try:
    from tasks import celery_app, run_scan_task, correlate_assets, validate_remediation_task, check_remediation_drift_task, cleanup_remediation_branches_task
except ImportError:
    # Some legacy unit tests inject a partial tasks module before importing app.py.
    # Keep app importable while preserving the real task module in normal runtime.
    import tasks as _tasks

    celery_app = getattr(_tasks, "celery_app", None)
    run_scan_task = getattr(_tasks, "run_scan_task", None)

    _CELERY_SETUP_HINT = (
        "Celery worker not running. "
        "Start Redis: `redis-server` and Celery: `celery -A tasks worker --loglevel=info`. "
        "Set CELERY_BROKER_URL=redis://localhost:6379/0 in your .env file."
    )

    def correlate_assets(*args, **kwargs):
        real = getattr(_tasks, "correlate_assets", None)
        if real is None:
            raise HTTPException(status_code=503, detail=_CELERY_SETUP_HINT)
        return real(*args, **kwargs)

    def validate_remediation_task(*args, **kwargs):
        real = getattr(_tasks, "validate_remediation_task", None)
        if real is None:
            raise HTTPException(status_code=503, detail=_CELERY_SETUP_HINT)
        return real(*args, **kwargs)

    def check_remediation_drift_task(*args, **kwargs):
        real = getattr(_tasks, "check_remediation_drift_task", None)
        if real is None:
            raise HTTPException(status_code=503, detail=_CELERY_SETUP_HINT)
        return real(*args, **kwargs)

    def cleanup_remediation_branches_task(*args, **kwargs):
        real = getattr(_tasks, "cleanup_remediation_branches_task", None)
        if real is None:
            raise HTTPException(status_code=503, detail=_CELERY_SETUP_HINT)
        return real(*args, **kwargs)
