def _asset_key_from_result(r: Dict[str, Any]) -> str:
    h = r.get("host") or r.get("hostname") or ""
    p = int(r.get("port") or 443)
    return asset_key(h, p)


def _finding_ids(r: Dict[str, Any]) -> set:
    out = set()
    for f in (r.get("findings") or []):
        fid = f.get("id")
        if fid:
            out.add(str(fid))
    return out


def _compute_asset_diff(current: Dict[str, Any], baseline: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    cur_ids = _finding_ids(current)
    base_ids = _finding_ids(baseline or {})
    new_ids = sorted(cur_ids - base_ids)
    resolved_ids = sorted(base_ids - cur_ids)
    unchanged_ids = sorted(cur_ids & base_ids)

    def pick(obj: Optional[Dict[str, Any]], keys: List[str], default=None):
        if not obj:
            return default
        for k in keys:
            if k in obj and obj.get(k) is not None:
                return obj.get(k)
        return default

    cur_score = pick(current, ["quantum_risk_score", "risk_score"], None)
    base_score = pick(baseline, ["quantum_risk_score", "risk_score"], None)

    cur_level = pick(current, ["quantum_risk_level", "risk", "risk_level"], "")
    base_level = pick(baseline, ["quantum_risk_level", "risk", "risk_level"], "")

    return {
        "host": current.get("host") or current.get("hostname") or "",
        "port": int(current.get("port") or 443),
        "baseline_present": bool(baseline),
        "current": {"score": cur_score, "level": cur_level},
        "baseline": {"score": base_score, "level": base_level},
        "score_delta": (cur_score - base_score) if (isinstance(cur_score, (int, float)) and isinstance(base_score, (int, float))) else None,
        "new_findings": new_ids,
        "resolved_findings": resolved_ids,
        "unchanged_findings": unchanged_ids,
    }


def _compute_scan_diff(current_scan: Dict[str, Any], baseline_scan: Dict[str, Any]) -> Dict[str, Any]:
    cur_results = current_scan.get("results") or []
    base_results = baseline_scan.get("results") or []

    cur_map = {_asset_key_from_result(r): r for r in cur_results}
    base_map = {_asset_key_from_result(r): r for r in base_results}

    assets = []
    for k, cur in cur_map.items():
        assets.append(_compute_asset_diff(cur, base_map.get(k)))

    total_assets = len(assets)
    total_new = sum(1 for a in assets if a["new_findings"])
    total_resolved = sum(1 for a in assets if a["resolved_findings"])
    total_changed = sum(1 for a in assets if (a["new_findings"] or a["resolved_findings"]))

    regressions = sorted(
        [a for a in assets if (a.get("score_delta") is not None and a["score_delta"] > 0)],
        key=lambda x: x["score_delta"],
        reverse=True,
    )[:25]
    improvements = sorted(
        [a for a in assets if (a.get("score_delta") is not None and a["score_delta"] < 0)],
        key=lambda x: x["score_delta"],
    )[:25]

    return {
        "scan_id": current_scan.get("id"),
        "baseline_scan_id": baseline_scan.get("id"),
        "generated_at": _now_iso(),
        "totals": {
            "assets": total_assets,
            "assets_changed": total_changed,
            "assets_with_new_findings": total_new,
            "assets_with_resolved_findings": total_resolved,
        },
        "top_regressions": regressions,
        "top_improvements": improvements,
        "assets": assets,
    }
def _init_otel() -> None:
    """Configure OpenTelemetry tracing when OTEL_EXPORTER_OTLP_ENDPOINT is set."""
    endpoint = str(os.getenv("OTEL_EXPORTER_OTLP_ENDPOINT", "")).strip()
    if not endpoint:
        return
    try:
        from opentelemetry import trace
        from opentelemetry.sdk.trace import TracerProvider
        from opentelemetry.sdk.trace.export import BatchSpanProcessor
        from opentelemetry.sdk.resources import Resource
        from opentelemetry.exporter.otlp.proto.grpc.trace_exporter import OTLPSpanExporter

        resource = Resource.create({
            "service.name": os.getenv("OTEL_SERVICE_NAME", "pqc-scanner"),
            "service.version": "0.6.0",
            "deployment.environment": os.getenv("PQC_ENVIRONMENT", "production"),
        })
        provider = TracerProvider(resource=resource)
        provider.add_span_processor(BatchSpanProcessor(OTLPSpanExporter(endpoint=endpoint)))
        trace.set_tracer_provider(provider)
        logging.getLogger("pqc.otel").info("OpenTelemetry tracing enabled ? %s", endpoint)
    except Exception as exc:
        logging.getLogger("pqc.otel").warning("OpenTelemetry init failed: %s", exc)


def _startup():
    _assert_production_startup_safe()
    _init_otel()
    init_db()
    try:
        ensure_vault_tables()
    except Exception as _vault_err:
        # Vault tables are Postgres-only. Silently skip when running SQLite-only (no DATABASE_URL).
        # The error text can echo connection strings or env values (a BOM-mangled .env line, an
        # invalid DSN); log it only after secrets are removed.
        logging.warning("[PQC VAULT] Vault table init skipped: %s", _redact_secrets(_vault_err))
    for w in _security_warnings():
        logging.warning("[PQC SECURITY] %s", w)


# ── DB helpers ───────────────────────────────────────────────────────────────
# Alias so legacy closing(get_db()) calls resolve to the same underlying fn.
get_db = get_connection


@contextmanager
def _db():
    """Yield a SQLite connection with row_factory=sqlite3.Row; always closes."""
    conn = get_connection()
    conn.row_factory = sqlite3.Row
    try:
        yield conn
    finally:
        conn.close()


@asynccontextmanager
async def _lifespan(_app: FastAPI):
    # ── Startup ───────────────────────────────────────────────
    # Reuse SQLite connections for the database this process serves (see db._PooledConnection).
    from db import disable_connection_pool, enable_connection_pool
    enable_connection_pool()
    _startup()
    _start_scheduler()  # in-process thread scheduler

    # Scan scheduler (Wave 14) + telemetry push helper
    from services.realtime_telemetry import push_event as _telemetry_push

    async def _push(org_id: str, event_type: str, data: dict):
        try:
            _telemetry_push(event_type=event_type, data=data, org_id=org_id)
        except Exception:
            pass

    def _run_scan_sync(host: str, port: int, org_id: str):
        try:
            return scan_host(host, port)
        except Exception:
            return None

    # _db, not get_db: the scheduler reads rows by column name (dict(row), row["interval_hours"]), which
    # needs sqlite3.Row, and `with get_connection()` only commits -- it never closed the connection.
    start_scheduler(_db, _run_scan_sync, _push)

    # Wave 15 table init
    with _db() as _db15:
        _tick_init(_db15)
        _sla_init(_db15)
        _wh_init(_db15)
        _kms_init(_db15)
        _pol_init(_db15)

    # Wave 17 table init + Drift Sentinel
    with _db() as _db17:
        _drift_init(_db17)
        _cbomwh_init(_db17)
        _push_init(_db17)
        _issuer_init(_db17)

    _drift_start(_db, _push)

    async def maintain_security_journal():
        # One bounded 5,000-row batch per 60-second tick is a ceiling of 5,000 rows a minute, which
        # is below the rate a mid-size customer base writes them at: the journal grew while
        # retention was configured, and a retention change or an older restore took most of a day
        # to drain (docs/LOAD_TEST_REPORT.md section 6). prune() now drains inside a time budget
        # and says whether anything expired is still there; while it is, come straight back.
        while True:
            backlog = False
            try:
                result = await run_in_threadpool(_security_journal.prune)
                backlog = bool((result or {}).get("backlog"))
            except Exception:
                _security_journal.mark_failure("retention")
            await asyncio.sleep(1 if backlog else 60)

    async def maintain_ai_receipts():
        while True:
            try:
                offset = 0
                while True:
                    organizations = await run_in_threadpool(list_organizations, limit=500, offset=offset)
                    for organization in organizations:
                        await run_in_threadpool(_ai_privacy.prune, str(organization["id"]))
                    if len(organizations) < 500:
                        break
                    offset += len(organizations)
            except Exception:
                logging.warning("AI receipt retention maintenance unavailable; retrying in 60 seconds")
            await asyncio.sleep(60)

    ai_receipt_maintenance = asyncio.create_task(maintain_ai_receipts())
    journal_maintenance = asyncio.create_task(maintain_security_journal())
    # Daily usage rollups: backfill on start, then roll newly closed days (PQC_USAGE_ROLLUP_INTERVAL_SECONDS).
    usage_rollup_task = asyncio.create_task(_usage_rollups.maintain(run_in_threadpool))
    # Admin analytics overview: precomputed into platform_analytics_snapshots on a schedule, one
    # range at a time, so the dashboard is served from storage instead of aggregating the whole
    # request journal while an operator waits (services/analytics_snapshots).
    analytics_snapshot_task = asyncio.create_task(_analytics_snapshots.maintain(run_in_threadpool))
    _platform_analytics.WARM_ENABLED = True
    # Operator alert routing: sends new platform notifications to configured channels every 60 s.
    _alert_routing.start(_alert_notifications_snapshot, lambda: _invite_links.base_url(None))

    try:
        yield
    finally:
        _platform_analytics.WARM_ENABLED = False
        await _alert_routing.stop()
        ai_receipt_maintenance.cancel()
        journal_maintenance.cancel()
        usage_rollup_task.cancel()
        analytics_snapshot_task.cancel()
        for task in (ai_receipt_maintenance, journal_maintenance, usage_rollup_task, analytics_snapshot_task):
            try:
                await task
            except asyncio.CancelledError:
                pass
        # ── Shutdown ──────────────────────────────────────────
        _stop_scheduler()
        stop_scheduler()
        _drift_stop()
        _security_journal.flush_pending()
        _audit_queue.drain()  # never leave a queued audit entry unwritten at shutdown
        disable_connection_pool()


