_LANDING_HTML_PATH = os.path.join(BASE_DIR, "static", "landing.html")
_NOT_FOUND_HTML_PATH = os.path.join(BASE_DIR, "static", "404.html")
_API_PATH_PREFIXES = ("/v1/", "/api/", "/platform/", "/auth/", "/webhooks/")


@app.exception_handler(StarletteHTTPException)
async def _not_found_page_handler(request: Request, exc: StarletteHTTPException):
    """A browser asking for a page that does not exist gets the 404 page.

    Only a 404, only when the client asks for HTML, and never under an API
    prefix: API clients and tests keep the standard JSON error body.
    """
    path = request.url.path or ""
    wants_html = "text/html" in (request.headers.get("accept") or "")
    if exc.status_code == 404 and wants_html and not path.startswith(_API_PATH_PREFIXES) and os.path.exists(_NOT_FOUND_HTML_PATH):
        from fastapi.responses import HTMLResponse
        with open(_NOT_FOUND_HTML_PATH, encoding="utf-8") as handle:
            return HTMLResponse(handle.read(), status_code=404)
    return await _default_http_exception_handler(request, exc)


@app.exception_handler(_pg_pool.PoolError)
async def _pool_exhausted_handler(request: Request, exc: _pg_pool.PoolError):
    """A full Postgres pool is congestion, not a server fault: answer 503, not 500.

    db_postgres._getconn_waiting already waits PQC_PG_POOL_ACQUIRE_TIMEOUT for a connection, so
    reaching here means the database work in flight genuinely exceeds the pool for longer than
    that. A 503 with Retry-After tells a client to back off; a 500 invites it to retry at once
    and deepen the queue.
    """
    logger.warning("postgres pool exhausted serving %s %s", request.method, request.url.path)
    return JSONResponse(
        status_code=503,
        content={"detail": "The service is busy; the database connection pool is saturated. Retry shortly."},
        headers={"Retry-After": "2"},
    )


