@app.get("/robots.txt", include_in_schema=False)
def robots_txt(request: Request):
    """static/robots.txt, with the Sitemap line resolved to an absolute URL.

    The rules live in the file so they can be read and edited like any other content. The one line
    that cannot is Sitemap: the standard requires an absolute URL there, and a relative one is
    silently ignored by every crawler -- so the file holds a relative placeholder and this route
    expands it against the deployment's own hostname.
    """
    from fastapi.responses import Response as _Response
    from services.public_config import public_base_url

    path = os.path.join(BASE_DIR, "static", "robots.txt")
    try:
        with open(path, "r", encoding="utf-8") as handle:
            body = handle.read()
    except OSError:
        # Never 500 on robots.txt: a crawler that cannot read it may treat the whole site as
        # disallowed. An empty allow-all is the safe answer.
        body = "User-agent: *\n"
    base = (public_base_url() or str(request.base_url)).rstrip("/")
    body = body.replace("Sitemap: /sitemap.xml", f"Sitemap: {base}/sitemap.xml")
    return _Response(body, media_type="text/plain",
                     headers={"Cache-Control": "public, max-age=3600"})


#: The public pages worth crawling, with a crawl priority. Everything behind a login is excluded by
#: robots.txt and would be useless in a sitemap anyway. The registry's own records are not listed
#: here: there can be very many of them, they need sharding and a lastmod per record, and that is
#: docs/PUBLIC_REGISTRY_DESIGN.md step 4.
_SITEMAP_PAGES = (
    ("/", "1.0", "weekly"),
    ("/check", "0.9", "weekly"),
    ("/trial", "0.8", "monthly"),
    ("/pricing", "0.7", "monthly"),
    ("/security", "0.7", "monthly"),
    ("/airlock-deployment", "0.6", "monthly"),
    ("/data-boundary", "0.6", "monthly"),
    ("/pilot", "0.5", "monthly"),
    ("/public-check/terms", "0.4", "yearly"),
    ("/public-check/acceptable-use", "0.4", "yearly"),
    ("/public-check/privacy", "0.4", "yearly"),
    ("/abuse", "0.5", "yearly"),
    ("/scanner", "0.5", "yearly"),
    ("/terms", "0.3", "yearly"),
    ("/privacy", "0.3", "yearly"),
    ("/dpa", "0.3", "yearly"),
    ("/support", "0.4", "monthly"),
)


@app.get("/sitemap.xml", include_in_schema=False)
def sitemap_xml(request: Request):
    """The public pages, as absolute URLs.

    A sitemap needs absolute URLs, and the host they name has to be the canonical one. It comes
    from PQC_PUBLIC_BASE_URL when configured, because that is the hostname the deployment calls
    itself and the one every canonical link and badge URL already uses. Falling back to the
    request's own base URL means an unconfigured deployment still answers correctly, but a request
    arriving on a second hostname would then advertise that one -- which is why the configured
    value wins.
    """
    from fastapi.responses import Response as _Response
    from services.public_config import public_base_url

    base = (public_base_url() or str(request.base_url)).rstrip("/")
    entries = "".join(
        f"<url><loc>{base}{path}</loc>"
        f"<changefreq>{changefreq}</changefreq><priority>{priority}</priority></url>"
        for path, priority, changefreq in _SITEMAP_PAGES
    )
    body = ('<?xml version="1.0" encoding="UTF-8"?>'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
            f"{entries}</urlset>")
    return _Response(body, media_type="application/xml",
                     headers={"Cache-Control": "public, max-age=3600"})


