# -----------------------------
# Sprint 5: simple in-process scheduler
# -----------------------------

_SCHED_STOP = threading.Event()
_SCHED_THREAD: Optional[threading.Thread] = None

_BROKER_PROBE_TTL_SECONDS = 15.0
_broker_probe = {"at": 0.0, "ok": False}


def _broker_reachable(timeout: float = 0.75) -> bool:
    """Fast pre-flight on the Celery broker.

    Celery's own reconnect budget takes roughly 100 seconds to surface an unreachable broker, which
    would make POST /scans look like it had hung before falling back to the in-process worker. A
    short TCP connect answers the same question in milliseconds. The result is cached briefly so a
    burst of scans does not re-probe on every request.
    """
    import socket

    now = time.monotonic()
    if now - _broker_probe["at"] < _BROKER_PROBE_TTL_SECONDS:
        return bool(_broker_probe["ok"])

    # Mirror tasks.py: CELERY_BROKER_URL, else REDIS_URL, else Celery's localhost default.
    url = str(
        os.getenv("CELERY_BROKER_URL") or os.getenv("REDIS_URL") or "redis://localhost:6379/0"
    ).strip()
    ok = False
    try:
        parsed = urllib.parse.urlparse(url)
        host = parsed.hostname or "127.0.0.1"
        port = int(parsed.port or 6379)
        with socket.create_connection((host, port), timeout=timeout):
            ok = True
    except Exception:
        ok = False

    _broker_probe["at"] = now
    _broker_probe["ok"] = ok
    return ok


def _create_scan_and_start(targets: List[str], source: str = "manual", collection_id: Optional[int] = None) -> Dict[str, Any]:
    # normalize and cap
    targets = [t.strip() for t in (targets or []) if t and t.strip()]
    if not targets:
        raise HTTPException(status_code=400, detail="No targets provided.")
    if len(targets) > MAX_TARGETS:
        raise HTTPException(status_code=400, detail=f"Too many targets (max {MAX_TARGETS}).")
    for t in targets:
        if len(t) > MAX_TARGET_LEN:
            raise HTTPException(status_code=400, detail=f"Invalid target: {t[:80]}")

    scan_id = str(uuid.uuid4())
    created_at = _utc_now()
    prog = _progress(len(targets), 0)

    scan = {
        "id": scan_id,
        "status": "running",
        "created_at": created_at,
        "progress": prog,
        "error": "",
        "results": [],
        "summary": {},
        "meta": {"source": source, "collection_id": collection_id},
    }
    _cache_put(scan)

    save_scan_row(
        scan_id=scan_id,
        status="running",
        created_at=created_at,
        progress=prog,
        error_text="",
        results=[],
        summary={},
    )

    org_id = current_organization_id()
    t = threading.Thread(target=_scan_worker, args=(scan_id, targets, org_id), daemon=True)
    t.start()

    return {"id": scan_id, "status": "running", "created_at": _format_utc_z(created_at)}


def _scheduler_loop():
    # Runs forever, triggers collection scans when due.
    while not _SCHED_STOP.is_set():
        try:
            now = _now_iso()
            for sch in due_schedules(now):
                # load targets from collection
                col = get_collection(int(sch["collection_id"]))
                targets_text = (col.get("targets_text") or "").strip()
                targets = [ln.strip() for ln in targets_text.splitlines() if ln.strip()]

                created = _create_scan_and_start(targets, source="schedule", collection_id=int(sch["collection_id"]))
                mark_schedule_ran(int(sch["id"]), now, int(sch["interval_minutes"]), created["id"])
        except Exception as _sched_exc:
            logging.error("[SCHEDULER] Error in scheduled scan tick: %s", _sched_exc, exc_info=True)

        _SCHED_STOP.wait(10.0)

def _start_scheduler():
    global _SCHED_THREAD
    try:
        # Sprint 9.9: Single Scheduler Authority
        # In Docker, ONLY celery beat should drive schedules. When WORKER_ROLE is set
        # (api/worker/beat), disable the legacy in-process scheduler loop.
        if os.getenv("WORKER_ROLE"):
            return
        if os.getenv("PYTEST_CURRENT_TEST"):
            return
        if _SCHED_THREAD and _SCHED_THREAD.is_alive():
            return
        _SCHED_THREAD = threading.Thread(target=_scheduler_loop, daemon=True)
        _SCHED_THREAD.start()
    except Exception as _start_exc:
        logging.error("[SCHEDULER] Failed to start scheduler thread: %s", _start_exc, exc_info=True)

def _stop_scheduler():
    _SCHED_STOP.set()


def _jwt_token_from_auth_header(auth_header: str) -> str:
    raw = str(auth_header or "").strip()
    if not raw.lower().startswith("bearer "):
        return ""
    return raw.split(" ", 1)[1].strip()


def _b64url_decode(segment: str) -> bytes:
    raw = str(segment or "")
    raw += "=" * (-len(raw) % 4)
    return base64.urlsafe_b64decode(raw.encode("utf-8"))


def _jwt_parts(token: str) -> Dict[str, Any]:
    raw = str(token or "").strip()
    parts = raw.split(".")
    if len(parts) != 3:
        raise ValueError("jwt must contain exactly 3 segments")
    header_obj = json.loads(_b64url_decode(parts[0]).decode("utf-8", errors="replace") or "{}")
    payload_obj = json.loads(_b64url_decode(parts[1]).decode("utf-8", errors="replace") or "{}")
    return {
        "header": header_obj if isinstance(header_obj, dict) else {},
        "payload": payload_obj if isinstance(payload_obj, dict) else {},
        "signature": _b64url_decode(parts[2]),
        "signing_input": f"{parts[0]}.{parts[1]}".encode("utf-8"),
    }


def _claim_value(payload: Dict[str, Any], path: str) -> Any:
    current: Any = payload
    for part in [str(x or "").strip() for x in str(path or "").split(".") if str(x or "").strip()]:
        if not isinstance(current, dict):
            return None
        current = current.get(part)
    return current


def _jwt_payload_from_auth_header(auth_header: str) -> Dict[str, Any]:
    token = _jwt_token_from_auth_header(auth_header)
    if not token:
        return {}
    try:
        parts = _jwt_parts(token)
        return parts["payload"] if isinstance(parts["payload"], dict) else {}
    except Exception:
        return {}


def _auth_public_path(path: str) -> bool:
    p = str(path or "").strip() or "/"
    if p in _PUBLIC_INFO_PAGES:
        return True
    # /status is documented as "suitable for a public/internal status page" and deliberately reports
    # nothing beyond api ok/degraded and database ok/degraded -- no versions, no DSNs, no component
    # detail (that is /health/deep, which stays authenticated). It was not listed here, so the one
    # endpoint built to be publicly reachable answered 401 on every hardened deployment.
    if p in {
        "/",
        "/status",
        "/health",
        "/healthz",
        "/robots.txt",
        "/favicon.ico",
        "/favicon.svg",
        "/docs",
        "/openapi.json",
        "/redoc",
        "/launch",
        "/landing",
        "/security",
        "/privacy",
        "/terms",
        "/support",
        "/trust-passport-demo",
        "/enterprise-admin",
        "/admin-page",
        "/auth/access-policy",
        # Operator sign-in bootstrap: what the admin sign-in screen offers, and ending a cookie session.
        "/platform/auth-config",
        "/platform/session/logout",
        # Invitation landing page and its token preview (rate limited; returns only a masked summary).
        "/invite",
        "/auth/invite/preview",
        # Console banner source. Anonymous callers only see notices addressed to everyone.
        "/announcements/active",
    }:
        return True
    if p == "/auth/config":
        return True
    # The free public readiness checker: the page at /check and /check/{domain}, and its
    # unauthenticated API. It is the project's shop window, so it has to answer without a login.
    # Exempt from the customer auth gate and from the per-organization limiter (it has no
    # organization), but not from the per-IP limiter, and not from its own guardrails: the opt-out
    # list, the SSRF guard, the per-IP/per-domain/global check budgets, the bounded queue and the
    # cache all live in services/public_check.py and run on every call. has_prefix is used rather
    # than startswith so /v1/check and /CHECK reach the same decision as /check does. The operator
    # routes under /platform/public-check are deliberately NOT here.
    # /r/{domain} is the permanent public record the checker writes. Same reasoning, and the same
    # guardrails: it is read-only, it reads stored data, and nothing under it can start a check.
    # has_prefix compares whole segments, so "/r" here does not also claim /repositories or
    # /robots.txt the way a startswith would.
    #
    # /trial-request is how a stranger asks for an account. It must answer without a login for the
    # obvious reason, and it grants nothing: it writes one pending row that a person has to act on.
    if _route_paths.has_prefix(p, ("/check", "/api/public-check", "/r", "/trial-request",
                                   "/api/trial-request")):
        return True
    if p.startswith("/vendor-admin"):
        return True
    # Credential-exchange endpoints must be reachable without a bearer token, otherwise there is no
    # way to obtain one: with PQC_AUTH_REQUIRED=1 the middleware would answer /auth/login itself
    # with 401 "missing bearer token". Each of these authenticates from its own request payload
    # (password, or an opaque refresh token that is hashed and looked up), and each is rate-limited
    # by _RATE_AUTH. /auth/register is deliberately NOT here — it creates accounts and must stay
    # behind admin authorization.
    if p in {"/auth/login", "/auth/refresh", "/auth/logout"}:
        return True
    if p == "/auth/support-session/exchange":  # the one-time launch code is the credential
        return True
    if p.startswith("/auth/saml"):
        return True
    if p.startswith("/auth/oidc"):
        return True
    if p.startswith("/ui"):
        return True
    if p.startswith("/vendor-attestation/"):
        return True
    if p == "/integrations/github/webhook":
        return True
    return False


# Role names and the credential model live in services/platform_operators.py. A missing role header
# no longer means owner: shared-key callers get the least-privileged role unless they ask for more
# (within the key's ceiling), named operators get the role bound to their key, and an unknown role
# name is a 400 rather than a silent owner.
_PLATFORM_ADMIN_ROLE_ALIASES = dict(_platform_operators.ROLE_ALIASES)
_PLATFORM_ADMIN_READ_ROLES = set(_platform_operators.READ_ROLES)
_PLATFORM_ADMIN_WRITE_ROLES = set(_platform_operators.WRITE_ROLES)
_PLATFORM_ADMIN_OWNER_ROLES = set(_platform_operators.OWNER_ROLES)


def _platform_admin_role_from_request(request: Request) -> str:
    """Best-effort label for monitoring only; authorization is decided in _require_platform_admin."""
    return (_platform_operators.normalize_role(request.headers.get("x-platform-admin-role"))
            or _platform_operators.LEAST_PRIVILEGED_ROLE)


def _platform_admin_actor_from_request(request: Request) -> Dict[str, str]:
    credential = _platform_operators.resolve_credential(
        str(request.headers.get("x-platform-key") or ""), _PLATFORM_ADMIN_KEY
    )
    role = _platform_admin_role_from_request(request)
    if credential:
        try:
            role = _platform_operators.effective_role(credential, request.headers.get("x-platform-admin-role"))
        except _platform_operators.RoleError:
            role = _platform_operators.LEAST_PRIVILEGED_ROLE
    return {
        "actor_id": credential["name"] if credential else _platform_operators.LEGACY_OPERATOR_NAME,
        "actor_role": role,
    }


def _platform_key_authenticates(request: Request) -> bool:
    """True when a request carries a valid platform admin key for a /platform/* path.

    The platform key is a standalone vendor-operator credential, deliberately separate from user
    roles -- it is what the vendor admin portal and scripts/check-go-live-gate.ps1 present, and they
    have no user token to offer. But /platform/* is not an auth-public path, so with
    PQC_AUTH_REQUIRED=1 -- the setting the hardening guide prescribes -- the middleware answered
    every one of those requests with 401 before the endpoint's own key check ever ran. The go-live
    gate was unreachable on precisely the configuration it exists to certify, and the admin portal
    was unusable in production.

    This does not widen access: the path must be under /platform/, the key must be configured, and
    the presented value must match it under a constant-time comparison. Requests without a valid key
    still get the 401 they did before, and the endpoint's own _require_platform_admin still runs
    (enforcing production key length and the query-string ban).
    """
    # The canonical path, so /v1/platform/... and /platform//... reach the same decision as
    # /platform/... does -- the router collapses those spellings onto the same handler.
    if not _route_paths.has_prefix(request.url.path, ("/platform",)):
        return False
    provided = str(request.headers.get("x-platform-key") or "").strip()
    if not provided:
        # An operator SSO session cookie; the endpoint guard repeats the full check (CSRF, MFA, role).
        raw_session = _operator_auth.session_cookie(request)
        try:
            return bool(raw_session) and _operator_auth.session_valid_cached(raw_session)
        except Exception:
            return False
    # resolve_credential compares UTF-8 bytes (compare_digest raises TypeError on non-ASCII str, which
    # from the middleware would turn "x-platform-key: café" into a 500) and checks both the legacy
    # shared key and named operator key hashes in constant time.
    if not _platform_operators.resolve_credential(provided, _PLATFORM_ADMIN_KEY):
        return False
    actor = _platform_admin_actor_from_request(request)
    request.state.actor_id = actor["actor_id"]
    request.state.actor_role = actor["actor_role"]
    return True


def _public_auth_config() -> Dict[str, Any]:
    return {
        "mode": AUTH_MODE,
        "required": bool(AUTH_REQUIRED),
        "provider_name": AUTH_PROVIDER_NAME,
        "login_url": AUTH_LOGIN_URL,
        "logout_url": AUTH_LOGOUT_URL,
        "token_help": AUTH_TOKEN_HELP,
        "bearer_token_supported": AUTH_MODE == "jwt",
        "manual_actor_supported": AUTH_MODE != "jwt" or not AUTH_REQUIRED,
        "password_login_enabled": bool(AUTH_ISSUER_ENABLED),
    }


