# ---------------------------------------------------------------------------
# SAML 2.0 SSO endpoints
# ---------------------------------------------------------------------------
# Platform Admin — cross-org visibility for the SaaS operator
# Protected by PQC_PLATFORM_ADMIN_KEY env var (must match x-platform-key header)
# ---------------------------------------------------------------------------

_PLATFORM_ADMIN_KEY = os.getenv("PQC_PLATFORM_ADMIN_KEY", "").strip()
_PLATFORM_ADMIN_MIN_KEY_LENGTH = int(os.getenv("PQC_PLATFORM_ADMIN_MIN_KEY_LENGTH", "32") or "32")
_ALLOW_PLATFORM_KEY_QUERY = str(os.getenv("PQC_ALLOW_PLATFORM_KEY_QUERY", "0") or "0").strip().lower() in {"1", "true", "yes", "on"}
_ALLOW_DEMO_IN_PRODUCTION = str(os.getenv("PQC_ALLOW_DEMO_IN_PRODUCTION", "0") or "0").strip().lower() in {"1", "true", "yes", "on"}
_FEATURE_FLAGS_STRICT = str(os.getenv("PQC_FEATURE_FLAGS_STRICT", "0") or "0").strip().lower() in {"1", "true", "yes", "on"}
_ORG_STATUS_CACHE: Dict[str, Any] = {"expires_at": 0.0, "statuses": {}}


from services import operator_auth as _operator_auth  # noqa: E402


def _require_platform_admin(request: Request, allowed_roles: Optional[set[str]] = None) -> Dict[str, str]:
    """Raise unless the request carries a valid platform credential and a role it is allowed to use.

    The role comes from the credential (services/platform_operators.py): a named operator key is
    bound to its role; the legacy shared key defaults to auditor and may request up to its ceiling.
    Unknown role names answer 400. The resolved operator is recorded on every admin audit event.
    Without a key header, an operator SSO session cookie is accepted (services/operator_auth.py:
    CSRF on writes, MFA elevation); the shared key is break-glass only in production/staging.
    """
    if (not str(request.headers.get("x-platform-key") or "").strip()
            and not str(request.query_params.get("platform_key") or "").strip()
            and _operator_auth.session_cookie(request)):
        session_actor = _operator_auth.require_session_actor(request, set(allowed_roles or _PLATFORM_ADMIN_READ_ROLES))
        # Same tail as the key path below, including enter_platform_scope. This branch used to
        # return here, so an operator signed in through SSO -- the credential the go-live gate
        # requires -- never opened the audited cross-tenant scope. On Postgres that operator's
        # console read nothing, and postgres_rls.operator_access_rule described a path that did not
        # exist. It failed closed, which is why nobody noticed: RLS was never exercised by it.
        return _accept_platform_operator(request, session_actor)
    if not _platform_operators.credentials_configured(_PLATFORM_ADMIN_KEY):
        raise HTTPException(
            status_code=503,
            detail="Platform admin endpoints are disabled. Set PQC_PLATFORM_ADMIN_KEY or PQC_PLATFORM_OPERATORS to enable.",
        )
    if PRODUCTION_ENVIRONMENT and _PLATFORM_ADMIN_KEY and len(_PLATFORM_ADMIN_KEY) < _PLATFORM_ADMIN_MIN_KEY_LENGTH:
        raise HTTPException(status_code=503, detail="Platform admin key is too short for production.")
    query_key = str(request.query_params.get("platform_key") or "").strip()
    if query_key and (PRODUCTION_ENVIRONMENT or not _ALLOW_PLATFORM_KEY_QUERY):
        raise HTTPException(status_code=403, detail="Platform admin key in query string is disabled.")
    provided = str(request.headers.get("x-platform-key") or (query_key if _ALLOW_PLATFORM_KEY_QUERY else "") or "").strip()
    credential = _platform_operators.resolve_credential(provided, _PLATFORM_ADMIN_KEY)
    if not credential:
        try:
            _RATE_LIMIT_OBSERVATIONS.append({
                "organization_id": "platform",
                "path": request.url.path,
                "source": "admin_auth_failed",
                "created_at": _now_iso(),
            })
        except Exception:
            pass
        raise HTTPException(status_code=403, detail="Invalid or missing platform admin key.")
    try:
        role = _platform_operators.effective_role(credential, request.headers.get("x-platform-admin-role"))
    except _platform_operators.RoleError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail) from None
    actor: Dict[str, Any] = {
        "actor_id": credential["name"],
        "actor_role": role,
        "ceiling_role": credential["ceiling_role"],
        "bound": bool(credential["bound"]),
        "credential_source": credential["source"],
    }
    if not credential["bound"]:
        claimed = _platform_operators.sanitize_claimed_user(request.headers.get("x-platform-admin-user"))
        if claimed:
            actor["claimed_user"] = claimed  # unverified: a shared key cannot prove who holds it
    request.state.platform_operator = actor
    _operator_auth.apply_key_policy(request, credential, actor, _record_platform_admin_event)
    allowed = set(allowed_roles or _PLATFORM_ADMIN_READ_ROLES)
    if role not in allowed:
        raise HTTPException(
            status_code=403,
            detail=f"Platform admin role '{role}' is not allowed for this operation.",
        )
    return _accept_platform_operator(request, actor)


def _accept_platform_operator(request: Request, actor: Dict[str, Any]) -> Dict[str, str]:
    """The last step of every accepted operator request, whatever credential it presented.

    Only here -- after the credential has been resolved AND the role has been accepted for this
    operation -- may this request read across tenants. Doing it here rather than in middleware is
    the point: an unauthenticated or wrongly-roled request to /platform/* has already raised, so it
    never reaches a connection with the escape hatch open. The scope lives in the request's own
    context and is gone when the response is sent; services/tenant_scope records every entry.

    Both the key path and the SSO-session path end here, so there is exactly one place where an
    operator becomes cross-tenant and exactly one ledger entry describing it.
    """
    role = str(actor.get("actor_role") or "")
    request.state.platform_operator = actor
    request.state.actor_id = actor["actor_id"]
    request.state.actor_role = role
    _platform_operators.CURRENT_OPERATOR.set(actor)
    _tenant_scope.enter_platform_scope(
        f"platform-admin {request.method} {_safe_audit_path(request)}",
        actor=f"{actor['actor_id']}/{role}",
    )
    return actor


def _customer_request_blocked_for_suspension(path: str, org_id: str) -> bool:
    """Block customer product routes for suspended tenants, while leaving public/admin routes available."""
    skip_prefixes = (
        "/health", "/docs", "/openapi.json", "/redoc", "/favicon.ico",
        "/ui", "/vendor-admin", "/platform", "/auth", "/webhooks",
    )
    if any(str(path or "").startswith(prefix) for prefix in skip_prefixes):
        return False
    now = time.time()
    try:
        if now >= float(_ORG_STATUS_CACHE.get("expires_at") or 0):
            statuses = {
                str(o.get("id") or ""): str(o.get("subscription_status") or "active").lower()
                for o in list_organizations(limit=2000)
            }
            _ORG_STATUS_CACHE["statuses"] = statuses
            _ORG_STATUS_CACHE["expires_at"] = now + 15
        return str((_ORG_STATUS_CACHE.get("statuses") or {}).get(str(org_id), "active")).lower() == "suspended"
    except Exception:
        return False


