def _ensure_platform_state_schema() -> None:
    global _PLATFORM_STATE_SCHEMA_READY
    if _PLATFORM_STATE_SCHEMA_READY:
        return
    if not postgres_main_db_requested():
        return
    with pg_product_conn() as conn, tolerate_missing_ddl_privilege(
        conn,
        ("platform_traffic_events", "platform_feature_state_records"),
        "platform state",
    ):
        with conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS platform_traffic_events (
                    id BIGSERIAL PRIMARY KEY,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    source_ip TEXT NOT NULL DEFAULT '',
                    ip_hash TEXT NOT NULL DEFAULT '',
                    organization_id TEXT NOT NULL DEFAULT '',
                    method TEXT NOT NULL DEFAULT '',
                    path TEXT NOT NULL DEFAULT '',
                    status_code INTEGER NOT NULL DEFAULT 0,
                    status_family TEXT NOT NULL DEFAULT '',
                    duration_ms DOUBLE PRECISION NOT NULL DEFAULT 0,
                    actor_role TEXT NOT NULL DEFAULT '',
                    actor_id TEXT NOT NULL DEFAULT '',
                    authenticated BOOLEAN NOT NULL DEFAULT FALSE,
                    user_agent TEXT NOT NULL DEFAULT '',
                    referrer_path TEXT NOT NULL DEFAULT '',
                    request_id TEXT NOT NULL DEFAULT '',
                    error TEXT NOT NULL DEFAULT ''
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS platform_feature_state_records (
                    id BIGSERIAL PRIMARY KEY,
                    source_table TEXT NOT NULL,
                    source_pk TEXT NOT NULL,
                    organization_id TEXT NOT NULL DEFAULT '',
                    payload_json JSONB NOT NULL DEFAULT '{}'::jsonb,
                    source_updated_at TEXT NOT NULL DEFAULT '',
                    migrated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (source_table, source_pk)
                )
                """
            )
            cur.execute("CREATE INDEX IF NOT EXISTS idx_platform_traffic_events_created ON platform_traffic_events(created_at)")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_platform_traffic_events_org ON platform_traffic_events(organization_id)")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_platform_traffic_events_ip_hash ON platform_traffic_events(ip_hash)")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_platform_state_records_table ON platform_feature_state_records(source_table)")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_platform_state_records_org ON platform_feature_state_records(organization_id)")
        conn.commit()
    _PLATFORM_STATE_SCHEMA_READY = True


def _persist_traffic_event(event: Dict[str, Any]) -> None:
    if not _TRAFFIC_PERSIST_TO_DB:
        return
    try:
        # Queued for the journal's background writer, which commits in batches. Writing one row per
        # request inline took a connection and SQLite's single write lock on every request, so under
        # a page's burst of parallel calls every request queued behind every other request's insert.
        _security_journal.enqueue_request(event)
    except _security_journal.JournalUnavailable:
        # Traffic remains available in the process buffer; the admin health view reports the gap.
        pass


def _sqlite_feature_state_tables() -> List[Dict[str, Any]]:
    try:
        with closing(get_connection()) as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                """
                SELECT name
                FROM sqlite_master
                WHERE type='table' AND name NOT LIKE 'sqlite_%'
                ORDER BY name
                """
            ).fetchall()
            out: List[Dict[str, Any]] = []
            for row in rows:
                name = str(row["name"] or "")
                count = 0
                try:
                    count = int(conn.execute(f"SELECT COUNT(*) FROM {name}").fetchone()[0] or 0)
                except Exception:
                    count = 0
                out.append({
                    "table": name,
                    "rows": count,
                    "state": "postgres_native" if name in _POSTGRES_NATIVE_OR_ARCHIVED_TABLES else "sqlite_auxiliary",
                    "postgres_archive_supported": name not in _POSTGRES_NATIVE_OR_ARCHIVED_TABLES,
                })
            return out
    except Exception as exc:
        return [{"table": "", "rows": 0, "state": "unavailable", "error": str(exc)[:180]}]


def _platform_state_coverage() -> Dict[str, Any]:
    tables = _sqlite_feature_state_tables()
    auxiliary = [t for t in tables if t.get("state") == "sqlite_auxiliary"]
    archived_count = 0
    if postgres_main_db_requested():
        try:
            _ensure_platform_state_schema()
            with pg_product_conn() as conn:
                with conn.cursor() as cur:
                    cur.execute("SELECT COUNT(*) FROM platform_feature_state_records")
                    archived_count = int(cur.fetchone()[0] or 0)
        except Exception:
            archived_count = 0
    return {
        "api_version": "v1",
        "generated_at": _platform_now_iso(),
        "postgres_mode": bool(postgres_main_db_requested()),
        "traffic_persistence_enabled": bool(_TRAFFIC_PERSIST_TO_DB),
        "sqlite_auxiliary_tables": auxiliary,
        "sqlite_auxiliary_table_count": len(auxiliary),
        "postgres_archive_records": archived_count,
        "scale_rule": (
            "Multiple API replicas are supported only when auxiliary SQLite tables are empty or "
            "archived/migrated and remaining SQLite state is on a shared persistent volume."
        ),
    }


def _migrate_sqlite_auxiliary_state_to_postgres(req: PlatformStateMigrationRequest) -> Dict[str, Any]:
    if not postgres_main_db_requested():
        raise HTTPException(status_code=409, detail="Postgres mode is required for auxiliary state migration.")
    _ensure_platform_state_schema()
    include = {str(t or "").strip() for t in req.include_tables if str(t or "").strip()}
    exclude = {str(t or "").strip() for t in req.exclude_tables if str(t or "").strip()}
    tables = [
        t["table"] for t in _sqlite_feature_state_tables()
        if t.get("state") == "sqlite_auxiliary"
        and (not include or t["table"] in include)
        and t["table"] not in exclude
    ]
    result: Dict[str, Any] = {
        "api_version": "v1",
        "generated_at": _platform_now_iso(),
        "dry_run": bool(req.dry_run),
        "tables": {},
        "copied": 0,
    }
    with closing(get_connection()) as src:
        src.row_factory = sqlite3.Row
        for table in tables:
            rows = src.execute(f"SELECT rowid AS __rowid__, * FROM {table} LIMIT ?", (int(req.limit_per_table),)).fetchall()
            result["tables"][table] = {"matched": len(rows), "copied": 0}
            if req.dry_run or not rows:
                continue
            payloads = []
            for row in rows:
                payload = {k: row[k] for k in row.keys() if k != "__rowid__"}
                source_pk = str(payload.get("id") or payload.get("key") or payload.get("token") or row["__rowid__"])
                org_id = str(payload.get("organization_id") or payload.get("org_id") or "").strip()
                updated_at = str(payload.get("updated_at") or payload.get("created_at") or "")
                payloads.append((table, source_pk, org_id, Json(payload), updated_at))
            with pg_product_conn() as dest:
                with dest.cursor() as cur:
                    for payload in payloads:
                        cur.execute(
                            """
                            INSERT INTO platform_feature_state_records (
                                source_table, source_pk, organization_id, payload_json, source_updated_at, migrated_at
                            )
                            VALUES (%s, %s, %s, %s, %s, NOW())
                            ON CONFLICT (source_table, source_pk) DO UPDATE SET
                                organization_id = EXCLUDED.organization_id,
                                payload_json = EXCLUDED.payload_json,
                                source_updated_at = EXCLUDED.source_updated_at,
                                migrated_at = NOW()
                            """,
                            payload,
                        )
                dest.commit()
            result["tables"][table]["copied"] = len(payloads)
            result["copied"] += len(payloads)
    return result


def _record_platform_admin_event(organization_id: str, action: str, reason: str = "", details: Optional[Dict[str, Any]] = None) -> None:
    _ensure_platform_admin_schema()
    details = dict(details or {})
    # Name the operator on every event: the guard for this request stored who it resolved.
    operator = _platform_operators.CURRENT_OPERATOR.get() or {}
    actor_id = str(operator.get("actor_id") or _platform_operators.LEGACY_OPERATOR_NAME)[:160]
    if operator:
        details.setdefault("operator", {
            k: operator.get(k) for k in ("actor_id", "actor_role", "ceiling_role", "credential_source", "claimed_user", "auth_method", "email")
            if operator.get(k) not in (None, "")
        })
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO platform_admin_events (organization_id, action, actor_id, reason, details_json, created_at)
                    VALUES (%s, %s, %s, %s, %s, NOW())
                    """,
                    (organization_id, action, actor_id, reason, Json(details)),
                )
            conn.commit()
        return
    with closing(get_connection()) as conn:
        conn.execute(
            "INSERT INTO platform_admin_events (organization_id, action, actor_id, reason, details_json, created_at) VALUES (?, ?, ?, ?, ?, ?)",
            (organization_id, action, actor_id, reason, json.dumps(details, separators=(",", ":"), default=str), _platform_now_iso()),
        )
        conn.commit()


def _platform_list_admin_events(organization_id: str = "", limit: int = 100) -> List[Dict[str, Any]]:
    _ensure_platform_admin_schema()
    lim = max(1, min(int(limit or 100), 500))
    if postgres_main_db_requested():
        params: List[Any] = []
        where = ""
        if organization_id:
            where = "WHERE organization_id = %s"
            params.append(organization_id)
        params.append(lim)
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    f"""
                    SELECT id, organization_id, action, actor_id, reason, details_json, created_at
                    FROM platform_admin_events
                    {where}
                    ORDER BY created_at DESC, id DESC
                    LIMIT %s
                    """,
                    params,
                )
                return [_json_safe(dict(r)) for r in cur.fetchall()]
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        params2: List[Any] = []
        where2 = ""
        if organization_id:
            where2 = "WHERE organization_id = ?"
            params2.append(organization_id)
        rows = conn.execute(
            f"SELECT * FROM platform_admin_events {where2} ORDER BY created_at DESC, id DESC LIMIT ?",
            (*params2, lim),
        ).fetchall()
        out = []
        for row in rows:
            item = dict(row)
            try:
                item["details_json"] = json.loads(item.get("details_json") or "{}")
            except Exception:
                item["details_json"] = {}
            out.append(item)
        return out


