def _platform_feature_flags(organization_id: str = "") -> List[Dict[str, Any]]:
    _ensure_platform_admin_schema()
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                if organization_id:
                    cur.execute("SELECT * FROM platform_feature_flags WHERE organization_id=%s ORDER BY flag_key", (organization_id,))
                else:
                    cur.execute("SELECT * FROM platform_feature_flags ORDER BY organization_id, flag_key")
                rows = cur.fetchall()
        return [_json_safe(dict(r)) for r in rows]
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        if organization_id:
            rows = conn.execute("SELECT * FROM platform_feature_flags WHERE organization_id=? ORDER BY flag_key", (organization_id,)).fetchall()
        else:
            rows = conn.execute("SELECT * FROM platform_feature_flags ORDER BY organization_id, flag_key").fetchall()
        out = []
        for row in rows:
            item = dict(row)
            item["enabled"] = bool(item.get("enabled"))
            out.append(item)
        return out


def _upsert_platform_feature_flag(organization_id: str, req: PlatformFeatureFlagRequest) -> Dict[str, Any]:
    _ensure_platform_admin_schema()
    org_id = str(organization_id or "").strip()
    flag = re.sub(r"[^a-zA-Z0-9_.:-]+", "_", str(req.flag_key or "").strip())[:120]
    if not org_id or not flag:
        raise HTTPException(status_code=400, detail="organization_id and flag_key are required.")
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    """
                    INSERT INTO platform_feature_flags (organization_id, flag_key, enabled, reason, updated_at)
                    VALUES (%s, %s, %s, %s, NOW())
                    ON CONFLICT (organization_id, flag_key) DO UPDATE SET
                        enabled=EXCLUDED.enabled, reason=EXCLUDED.reason, updated_at=NOW()
                    RETURNING *
                    """,
                    (org_id, flag, bool(req.enabled), str(req.reason or "")[:500]),
                )
                row = cur.fetchone()
            conn.commit()
        return _json_safe(dict(row))
    now = _platform_now_iso()
    with closing(get_connection()) as conn:
        conn.execute(
            """
            INSERT INTO platform_feature_flags (organization_id, flag_key, enabled, reason, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(organization_id, flag_key) DO UPDATE SET
                enabled=excluded.enabled, reason=excluded.reason, updated_at=excluded.updated_at
            """,
            (org_id, flag, int(bool(req.enabled)), str(req.reason or "")[:500], now),
        )
        row = conn.execute("SELECT * FROM platform_feature_flags WHERE organization_id=? AND flag_key=?", (org_id, flag)).fetchone()
        conn.commit()
    item = dict(row)
    item["enabled"] = bool(item.get("enabled"))
    return item


def _feature_enabled_for_org(organization_id: str, flag_key: str, default: bool = True) -> bool:
    """Tenant feature kill-switch. Strict mode requires an explicit enabled flag."""
    org_id = str(organization_id or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    flag = re.sub(r"[^a-zA-Z0-9_.:-]+", "_", str(flag_key or "").strip())[:120]
    if not flag:
        return False
    try:
        for item in _platform_feature_flags(org_id):
            if str(item.get("flag_key") or "") == flag:
                return bool(item.get("enabled"))
    except Exception:
        if _FEATURE_FLAGS_STRICT:
            return False
    return bool(default and not _FEATURE_FLAGS_STRICT)


def _require_org_feature(organization_id: str, flag_key: str, action: str = "this action") -> None:
    if not _feature_enabled_for_org(organization_id, flag_key):
        raise HTTPException(
            status_code=403,
            detail=f"{action} is disabled for this organization by feature flag '{flag_key}'.",
        )


def _retention_cutoff_iso(days: int) -> str:
    return (datetime.now(timezone.utc) - timedelta(days=int(days))).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _run_platform_retention(req: PlatformRetentionRunRequest) -> Dict[str, Any]:
    plans = [
        ("scans", "created_at", req.scans_days),
        ("scan_results", "scanned_at", req.scan_results_days),
        ("validation_jobs", "created_at", req.validation_jobs_days),
        ("webhook_events", "created_at", req.webhook_events_days),
        ("login_events", "created_at", req.login_events_days),
        ("platform_admin_events", "created_at", req.platform_admin_events_days),
    ]
    results: List[Dict[str, Any]] = []
    limit = int(req.limit or 5000)
    _ensure_platform_admin_schema()
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor() as cur:
                for table, column, days in plans:
                    cutoff = _retention_cutoff_iso(days)
                    try:
                        cur.execute(f"SELECT COUNT(*) FROM {table} WHERE {column} < %s", (cutoff,))
                        count = int((cur.fetchone() or [0])[0] or 0)
                        deleted = 0
                        if not req.dry_run and count:
                            cur.execute(
                                f"""
                                DELETE FROM {table}
                                WHERE ctid IN (
                                    SELECT ctid FROM {table}
                                    WHERE {column} < %s
                                    LIMIT %s
                                )
                                """,
                                (cutoff, limit),
                            )
                            deleted = int(cur.rowcount or 0)
                        results.append({"table": table, "column": column, "days": days, "cutoff": cutoff, "matched": count, "deleted": deleted})
                    except Exception as exc:
                        results.append({"table": table, "column": column, "days": days, "error": str(exc)[:240]})
            if not req.dry_run:
                conn.commit()
    else:
        with closing(get_connection()) as conn:
            for table, column, days in plans:
                cutoff = _retention_cutoff_iso(days)
                try:
                    row = conn.execute(f"SELECT COUNT(*) FROM {table} WHERE datetime({column}) < datetime(?)", (cutoff,)).fetchone()
                    count = int((row[0] if row else 0) or 0)
                    deleted = 0
                    if not req.dry_run and count:
                        cur = conn.execute(
                            f"""
                            DELETE FROM {table}
                            WHERE rowid IN (
                                SELECT rowid FROM {table}
                                WHERE datetime({column}) < datetime(?)
                                LIMIT ?
                            )
                            """,
                            (cutoff, limit),
                        )
                        deleted = int(cur.rowcount or 0)
                    results.append({"table": table, "column": column, "days": days, "cutoff": cutoff, "matched": count, "deleted": deleted})
                except Exception as exc:
                    results.append({"table": table, "column": column, "days": days, "error": str(exc)[:240]})
            if not req.dry_run:
                conn.commit()
    results.append({
        "table": "audit_logs",
        "column": "created_at",
        "matched": 0,
        "deleted": 0,
        "skipped": "Audit logs are append-only evidence and are not deleted by this retention job.",
    })
    return {
        "api_version": "v1",
        "generated_at": _platform_now_iso(),
        "dry_run": bool(req.dry_run),
        "limit_per_table": limit,
        "items": results,
    }


def _platform_customer_stats() -> List[Dict[str, Any]]:
    _ensure_platform_admin_schema()
    actual_logins = _security_journal.customer_login_stats()
    if not postgres_main_db_requested():
        notes = _platform_notes_by_org()
        out = platform_customer_stats()
        for c in out:
            c.update(notes.get(str(c.get("organization_id") or ""), {}))
            c.update(actual_logins.get(c["organization_id"], {"last_login_at": None, "active_users_7d": 0}))
            c.pop("last_login_user", None)
            c["risk_score"] = _platform_customer_risk_score(c)
        return out

    with pg_product_conn() as conn:
        with conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute(
                """
                SELECT
                    o.id AS organization_id,
                    o.name,
                    o.plan_type,
                    o.subscription_status,
                    o.created_at,
                    o.updated_at,
                    COALESCE(sc.scan_count, 0) AS scan_count,
                    COALESCE(a.asset_count, 0) AS asset_count,
                    COALESCE(r.remediation_count, 0) AS remediation_count,
                    COALESCE(u.user_count, 0) AS user_count,
                    ls.last_scan_at,
                    ll.last_login_at,
                    ll.last_login_user,
                    COALESCE(au.active_users_7d, 0) AS active_users_7d,
                    COALESCE(n.internal_notes, '') AS internal_notes,
                    COALESCE(n.lifecycle_stage, '') AS lifecycle_stage,
                    COALESCE(n.renewal_at, '') AS renewal_at,
                    COALESCE(n.account_owner, '') AS account_owner
                FROM organizations o
                LEFT JOIN (SELECT organization_id, COUNT(*) AS scan_count FROM scans GROUP BY organization_id) sc ON sc.organization_id = o.id
                LEFT JOIN (SELECT organization_id, COUNT(*) AS asset_count FROM assets GROUP BY organization_id) a ON a.organization_id = o.id
                LEFT JOIN (SELECT organization_id, COUNT(*) AS remediation_count FROM remediations GROUP BY organization_id) r ON r.organization_id = o.id
                LEFT JOIN (SELECT organization_id, COUNT(*) AS user_count FROM organization_memberships GROUP BY organization_id) u ON u.organization_id = o.id
                LEFT JOIN (SELECT organization_id, MAX(created_at) AS last_scan_at FROM scans GROUP BY organization_id) ls ON ls.organization_id = o.id
                LEFT JOIN (
                    SELECT DISTINCT ON (organization_id)
                        organization_id, created_at AS last_login_at, actor_id AS last_login_user
                    FROM audit_logs
                    WHERE action = 'user.login'
                    ORDER BY organization_id, created_at DESC
                ) ll ON ll.organization_id = o.id
                LEFT JOIN (
                    SELECT organization_id, COUNT(DISTINCT actor_id) AS active_users_7d
                    FROM audit_logs
                    WHERE action = 'user.login' AND created_at >= NOW() - INTERVAL '7 days'
                    GROUP BY organization_id
                ) au ON au.organization_id = o.id
                LEFT JOIN platform_customer_notes n ON n.organization_id = o.id
                ORDER BY o.updated_at DESC
                LIMIT 1000
                """
            )
            rows = [_json_safe(dict(r)) for r in cur.fetchall()]
    for c in rows:
        c.update(actual_logins.get(c["organization_id"], {"last_login_at": None, "active_users_7d": 0}))
        c.pop("last_login_user", None)
        c["risk_score"] = _platform_customer_risk_score(c)
    return rows


def _platform_login_events(organization_id: str = "", user_id: str = "", limit: int = 200, since_iso: str = "") -> List[Dict[str, Any]]:
    return _security_journal.auth_events(organization_id=organization_id, user_id=user_id,
                                         limit=limit, since_iso=since_iso, successful_logins=True)


def _platform_customer_risk_score(c: Dict[str, Any]) -> int:
    score = 0
    if not c.get("last_login_at"):
        score += 35
    if int(c.get("scan_count") or 0) == 0:
        score += 30
    if int(c.get("active_users_7d") or 0) == 0:
        score += 20
    if str(c.get("subscription_status") or "").lower() in {"suspended", "archived", "past_due"}:
        score += 15
    return min(score, 100)


def _platform_upsert_notes(organization_id: str, req: PlatformCustomerUpdateRequest) -> Dict[str, Any]:
    _ensure_platform_admin_schema()
    existing = _platform_notes_by_org().get(organization_id, {})
    notes = str(req.internal_notes if req.internal_notes is not None else existing.get("internal_notes", ""))
    stage = str(req.lifecycle_stage if req.lifecycle_stage is not None else existing.get("lifecycle_stage", ""))
    renewal = str(req.renewal_at if req.renewal_at is not None else existing.get("renewal_at", ""))
    owner = str(req.account_owner if req.account_owner is not None else existing.get("account_owner", ""))
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    """
                    INSERT INTO platform_customer_notes (organization_id, internal_notes, lifecycle_stage, renewal_at, account_owner, updated_at)
                    VALUES (%s, %s, %s, %s, %s, NOW())
                    ON CONFLICT (organization_id) DO UPDATE SET
                        internal_notes = EXCLUDED.internal_notes,
                        lifecycle_stage = EXCLUDED.lifecycle_stage,
                        renewal_at = EXCLUDED.renewal_at,
                        account_owner = EXCLUDED.account_owner,
                        updated_at = NOW()
                    RETURNING *
                    """,
                    (organization_id, notes[:4000], stage[:80], renewal[:80], owner[:120]),
                )
                row = _json_safe(dict(cur.fetchone()))
            conn.commit()
            return row
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        now = _platform_now_iso()
        conn.execute(
            """
            INSERT INTO platform_customer_notes (organization_id, internal_notes, lifecycle_stage, renewal_at, account_owner, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(organization_id) DO UPDATE SET
                internal_notes=excluded.internal_notes,
                lifecycle_stage=excluded.lifecycle_stage,
                renewal_at=excluded.renewal_at,
                account_owner=excluded.account_owner,
                updated_at=excluded.updated_at
            """,
            (organization_id, notes[:4000], stage[:80], renewal[:80], owner[:120], now),
        )
        row = conn.execute("SELECT * FROM platform_customer_notes WHERE organization_id=?", (organization_id,)).fetchone()
        conn.commit()
        return dict(row) if row else {}


def _autopatch_diagnosis(req: PlatformAutopatchCreateRequest) -> Dict[str, Any]:
    issue = str(req.issue_type or "ci_failure").strip().lower()
    logs = str(req.logs or "")
    severity = str(req.severity or "medium").strip().lower()
    risk = "high" if severity in {"critical", "high"} else "medium"
    if issue in {"dependency_vulnerability", "vulnerability", "cve"}:
        diagnosis = "Dependency or supply-chain issue. Safe autopatch path is version bump on a draft branch, full test run, and human review before merge."
        steps = ["Identify affected package and fixed version.", "Create narrow dependency update.", "Run dependency scan and regression tests.", "Open draft PR with vulnerability evidence."]
        risk = "high" if severity in {"critical", "high"} else "medium"
    elif issue in {"ci_failure", "test_failure"}:
        diagnosis = "CI/test failure. Safe autopatch path is reproduce, narrow code or test fix, run targeted tests, then open draft PR."
        steps = ["Parse failing check/log excerpt.", "Identify likely failing file or test.", "Create minimal patch branch.", "Run targeted tests and full smoke where practical.", "Open draft PR."]
    elif issue in {"lint", "typecheck", "format"}:
        diagnosis = "Static quality failure. Safe autopatch path is formatter/lint-compatible patch and review."
        steps = ["Run formatter/linter locally.", "Apply smallest compliant change.", "Run lint/typecheck again.", "Open draft PR."]
        risk = "low"
    elif issue in {"runtime_error", "production_error"}:
        diagnosis = "Runtime error. Safe autopatch path is reproduce from logs, add regression coverage, patch, and require approval before deploy."
        steps = ["Summarize stack trace and affected route/job.", "Add regression test if reproducible.", "Patch root cause.", "Run targeted tests.", "Open draft PR with rollback notes."]
        risk = "high"
    else:
        diagnosis = "Unclassified platform issue. Keep in suggest mode until a maintainer reviews the root cause."
        steps = ["Classify issue.", "Identify owner and affected files.", "Prepare patch plan.", "Require human approval before branch/PR work."]

    hints: List[str] = []
    lower_logs = logs.lower()
    if "modulenotfounderror" in lower_logs:
        hints.append("Missing dependency likely; inspect requirements and imports.")
    if "assertionerror" in lower_logs or "failed" in lower_logs:
        hints.append("Regression test failure likely; preserve failing assertion in PR evidence.")
    if "timeout" in lower_logs:
        hints.append("May be transient or performance-related; rerun before patching.")
    if "403" in lower_logs or "401" in lower_logs:
        hints.append("Authentication/authorization path affected; classify as high-risk.")
        risk = "high"

    return {
        "diagnosis": diagnosis,
        "patch_plan": {
            "mode": "draft_pr_only",
            "steps": steps,
            "affected_files": [str(x)[:260] for x in (req.affected_files or [])],
            "evidence_hints": hints,
            "approval_gate": "human_approval_required_before_merge_or_deploy",
            "forbidden_actions": ["direct_main_push", "auto_merge", "auto_deploy", "credential_rotation_without_operator"],
        },
        "risk_level": risk,
    }


def _normalize_autopatch_row(row: Dict[str, Any]) -> Dict[str, Any]:
    out = _json_safe(dict(row))
    for key, default in (("affected_files_json", []), ("patch_plan_json", {})):
        value = out.get(key)
        if isinstance(value, str):
            try:
                out[key] = json.loads(value or ("[]" if isinstance(default, list) else "{}"))
            except Exception:
                out[key] = default
        elif value is None:
            out[key] = default
    out["affected_files"] = out.pop("affected_files_json", [])
    out["patch_plan"] = out.pop("patch_plan_json", {})
    try:
        out["id"] = int(out.get("id") or 0)
    except Exception:
        out["id"] = 0
    return out


def _create_platform_autopatch(req: PlatformAutopatchCreateRequest) -> Dict[str, Any]:
    _ensure_platform_admin_schema()
    diag = _autopatch_diagnosis(req)
    now = _platform_now_iso()
    affected = [str(x or "").strip()[:260] for x in (req.affected_files or []) if str(x or "").strip()]
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    """
                    INSERT INTO platform_autopatches (
                        issue_type, severity, title, source, repo_full_name, failing_check,
                        logs, affected_files_json, diagnosis, patch_plan_json, risk_level, status, created_at, updated_at
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'needs_review',NOW(),NOW())
                    RETURNING *
                    """,
                    (
                        req.issue_type, req.severity, req.title, req.source, req.repo_full_name,
                        req.failing_check, req.logs[:12000], Json(affected), diag["diagnosis"],
                        Json(diag["patch_plan"]), diag["risk_level"],
                    ),
                )
                row = dict(cur.fetchone())
            conn.commit()
        return _normalize_autopatch_row(row)
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.execute(
            """
            INSERT INTO platform_autopatches (
                issue_type, severity, title, source, repo_full_name, failing_check, logs,
                affected_files_json, diagnosis, patch_plan_json, risk_level, status, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'needs_review', ?, ?)
            """,
            (
                req.issue_type, req.severity, req.title, req.source, req.repo_full_name, req.failing_check,
                req.logs[:12000], json.dumps(affected), diag["diagnosis"], json.dumps(diag["patch_plan"]),
                diag["risk_level"], now, now,
            ),
        )
        row = conn.execute("SELECT * FROM platform_autopatches WHERE id=?", (cur.lastrowid,)).fetchone()
        conn.commit()
        return _normalize_autopatch_row(dict(row))


def _list_platform_autopatches(status: str = "", limit: int = 100) -> List[Dict[str, Any]]:
    _ensure_platform_admin_schema()
    lim = max(1, min(int(limit or 100), 500))
    if postgres_main_db_requested():
        params: List[Any] = []
        where = ""
        if status:
            where = "WHERE status = %s"
            params.append(status)
        params.append(lim)
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(f"SELECT * FROM platform_autopatches {where} ORDER BY updated_at DESC, id DESC LIMIT %s", params)
                return [_normalize_autopatch_row(dict(r)) for r in cur.fetchall()]
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        params2: List[Any] = []
        where2 = ""
        if status:
            where2 = "WHERE status = ?"
            params2.append(status)
        rows = conn.execute(f"SELECT * FROM platform_autopatches {where2} ORDER BY updated_at DESC, id DESC LIMIT ?", (*params2, lim)).fetchall()
        return [_normalize_autopatch_row(dict(r)) for r in rows]


def _get_platform_autopatch(autopatch_id: int) -> Optional[Dict[str, Any]]:
    rows = _list_platform_autopatches(limit=500)
    return next((r for r in rows if int(r.get("id") or 0) == int(autopatch_id)), None)


def _update_platform_autopatch(autopatch_id: int, fields: Dict[str, Any]) -> Dict[str, Any]:
    _ensure_platform_admin_schema()
    allowed = {"status", "branch_name", "pr_title", "pr_body", "pr_url", "diagnosis", "patch_plan_json", "risk_level"}
    updates = {k: v for k, v in fields.items() if k in allowed}
    if not updates:
        row = _get_platform_autopatch(autopatch_id)
        if not row:
            raise HTTPException(status_code=404, detail="Autopatch item not found.")
        return row
    if postgres_main_db_requested():
        assignments = []
        params: List[Any] = []
        for k, v in updates.items():
            assignments.append(f"{k} = %s")
            params.append(Json(v) if k == "patch_plan_json" else v)
        params.append(int(autopatch_id))
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    f"UPDATE platform_autopatches SET {', '.join(assignments)}, updated_at = NOW() WHERE id = %s RETURNING *",
                    params,
                )
                row = cur.fetchone()
            conn.commit()
        if not row:
            raise HTTPException(status_code=404, detail="Autopatch item not found.")
        return _normalize_autopatch_row(dict(row))
    now = _platform_now_iso()
    set_sql = ", ".join(f"{k}=?" for k in updates)
    params2 = [json.dumps(v) if k == "patch_plan_json" else v for k, v in updates.items()]
    params2.extend([now, int(autopatch_id)])
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        conn.execute(f"UPDATE platform_autopatches SET {set_sql}, updated_at=? WHERE id=?", params2)
        row = conn.execute("SELECT * FROM platform_autopatches WHERE id=?", (int(autopatch_id),)).fetchone()
        conn.commit()
    if not row:
        raise HTTPException(status_code=404, detail="Autopatch item not found.")
    return _normalize_autopatch_row(dict(row))


def _platform_onboarding_checklist(c: Dict[str, Any]) -> Dict[str, Any]:
    checks = [
        {
            "key": "organization_created",
            "label": "Customer organization exists",
            "status": "pass" if c.get("organization_id") else "fail",
            "detail": str(c.get("organization_id") or "missing"),
        },
        {
            "key": "first_scan",
            "label": "First scan completed or queued",
            "status": "pass" if int(c.get("scan_count") or 0) > 0 else "fail",
            "detail": f"{int(c.get('scan_count') or 0)} scan(s)",
        },
        {
            "key": "asset_inventory",
            "label": "Asset inventory populated",
            "status": "pass" if int(c.get("asset_count") or 0) > 0 else "fail",
            "detail": f"{int(c.get('asset_count') or 0)} asset(s)",
        },
        {
            "key": "users",
            "label": "Users or owners assigned",
            "status": "pass" if int(c.get("user_count") or 0) > 0 or str(c.get("account_owner") or "").strip() else "warn",
            "detail": f"{int(c.get('user_count') or 0)} user(s), owner={c.get('account_owner') or 'not set'}",
        },
        {
            "key": "activity",
            "label": "Recent customer activity",
            "status": "pass" if c.get("last_login_at") else "warn",
            "detail": str(c.get("last_login_at") or "no login recorded"),
        },
    ]
    failed = sum(1 for item in checks if item["status"] == "fail")
    warnings = sum(1 for item in checks if item["status"] == "warn")
    return {"status": "ready" if failed == 0 else "incomplete", "failed": failed, "warnings": warnings, "checks": checks}


def _platform_observability_snapshot(limit: int = 100) -> Dict[str, Any]:
    observations = list(_REQUEST_OBSERVATIONS)[-int(limit):]
    rate_limited = list(_RATE_LIMIT_OBSERVATIONS)[-int(limit):]
    errors = [r for r in observations if int(r.get("status_code") or 0) >= 500]
    slow = [r for r in observations if float(r.get("duration_ms") or 0) >= 1500]
    by_status: Dict[str, int] = defaultdict(int)
    by_path: Dict[str, int] = defaultdict(int)
    for item in observations:
        by_status[str(item.get("status_code") or "unknown")] += 1
        by_path[str(item.get("path") or "unknown")] += 1
    return {
        "generated_at": _platform_now_iso(),
        "window_size": len(observations),
        "requests": observations,
        "recent_errors": errors[-25:],
        "slow_requests": slow[-25:],
        "rate_limited": rate_limited[-25:],
        "counts_by_status": dict(by_status),
        "top_paths": sorted(
            [{"path": k, "count": v} for k, v in by_path.items()],
            key=lambda x: x["count"],
            reverse=True,
        )[:10],
    }


def _platform_incident_snapshot() -> Dict[str, Any]:
    api_platform_health.__wrapped__ if hasattr(api_platform_health, "__wrapped__") else None
    obs = _platform_observability_snapshot(limit=500)
    incidents: List[Dict[str, Any]] = []
    for item in obs["recent_errors"]:
        incidents.append({
            "severity": "high",
            "category": "api_error",
            "title": f"{item.get('method')} {item.get('path')} returned {item.get('status_code')}",
            "detail": f"{item.get('duration_ms')} ms at {item.get('created_at')}",
            "organization_id": item.get("organization_id"),
        })
    for item in obs["slow_requests"]:
        incidents.append({
            "severity": "medium",
            "category": "latency",
            "title": f"Slow request: {item.get('method')} {item.get('path')}",
            "detail": f"{item.get('duration_ms')} ms",
            "organization_id": item.get("organization_id"),
        })
    for item in obs["rate_limited"]:
        incidents.append({
            "severity": "medium",
            "category": "rate_limit",
            "title": f"Rate limit triggered for {item.get('organization_id')}",
            "detail": f"{item.get('path')} via {item.get('source')}",
            "organization_id": item.get("organization_id"),
        })
    return {
        "generated_at": _platform_now_iso(),
        "status": "attention" if incidents else "clear",
        "incident_count": len(incidents),
        "incidents": incidents[:100],
    }


def _cleanup_tenant_probe(org_a: str, org_b: str, asset_a: str, asset_b: str) -> None:
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor() as cur:
                cur.execute("DELETE FROM asset_tags WHERE organization_id IN (%s,%s)", (org_a, org_b))
                cur.execute("DELETE FROM assets WHERE organization_id IN (%s,%s)", (org_a, org_b))
                cur.execute("DELETE FROM organizations WHERE id IN (%s,%s)", (org_a, org_b))
            conn.commit()
    else:
        with closing(get_connection()) as conn:
            conn.execute("DELETE FROM asset_tags WHERE organization_id IN (?,?)", (org_a, org_b))
            conn.execute("DELETE FROM assets WHERE organization_id IN (?,?)", (org_a, org_b))
            conn.execute("DELETE FROM organizations WHERE id IN (?,?)", (org_a, org_b))
            conn.commit()


def _run_tenant_isolation_probe() -> Dict[str, Any]:
    suffix = uuid.uuid4().hex[:10]
    org_a = f"tenant-probe-a-{suffix}"
    org_b = f"tenant-probe-b-{suffix}"
    asset_a = f"tenant-probe-a.example.com:443:{suffix}"
    asset_b = f"tenant-probe-b.example.com:443:{suffix}"
    details: Dict[str, Any] = {"org_a": org_a, "org_b": org_b}
    try:
        upsert_organization(org_a, "Tenant Probe A", plan_type="internal", subscription_status="active")
        upsert_organization(org_b, "Tenant Probe B", plan_type="internal", subscription_status="active")
        token_a = set_current_organization_id(org_a)
        try:
            upsert_asset(asset_a, owner="tenant-probe", team="security", environment="test")
            visible_a = [x.get("asset_key") for x in list_assets(limit=100)]
        finally:
            reset_current_organization_id(token_a)
        token_b = set_current_organization_id(org_b)
        try:
            upsert_asset(asset_b, owner="tenant-probe", team="security", environment="test")
            visible_b = [x.get("asset_key") for x in list_assets(limit=100)]
        finally:
            reset_current_organization_id(token_b)
        leak_a_sees_b = asset_b in visible_a
        leak_b_sees_a = asset_a in visible_b
        details.update({
            "org_a_visible_assets": visible_a,
            "org_b_visible_assets": visible_b,
            "leak_a_sees_b": leak_a_sees_b,
            "leak_b_sees_a": leak_b_sees_a,
        })
        return {
            "generated_at": _platform_now_iso(),
            "status": "pass" if not leak_a_sees_b and not leak_b_sees_a and asset_a in visible_a and asset_b in visible_b else "fail",
            "checks": [
                {"key": "org_a_own_asset_visible", "status": "pass" if asset_a in visible_a else "fail"},
                {"key": "org_b_own_asset_visible", "status": "pass" if asset_b in visible_b else "fail"},
                {"key": "org_a_cannot_see_org_b", "status": "pass" if not leak_a_sees_b else "fail"},
                {"key": "org_b_cannot_see_org_a", "status": "pass" if not leak_b_sees_a else "fail"},
            ],
            "details": details,
        }
    finally:
        _cleanup_tenant_probe(org_a, org_b, asset_a, asset_b)


def _build_audit_package(organization_id: str) -> bytes:
    token = set_current_organization_id(organization_id)
    try:
        package = {
            "package_version": "1.0",
            "organization_id": organization_id,
            "generated_at": _platform_now_iso(),
            "assets": list_assets(limit=10000),
            "scans": list_scan_rows(limit=2000),
            "remediations": list_remediations(limit=5000),
            "repositories": list_repositories(limit=5000),
            "audit_logs": list_audit_logs(limit=20000),
            # build_e2e_readiness takes keyword-only arguments with no defaults.
            # This call passed validation_jobs= (the parameter is validations=)
            # and omitted four required ones, so the audit package export raised
            # TypeError every time it was called and had never produced a file.
            "readiness": build_e2e_readiness(
                auth_configured=bool(AUTH_MODE and AUTH_MODE != "none"),
                repositories=list_repositories(limit=5000),
                github_installations=list_github_installations(limit=5000),
                scans=list_scan_rows(limit=200),
                assets=list_assets(limit=10000),
                remediations=list_remediations(limit=5000),
                validations=list_validation_jobs(limit=5000),
                pr_events=list_github_pr_events(limit=100),
                audit_events=list_audit_logs(limit=1000),
                webhook_events=list_webhook_events(limit=100),
            ),
        }
    finally:
        reset_current_organization_id(token)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("manifest.json", json.dumps({
            "organization_id": organization_id,
            "generated_at": package["generated_at"],
            "files": ["assets.json", "scans.json", "remediations.json", "repositories.json", "audit_logs.json", "readiness.json"],
        }, indent=2, default=str))
        for key in ("assets", "scans", "remediations", "repositories", "audit_logs", "readiness"):
            zf.writestr(f"{key}.json", json.dumps(package[key], indent=2, default=str))
    return buf.getvalue()


@app.get("/platform/customers")
def api_platform_customers(request: Request):
    """All customer organizations with usage stats. Requires x-platform-key header."""
    _require_platform_admin(request)
    customers = _platform_customer_stats()
    total_scans  = sum(c["scan_count"]        for c in customers)
    total_assets = sum(c["asset_count"]       for c in customers)
    total_remeds = sum(c["remediation_count"] for c in customers)
    active_7d    = sum(1 for c in customers if c.get("active_users_7d", 0) > 0)
    return {
        "summary": {
            "total_customers":      len(customers),
            "active_last_7_days":   active_7d,
            "total_scans_all_time": total_scans,
            "total_assets":         total_assets,
            "total_remediations":   total_remeds,
            "plan_breakdown":       {p: sum(1 for c in customers if c["plan_type"] == p)
                                     for p in set(c["plan_type"] for c in customers)},
        },
        "customers": customers,
    }


