@app.get("/platform/metrics")
def api_platform_metrics(request: Request):
    """Platform-wide health metrics for the operator dashboard."""
    _require_platform_admin(request)
    customers = _platform_customer_stats()
    now_iso  = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    day_ago  = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - 86400))
    week_ago = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - 7 * 86400))

    logins_24h  = _security_journal.login_count(day_ago)
    logins_7d   = _security_journal.login_count(week_ago)

    return {
        "generated_at":          now_iso,
        "customers_total":       len(customers),
        "customers_active_7d":   sum(1 for c in customers if c.get("active_users_7d", 0) > 0),
        "customers_never_active":sum(1 for c in customers if not c.get("last_login_at")),
        "logins_last_24h":       logins_24h,
        "logins_last_7d":        logins_7d,
        "total_scans":           sum(c["scan_count"]       for c in customers),
        "total_assets":          sum(c["asset_count"]      for c in customers),
        "total_remediations":    sum(c["remediation_count"] for c in customers),
        "plan_breakdown":        {p: sum(1 for c in customers if c["plan_type"] == p)
                                  for p in set(c["plan_type"] for c in customers)},
        "churn_risk": [
            {"organization_id": c["organization_id"], "name": c["name"],
             "last_login_at": c["last_login_at"], "scan_count": c["scan_count"],
             "risk_score": c.get("risk_score", 0)}
            for c in customers
            if (str(c.get("last_login_at") or "") < week_ago) or (not c.get("last_login_at") and c["scan_count"] == 0)
        ][:20],
    }


