@app.get("/platform/traffic/events")
def api_platform_traffic_events(
    request: Request,
    limit: int = Query(100, ge=1, le=500),
    source_ip: str = Query("", max_length=120),
    path_prefix: str = Query("", max_length=240),
    source: str = Query("recent", pattern="^(recent|archive)$"),
):
    """Recent platform-admin-only traffic events, optionally filtered by IP or path prefix."""
    _require_platform_admin(request)
    return {
        "api_version": "v1",
        "generated_at": _platform_now_iso(),
        "source": source,
        "items": _traffic_export_rows(source, int(limit), source_ip, path_prefix),
    }


def _traffic_export_rows(source, limit, source_ip="", path_prefix=""):
    if source == "archive":
        if not _TRAFFIC_PERSIST_TO_DB:
            raise HTTPException(409, "Traffic archive is disabled; this is not an empty retained history")
        try:
            return _security_journal.request_events(limit=limit, source_ip=source_ip, path_prefix=path_prefix)
        except Exception:
            raise HTTPException(503, "Traffic archive unavailable; no retained-history result was issued")
    return _traffic_events(limit=limit, source_ip=source_ip, path_prefix=path_prefix)


@app.get("/platform/traffic/export.ndjson")
def api_platform_traffic_export_ndjson(request: Request, limit: int = Query(500, ge=1, le=5000), source: str = Query("recent", pattern="^(recent|archive)$"), source_ip: str = Query("", max_length=64), path_prefix: str = Query("", max_length=240)):
    """SIEM-friendly newline-delimited JSON export of recent traffic metadata."""
    _require_platform_admin(request)
    lines = [json.dumps(item, separators=(",", ":"), default=str) for item in _traffic_export_rows(source, int(limit), source_ip, path_prefix)]
    return Response(
        content=("\n".join(lines) + ("\n" if lines else "")),
        media_type="application/x-ndjson",
        headers={"Content-Disposition": "attachment; filename=pqc-traffic-events.ndjson", "Cache-Control": "no-store"},
    )


@app.get("/platform/traffic/otel")
def api_platform_traffic_otel(request: Request, limit: int = Query(500, ge=1, le=5000), source: str = Query("recent", pattern="^(recent|archive)$"), source_ip: str = Query("", max_length=64), path_prefix: str = Query("", max_length=240)):
    """OpenTelemetry log-record-shaped export for collectors that ingest OTLP JSON."""
    _require_platform_admin(request)
    records = []
    for item in _traffic_export_rows(source, int(limit), source_ip, path_prefix):
        records.append({
            "timeUnixNano": str(int(datetime.fromisoformat(item["created_at"].replace("Z", "+00:00")).timestamp() * 1_000_000) * 1000),
            "severityText": "ERROR" if int(item.get("status_code") or 0) >= 500 else "INFO",
            "body": {"stringValue": f"{item.get('method')} {item.get('path')} {item.get('status_code')}"},
            "attributes": [
                {"key": "source.ip_hash", "value": {"stringValue": item.get("ip_hash", "")}},
                {"key": "http.method", "value": {"stringValue": item.get("method", "")}},
                {"key": "url.path", "value": {"stringValue": item.get("path", "")}},
                {"key": "http.response.status_code", "value": {"intValue": int(item.get("status_code") or 0)}},
                {"key": "http.server.duration_ms", "value": {"doubleValue": float(item.get("duration_ms") or 0.0)}},
                {"key": "pqc.organization_id", "value": {"stringValue": item.get("organization_id", "")}},
                {"key": "pqc.actor_role", "value": {"stringValue": item.get("actor_role", "")}},
            ],
        })
    return {
        "resourceLogs": [{
            "resource": {"attributes": [{"key": "service.name", "value": {"stringValue": "pqc-scanner"}}]},
            "scopeLogs": [{"scope": {"name": "pqc.traffic"}, "logRecords": records}],
        }]
    }


