@app.get("/platform/security-truth")
def api_platform_security_truth(request: Request, limit: int = Query(50, ge=1, le=200)):
    _require_platform_admin(request)
    findings = _list_external_findings(limit=int(limit))
    severity_counts: Dict[str, int] = defaultdict(int)
    status_counts: Dict[str, int] = defaultdict(int)
    tool_counts: Dict[str, int] = defaultdict(int)
    for item in findings:
        severity_counts[str(item.get("severity") or "medium")] += 1
        status_counts[str(item.get("status") or "open")] += 1
        tool_counts[str(item.get("tool_source") or "external")] += 1
    critical_open = [
        item for item in findings
        if str(item.get("status") or "open") == "open" and str(item.get("severity") or "").lower() in {"critical", "high"}
    ]
    blocked_changes = [
        i for i in list_audit_logs(limit=200, action="write_path.fix_request", decision="deny")
    ]
    guardrail_events = list_audit_logs(limit=50, action="guardrails.evaluate_change")
    return {
        "api_version": "v1",
        "generated_at": _now_iso(),
        "findings_total_returned": len(findings),
        "open_high_critical": len(critical_open),
        "blocked_write_path_changes": len(blocked_changes),
        "counts_by_severity": dict(severity_counts),
        "counts_by_status": dict(status_counts),
        "counts_by_tool": dict(tool_counts),
        "recent_findings": findings[:20],
        "recent_guardrails": guardrail_events[:20],
    }


@app.post("/platform/security-truth/findings/{finding_id}/write-path")
def api_platform_security_truth_finding_write_path(
    finding_id: int,
    req: ExternalFindingConvertRequest,
    request: Request,
):
    _require_platform_admin(request, _PLATFORM_ADMIN_WRITE_ROLES)
    finding = _get_external_finding(finding_id)
    org_id = str(finding.get("organization_id") or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    _require_org_feature(org_id, "write_path", "Security Truth write-path promotion")
    token = set_current_organization_id(org_id)
    try:
        evidence = finding.get("evidence") or {}
        fix = WritePathFixRequest(
            tool_source=str(finding.get("tool_source") or "platform-admin"),
            finding_id=str(finding.get("external_id") or finding.get("id") or finding_id),
            repo=str(finding.get("repo") or ""),
            asset_key=str(finding.get("resource_id") or ""),
            desired_outcome=req.desired_outcome or finding.get("remediation") or finding.get("description") or finding.get("title") or "Remediate external finding",
            changed_files=req.changed_files or evidence.get("changed_files") or [],
            proposed_diff=req.proposed_diff,
            create_remediation=req.create_remediation,
            dry_run=req.dry_run,
            metadata={
                "platform_admin_action": True,
                "external_finding_row_id": finding_id,
                "severity": finding.get("severity"),
                "category": finding.get("category"),
                **(req.metadata or {}),
            },
        )
        result = _create_write_path_fix_response(
            fix,
            org_id=org_id,
            actor={"actor_id": "platform-admin", "actor_role": "admin"},
        )
        _mark_external_finding_write_path(finding_id, org_id, str(result.get("request_id") or ""))
        _record_platform_admin_event(
            org_id,
            "security_truth.finding.write_path",
            reason=str(result.get("status") or ""),
            details={"finding_id": finding_id, "request_id": result.get("request_id")},
        )
        result["finding"] = _get_external_finding(finding_id, org_id)
        return result
    finally:
        reset_current_organization_id(token)


@app.get("/platform/customers/{organization_id}")
def api_platform_customer_detail(organization_id: str, request: Request):
    _require_platform_admin(request)
    customers = _platform_customer_stats()
    customer = next((c for c in customers if str(c.get("organization_id")) == organization_id), None)
    if not customer:
        raise HTTPException(status_code=404, detail="Customer organization not found.")

    recent_scans: List[Dict[str, Any]] = []
    remediation_status: Dict[str, int] = {}
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    "SELECT id, status, created_at, job_state FROM scans WHERE organization_id=%s ORDER BY created_at DESC LIMIT 8",
                    (organization_id,),
                )
                recent_scans = [_json_safe(dict(r)) for r in cur.fetchall()]
                cur.execute(
                    "SELECT status, COUNT(*) AS count FROM remediations WHERE organization_id=%s GROUP BY status",
                    (organization_id,),
                )
                remediation_status = {str(r["status"] or "unknown"): int(r["count"] or 0) for r in cur.fetchall()}
    else:
        with closing(get_connection()) as conn:
            conn.row_factory = sqlite3.Row
            recent_scans = [dict(r) for r in conn.execute(
                "SELECT id, status, created_at, job_state FROM scans WHERE organization_id=? ORDER BY created_at DESC LIMIT 8",
                (organization_id,),
            ).fetchall()]
            rows = conn.execute(
                "SELECT status, COUNT(*) AS count FROM remediations WHERE organization_id=? GROUP BY status",
                (organization_id,),
            ).fetchall()
            remediation_status = {str(r["status"] or "unknown"): int(r["count"] or 0) for r in rows}
    return {
        "customer": customer,
        "onboarding_checklist": _platform_onboarding_checklist(customer),
        "feature_flags": _platform_feature_flags(organization_id),
        "recent_logins": _platform_login_events(organization_id=organization_id, limit=20),
        "recent_scans": recent_scans,
        "remediation_status": remediation_status,
        "admin_events": _platform_list_admin_events(organization_id=organization_id, limit=40),
    }


