@app.patch("/platform/customers/{organization_id}")
def api_platform_update_customer(organization_id: str, req: PlatformCustomerUpdateRequest, request: Request):
    _actor = _require_platform_admin(request, _PLATFORM_ADMIN_WRITE_ROLES)
    customers = _platform_customer_stats()
    current = next((c for c in customers if str(c.get("organization_id")) == organization_id), None)
    if not current:
        raise HTTPException(status_code=404, detail="Customer organization not found.")
    if req.plan_type is not None and str(req.plan_type).strip()[:64] != str(current.get("plan_type") or "starter"):
        _operator_auth.require_step_up(_actor, "change a customer's plan")
    plan = str(req.plan_type if req.plan_type is not None else current.get("plan_type") or "starter").strip()[:64]
    status = str(req.subscription_status if req.subscription_status is not None else current.get("subscription_status") or "active").strip()[:64]
    upsert_organization(
        organization_id,
        str(current.get("name") or organization_id),
        plan_type=plan,
        subscription_status=status,
    )
    notes = _platform_upsert_notes(organization_id, req)
    _record_platform_admin_event(
        organization_id,
        "platform.customer_updated",
        details={"plan_type": plan, "subscription_status": status, "notes": notes},
    )
    return api_platform_customer_detail(organization_id, request)


