# ── Demo Lab (local development only) ─────────────────────────────────────────
# Seeds a fixed, fictional scenario so developers can exercise the console
# without live scans. It is available only when PQC_ENVIRONMENT is a local,
# dev or test environment — never in staging or production, whatever
# PQC_ALLOW_DEMO_IN_PRODUCTION says. Every record it creates carries the
# DEMO_LAB_SOURCE marker so it can be found and removed:
#   assets:        tag "demo-lab", metadata.source == "demo-lab"
#   scans:         id prefix "demo-lab-", result source == "demo-lab"
#   remediations:  origin_kind == "demo_lab"
#   validations:   job_id prefix "demo-lab-validation-", details.source == "demo-lab"
#   audit log:     actor_id == "demo-lab", action == "demo_lab.seed"
DEMO_LAB_SOURCE = "demo-lab"
_DEMO_LAB_ENVIRONMENTS = {"local", "dev", "development", "test", "testing"}


def _deployment_environment_label() -> str:
    """Coarse environment for the console: local, staging, or production."""
    if PRODUCTION_ENVIRONMENT:
        return "production"
    env = str(PQC_ENVIRONMENT or "").strip().lower()
    if env in {"prod", "production"}:
        return "production"
    if env in _DEMO_LAB_ENVIRONMENTS:
        return "local"
    return "staging"


def _demo_lab_available() -> bool:
    return _deployment_environment_label() == "local"


def _demo_lab_result(target: str) -> Dict[str, Any]:
    host, port = parse_target(target)
    facts = {
        "host": host,
        "port": port,
        "source": DEMO_LAB_SOURCE,
        "demo_lab": True,
        "tls_version": "TLSv1.3",
        "key_type": "RSA",
        "key_detail": "RSA 2048",
        "sig_algorithm": "sha256WithRSAEncryption",
        "issuer": "Demo Lab Test CA",
        "cert_issuer": "Demo Lab Test CA",
        "findings": [
            {
                "rule_id": "PQC_CLASSICAL_PUBLIC_KEY_DEPENDENCY",
                "severity": "high",
                "message": "Endpoint depends on classical RSA/ECC public-key cryptography for authentication/key establishment.",
            }
        ],
        "risk_level": "high",
        "quantum_risk_score": 72,
        "pqc_relevance": "high",
        "pqc_recommendation": "Prioritize crypto-agility and provider-supported hybrid/PQC TLS planning for long-lived sensitive data.",
    }
    facts.update(derive_quantum_readiness(facts, facts["findings"]))
    return facts


def _seed_demo_lab(org_id: str, req: DemoLabSeedRequest) -> Dict[str, Any]:
    if not _demo_lab_available():  # defence in depth; the route checks first
        raise HTTPException(status_code=403, detail="Demo Lab is available only in local development.")
    target = str(req.target or "demo-lab.invalid:443").strip() or "demo-lab.invalid:443"
    result = _demo_lab_result(target)
    asset_key_str = asset_key(result["host"], int(result.get("port") or 443))
    repo = upsert_repository(req.repo_name, f"https://github.com/{req.repo_name}")
    upsert_asset(
        asset_key_str,
        owner=req.owner,
        team=req.team,
        environment=req.environment,
        criticality=req.criticality,
        confidentiality_lifetime=req.confidentiality_lifetime,
        tags=["internet", "pqc", "hndl", DEMO_LAB_SOURCE],
        notes="Demo Lab record (local development only): fictional scenario data, not a scan result.",
        metadata={"demo_lab": True, "source": DEMO_LAB_SOURCE, "scenario": "quantum_migration"},
        repository_id=int(repo.get("id") or 0),
    )

    scan_id = f"demo-lab-{uuid.uuid4()}"
    now = _utc_now()
    summary = summarize_results([result])
    progress = _progress(1, 1)
    save_scan_row(scan_id, "completed", now, progress, "", [result], summary)
    save_scan_results(scan_id, results=[result], summary=summary, status="completed")
    save_scan_asset_summaries(scan_id, scanned_at_iso=now.isoformat().replace("+00:00", "Z"), results=[result])

    original = """resource "example_tls_policy" "portal" {
  min_tls_version = "1.2"
  allow_weak_ciphers = true
  crypto_agility_owner = ""
}
"""
    suggested = """resource "example_tls_policy" "portal" {
  min_tls_version = "1.3"
  allow_weak_ciphers = false
  crypto_agility_owner = "platform"
  pqc_migration_stage = "hybrid-provider-check"
}
"""
    remediation = create_remediation(
        asset_key_str,
        int(repo.get("id") or 0),
        "infra/tls-policy.tf",
        "Demo Lab: improve crypto agility for an internet-facing system with long-lived sensitive data and HNDL exposure.",
        "Require TLS 1.3, remove weak cipher assumptions, assign a crypto-agility owner, and track provider hybrid/PQC rollout.",
        original_content=original,
        suggested_content=suggested,
        status="verified_closed" if req.create_verified_evidence else "approved",
        review_note="Demo Lab evidence package.",
        origin_kind="demo_lab",
    )
    validation = create_validation_job(
        int(remediation.get("id") or 0),
        validator_type="terraform",
        git_ref="main",
        status="passed",
        job_id=f"demo-lab-validation-{uuid.uuid4()}",
        details={
            "demo_lab": True,
            "source": DEMO_LAB_SOURCE,
            "simulated": True,
            "commands": [
                {"cmd": "terraform fmt -check", "exit_code": 0, "executed": False},
                {"cmd": "terraform init -backend=false", "exit_code": 0, "executed": False},
                {"cmd": "terraform validate", "exit_code": 0, "executed": False},
            ],
            "iac_policy": {"status": "passed", "findings": []},
        },
    )
    validation = update_validation_job(
        int(validation.get("id") or 0),
        status="passed",
        stdout="[Demo Lab — simulated, no commands were executed] Scenario validation record for local development.\n",
        stderr="",
        exit_code=0,
        finished=True,
    ) or validation
    append_audit_log(
        actor_id=DEMO_LAB_SOURCE,
        actor_role="admin",
        action="demo_lab.seed",
        resource_type="organization",
        resource_id=org_id,
        decision="allow",
        reason="seeded Demo Lab records (local development only)",
        details={"source": DEMO_LAB_SOURCE, "target": asset_key_str, "repo": repo.get("name"), "scan_id": scan_id, "remediation_id": remediation.get("id")},
    )
    return {
        "ok": True,
        "source": DEMO_LAB_SOURCE,
        "record_markers": {
            "asset_tag": DEMO_LAB_SOURCE,
            "asset_metadata_source": DEMO_LAB_SOURCE,
            "scan_id_prefix": "demo-lab-",
            "remediation_origin_kind": "demo_lab",
            "validation_job_id_prefix": "demo-lab-validation-",
            "audit_actor_id": DEMO_LAB_SOURCE,
        },
        "target": asset_key_str,
        "scan_id": scan_id,
        "repo": repo,
        "asset": get_asset(asset_key_str),
        "remediation": get_remediation(int(remediation.get("id") or 0)) or remediation,
        "validation": validation,
        "portfolio": _build_quantum_migration_portfolio(org_id, scan_limit=100, asset_limit=10000),
        "report_url": "/org/quantum-readiness-report.html",
    }


