def _org_policy_key(org_id: str) -> str:
    return f"org_policy_json::{str(org_id or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID}"


def _load_org_policy(org_id: str) -> Dict[str, Any]:
    raw = str(get_integration_setting(_org_policy_key(org_id), "") or "").strip()
    if raw:
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, dict):
                policy = dict(DEFAULT_ORG_POLICY_PROFILE)
                policy.update(parsed)
                policy["version"] = str(policy.get("version") or "v1")
                return policy
        except Exception as _policy_exc:
            logging.warning("[POLICY] Failed to load org policy: %s", _policy_exc)
    return dict(DEFAULT_ORG_POLICY_PROFILE)


def _save_org_policy(org_id: str, policy: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(DEFAULT_ORG_POLICY_PROFILE)
    merged.update(policy or {})
    merged["version"] = str(merged.get("version") or "v1")
    set_integration_setting(_org_policy_key(org_id), json.dumps(merged, sort_keys=True))
    return merged


def _repo_name_parts(repo_name: str) -> tuple[str, str]:
    parts = str(repo_name or "").strip().strip("/").split("/", 1)
    if len(parts) != 2 or not parts[0] or not parts[1]:
        raise HTTPException(status_code=400, detail="repository must be in owner/repo format")
    return parts[0], parts[1]


def _matches_any_glob(path: str, patterns: List[str]) -> bool:
    p = str(path or "").strip()
    return any(fnmatch.fnmatch(p, pat) or fnmatch.fnmatch(p.split("/")[-1], pat) for pat in patterns or [])


def _github_fetch_repo_crypto_files(req: GithubCryptoDiscoveryRequest) -> Dict[str, Any]:
    owner, repo = _repo_name_parts(req.repository)
    token = _github_repo_token_or_502(int(req.github_credential_id), req.repository)
    ref = str(req.ref or "HEAD").strip() or "HEAD"
    tree_url = f"https://api.github.com/repos/{owner}/{repo}/git/trees/{urllib.parse.quote(ref, safe='')}?recursive=1"
    tree_resp = github_api("GET", tree_url, token, timeout_s=45)
    if not tree_resp.get("ok"):
        raise HTTPException(status_code=502, detail={"error": "failed to fetch github repository tree", "github": tree_resp})
    tree = (tree_resp.get("json") or {}).get("tree") or []
    include = req.include_globs or []
    exclude = req.exclude_globs or []
    max_files = max(1, min(int(req.max_files or 200), 1000))
    max_bytes = max(1, min(int(req.max_kb_per_file or 128), 2048)) * 1024
    candidates = []
    for item in tree:
        if item.get("type") != "blob":
            continue
        path = str(item.get("path") or "")
        if not path:
            continue
        if include and not _matches_any_glob(path, include):
            continue
        if exclude and _matches_any_glob(path, exclude):
            continue
        size = int(item.get("size") or 0)
        if size > max_bytes:
            continue
        candidates.append(item)
        if len(candidates) >= max_files:
            break
    files = []
    for item in candidates:
        blob_url = str(item.get("url") or "")
        if not blob_url:
            continue
        blob = github_api("GET", blob_url, token, timeout_s=30)
        if not blob.get("ok"):
            continue
        j = blob.get("json") or {}
        if str(j.get("encoding") or "").lower() != "base64":
            continue
        try:
            content = base64.b64decode(str(j.get("content") or "").encode("utf-8")).decode("utf-8", errors="replace")
        except Exception:
            continue
        files.append({"path": str(item.get("path") or ""), "content": content})
    return {"files": files, "tree_entries": len(tree), "candidate_files": len(candidates), "fetched_files": len(files)}


def _repo_id_for_name(repo_name: str) -> int:
    repo = get_repository_by_name(repo_name)
    if repo:
        return int(repo.get("id") or 0)
    return 0


def _decision_from_asset(asset: Dict[str, Any], latest: Dict[str, Any], policy: Dict[str, Any]) -> Dict[str, Any]:
    reasons: List[str] = []
    status = "pass"
    if policy.get("require_owner") and not str(asset.get("owner") or "").strip():
        reasons.append("asset owner missing")
        status = "warn"
    if policy.get("require_repository_link") and not int(asset.get("repository_id") or 0):
        reasons.append("repository link missing")
        status = "warn"
    hndl = str(latest.get("harvest_now_decrypt_later_risk") or "unknown").lower()
    risk = str(latest.get("risk_level") or latest.get("quantum_risk_level") or "").lower()
    if hndl in {"critical", "high"}:
        reasons.append(f"harvest-now/decrypt-later risk is {hndl}")
        status = "block" if hndl == "critical" else max(status, "warn", key=lambda x: {"pass": 0, "warn": 1, "block": 2}.get(x, 0))
    if risk == "critical" and policy.get("fail_ci_on_critical_asset", True):
        reasons.append("critical scan posture")
        status = "block"
    provider = str(latest.get("provider_guess") or "unknown").lower()
    if provider == "unknown" and bool(policy.get("unknown_provider_blocks")):
        reasons.append("TLS provider unknown")
        status = "block"
    if provider and provider not in set(str(x).lower() for x in (policy.get("allowed_providers") or [])):
        reasons.append(f"provider {provider} is not allowed by policy")
        status = "block"
    if not latest:
        reasons.append("asset has no scan evidence")
        status = "warn"
    return {
        "status": status,
        "reasons": reasons,
        "policy_version": policy.get("version") or "v1",
    }


def _canonical_json_bytes(payload: Dict[str, Any]) -> bytes:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")


def _evidence_signature(payload: Dict[str, Any]) -> Dict[str, Any]:
    key = str(os.getenv("PQC_EVIDENCE_SIGNING_KEY") or os.getenv("PQC_VAULT_MASTER_KEY") or "").strip()
    canonical = _canonical_json_bytes(payload)
    digest = hashlib.sha256(canonical).hexdigest()
    if not key:
        return {"alg": "sha256", "signed": False, "digest": digest, "note": "set PQC_EVIDENCE_SIGNING_KEY to enable HMAC signatures"}
    sig = hmac.new(key.encode("utf-8"), canonical, hashlib.sha256).hexdigest()
    return {"alg": "HMAC-SHA256", "signed": True, "key_id": "pqc-evidence-v1", "digest": digest, "signature": sig}


def _attach_evidence_integrity(payload: Dict[str, Any]) -> Dict[str, Any]:
    payload = dict(payload or {})
    payload.pop("evidence_hash", None)
    payload.pop("evidence_integrity", None)
    integrity = _evidence_signature(payload)
    payload["evidence_hash"] = str(integrity.get("digest") or "")
    payload["evidence_integrity"] = integrity
    return payload


def _latest_full_scan_result_for_asset(asset_key_str: str, scan_limit: int = 100) -> Dict[str, Any]:
    wanted = str(asset_key_str or "").strip()
    if not wanted:
        return {}
    for row in list_scan_rows(limit=scan_limit):
        scan_id = str(row.get("id") or "")
        if not scan_id:
            continue
        scan = load_scan_row(scan_id) or {}
        for result in scan.get("results") or []:
            if not isinstance(result, dict):
                continue
            key = str(result.get("asset_key") or "").strip()
            if not key:
                host = str(result.get("host") or "").strip()
                port = int(result.get("port") or 443)
                key = asset_key(host, port) if host else ""
            if key == wanted:
                out = dict(result)
                out["scan_id"] = scan_id
                out["scanned_at"] = row.get("created_at") or scan.get("created_at") or ""
                return out
    return latest_scan_result_for_asset(wanted) or {}


def _latest_full_scan_result_lookup(scan_limit: int = 100, fallback_keys: Optional[Sequence[str]] = None):
    """Many-asset form of _latest_full_scan_result_for_asset, for reports that ask about every asset.

    Answers exactly as that function does -- the first scan, in list_scan_rows order, whose results
    contain the asset wins, else latest_scan_result_for_asset -- but lists the scans once and loads
    each at most once. Calling the single-asset function per asset re-listed up to 100 scans and
    re-loaded each of them for every asset (7 assets x 44 scans = ~300 connections for
    /governance/certificates). The returned callable holds no state beyond the call that created it,
    so nothing is shared across requests or organizations.

    `fallback_keys`: the whole set of assets the caller will ask about. With it, the
    latest_scan_result_for_asset fallback -- taken for every asset that does not appear in the
    recent scans, which on a large inventory is most of them -- is resolved from one batched
    DISTINCT ON instead of one query per asset.
    """
    rows: Optional[List[Dict[str, Any]]] = None
    loaded = 0
    found: Dict[str, Dict[str, Any]] = {}
    fallback: Optional[Dict[str, Dict[str, Any]]] = None
    wanted_all = [str(k).strip() for k in (fallback_keys or []) if str(k or "").strip()]

    def lookup(asset_key_str: str) -> Dict[str, Any]:
        nonlocal rows, loaded, fallback
        wanted = str(asset_key_str or "").strip()
        if not wanted:
            return {}
        if rows is None:
            rows = list_scan_rows(limit=scan_limit)
        while wanted not in found and loaded < len(rows):
            row = rows[loaded]
            loaded += 1
            scan_id = str(row.get("id") or "")
            if not scan_id:
                continue
            scan = load_scan_row(scan_id) or {}
            for result in scan.get("results") or []:
                if not isinstance(result, dict):
                    continue
                key = str(result.get("asset_key") or "").strip()
                if not key:
                    host = str(result.get("host") or "").strip()
                    port = int(result.get("port") or 443)
                    key = asset_key(host, port) if host else ""
                if key and key not in found:
                    out = dict(result)
                    out["scan_id"] = scan_id
                    out["scanned_at"] = row.get("created_at") or scan.get("created_at") or ""
                    found[key] = out
        if wanted in found:
            return dict(found[wanted])
        if wanted_all:
            if fallback is None:
                from db import latest_scan_results_for_assets as _batch_latest
                fallback = _batch_latest(wanted_all) or {}
            return dict(fallback.get(wanted) or {})
        return latest_scan_result_for_asset(wanted) or {}

    return lookup


def _asset_evidence(asset_key_str: str, org_id: str) -> Dict[str, Any]:
    asset = get_asset(asset_key_str)
    if not asset:
        raise HTTPException(status_code=404, detail="asset not found")
    latest = _latest_full_scan_result_for_asset(asset_key_str) or {}
    policy = _load_org_policy(org_id)
    related_remediations = list_remediations(asset_key_str=asset_key_str, limit=200)
    remediation_evidence = []
    for row in related_remediations:
        validation = get_latest_validation_job_for_remediation(int(row.get("id") or 0))
        remediation_evidence.append(
            {
                "id": row.get("id"),
                "status": row.get("status"),
                "repo_id": row.get("repo_id"),
                "repository": row.get("repository_name") or "",
                "file_path": row.get("file_path") or "",
                "pr_url": row.get("pr_url") or "",
                "merged_at": row.get("merged_at") or "",
                "verification_scan_id": row.get("verification_scan_id") or "",
                "closed_at": row.get("closed_at") or "",
                "drift_status": row.get("drift_status") or "",
                "validation": validation or {},
            }
        )
    decision = _decision_from_asset(asset, latest, policy)
    return _attach_evidence_integrity({
        "generated_at": _now_iso(),
        "organization": _report_organization_record(org_id),
        "asset": asset,
        "latest_scan_evidence": latest,
        "quantum_readiness": {
            "harvest_now_decrypt_later_risk": latest.get("harvest_now_decrypt_later_risk") or "unknown",
            "classical_crypto_dependency": bool(latest.get("classical_crypto_dependency", False)),
            "classical_algorithm": latest.get("classical_algorithm") or latest.get("key_type") or "unknown",
            "provider_guess": latest.get("provider_guess") or "unknown",
            "provider_pqc_support_status": latest.get("provider_pqc_support_status") or "unknown",
            # None, not 0: an asset with no recorded agility score has not scored zero.
            "crypto_agility_score": latest.get("crypto_agility_score"),
            "pqc_migration_status": latest.get("pqc_migration_status") or "not_assessed",
            "next_action": (latest.get("pqc_blockers") or latest.get("pqc_migration_actions") or ["Scan and classify this asset."])[0],
            "migration_plan": latest.get("pqc_migration_plan") or [],
        },
        "policy_decision": decision,
        "remediations": remediation_evidence,
    })


def _remediation_evidence(remediation_id: int, org_id: str) -> Dict[str, Any]:
    row = get_remediation(int(remediation_id))
    if not row:
        raise HTTPException(status_code=404, detail="remediation not found")
    validation_jobs = list_validation_jobs(int(remediation_id), limit=100)
    asset_ev: Dict[str, Any] = {}
    try:
        asset_ev = _asset_evidence(str(row.get("asset_key") or ""), org_id)
    except Exception:
        asset_ev = {}
    payload = {
        "generated_at": _now_iso(),
        "organization": _report_organization_record(org_id),
        "remediation": row,
        "validation_jobs": validation_jobs,
        "asset_evidence": asset_ev,
    }
    return _attach_evidence_integrity(payload)


def _repo_evidence(repo_name: str, org_id: str) -> Dict[str, Any]:
    repo = get_repository_by_name(repo_name)
    if not repo:
        raise HTTPException(status_code=404, detail="repository not found")
    assets = list_assets_by_repository(int(repo.get("id") or 0))
    asset_evidence = []
    for asset in assets:
        try:
            asset_evidence.append(_asset_evidence(str(asset.get("asset_key") or ""), org_id))
        except Exception as _ae_exc:
            logging.warning("[EVIDENCE] Asset evidence failed for %s: %s", asset.get("asset_key"), _ae_exc)
    remediations = list_remediations(repo_id=int(repo.get("id") or 0), limit=500)
    gate = _repo_enforcement_decision(repo_name, changed_files=[], require_verified_closed=bool(_load_org_policy(org_id).get("require_verified_closed_for_ci_gate", True)))
    return _attach_evidence_integrity({
        "generated_at": _now_iso(),
        "organization": _report_organization_record(org_id),
        "repository": repo,
        "assets": asset_evidence,
        "remediations": remediations,
        "gate_decision": gate,
    })


def _asset_region(asset: Dict[str, Any]) -> str:
    metadata = asset.get("metadata") if isinstance(asset.get("metadata"), dict) else {}
    for key in ("region", "geo", "jurisdiction", "data_region"):
        value = str(metadata.get(key) or "").strip().lower()
        if value:
            return value
    tags = [str(t or "").strip().lower() for t in (asset.get("tags") or [])]
    if any(t in {"eu", "europe", "emea"} or t.startswith("eu-") for t in tags):
        return "eu"
    return ""


def _crypto_tokens(latest: Dict[str, Any]) -> str:
    values = [
        latest.get("classical_algorithm"),
        latest.get("key_type"),
        latest.get("key_detail"),
        latest.get("sig_algorithm"),
        latest.get("cert_algorithm"),
        latest.get("tls_key_exchange"),
    ]
    return " ".join(str(v or "").strip().lower().replace("_", "-") for v in values if str(v or "").strip())


def _violation_fix_suggestion(violation: Dict[str, Any]) -> str:
    kind = str(violation.get("kind") or "").strip().lower()
    if kind == "asset_policy":
        return "Review the linked asset, create a remediation candidate, validate the change, then verify-close after deployment."
    if kind == "quantum_policy":
        return "Prioritize this asset for HNDL review, assign an owner, and move the TLS/provider posture into a tracked migration plan."
    if kind == "provider_policy":
        return "Identify the TLS termination provider, link the responsible repository, and update the asset provider metadata."
    if kind == "crypto_policy":
        return "Replace the banned classical crypto dependency with the organization-approved migration target or document a reviewed exception."
    if kind == "iac_security":
        rule = str(violation.get("rule_id") or "").strip()
        if rule == "IAC_OPEN_SSH_TO_INTERNET":
            return "Restrict SSH ingress to approved administrative CIDRs or remove public SSH access."
        if rule == "IAC_AWS_S3_PUBLIC_ACCESS_BLOCK_DISABLED":
            return "Enable S3 public access block controls and validate the Terraform change."
        return "Update the IaC file to satisfy the policy finding, then rerun validation."
    return "Review the policy violation, apply the suggested remediation workflow, and rerun the PR gate."


def _enrich_gate_decision(decision: Dict[str, Any]) -> Dict[str, Any]:
    decision = dict(decision or {})
    violations = []
    suggestions = []
    for index, raw in enumerate(decision.get("violations") or [], start=1):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        item.setdefault("fix_suggestion", _violation_fix_suggestion(item))
        item.setdefault("blocking", True)
        item.setdefault("id", f"POLICY-{index:03d}")
        violations.append(item)
        suggestions.append(
            {
                "violation_id": item.get("id"),
                "kind": item.get("kind") or "policy",
                "asset_key": item.get("asset_key") or "",
                "file_path": item.get("file_path") or item.get("path") or "",
                "suggestion": item.get("fix_suggestion") or "",
            }
        )
    failed = bool(violations)
    decision["violations"] = violations
    decision["fix_suggestions"] = suggestions
    decision["blocking"] = failed
    decision["required_check_context"] = "pqc-scanner/security-policy"
    decision["merge_gate"] = "blocked" if failed else "allowed"
    decision["enforcement_mode"] = "blocking"
    return decision


def _github_check_text(decision: Dict[str, Any]) -> str:
    violations = [v for v in (decision.get("violations") or []) if isinstance(v, dict)]
    if not violations:
        return "No blocking PQC/security policy violations."
    lines = ["Blocking PQC/security policy violations:", ""]
    for v in violations[:25]:
        lines.append(f"- {v.get('id') or 'POLICY'} {v.get('kind') or 'policy'}: {v.get('message') or v.get('title') or v.get('rule_id') or 'policy violation'}")
        if v.get("fix_suggestion"):
            lines.append(f"  Fix: {v.get('fix_suggestion')}")
    return "\n".join(lines)


def _repo_enforcement_decision(repo_name: str, changed_files: Optional[List[Dict[str, str]]] = None, require_verified_closed: bool = True) -> Dict[str, Any]:
    repo_row = get_repository_by_name(repo_name)
    policy = _load_org_policy(current_organization_id())
    violations: List[Dict[str, Any]] = []
    assets = list_assets_by_repository(int(repo_row.get("id") or 0)) if repo_row else []
    for asset in assets:
        latest = _latest_full_scan_result_for_asset(asset.get("asset_key") or "") or {}
        risk = str(latest.get("risk_level") or "").strip().lower()
        hndl = str(latest.get("harvest_now_decrypt_later_risk") or "").strip().lower()
        provider = str(latest.get("provider_guess") or "unknown").strip().lower()
        if risk == "critical" and bool(policy.get("fail_ci_on_critical_asset", True)):
            violations.append(
                {
                    "kind": "asset_policy",
                    "asset_key": asset.get("asset_key"),
                    "risk_level": risk,
                    "scan_id": latest.get("scan_id") or "",
                    "message": "linked asset has critical posture",
                }
            )
        if hndl == "critical" and bool(policy.get("fail_ci_on_critical_asset", True)):
            violations.append(
                {
                    "kind": "quantum_policy",
                    "asset_key": asset.get("asset_key"),
                    "harvest_now_decrypt_later_risk": hndl,
                    "provider": provider,
                    "message": "linked asset has critical harvest-now/decrypt-later exposure",
                }
            )
        if provider == "unknown" and bool(policy.get("unknown_provider_blocks")):
            violations.append(
                {
                    "kind": "provider_policy",
                    "asset_key": asset.get("asset_key"),
                    "provider": provider,
                    "message": "TLS provider is unknown and policy blocks unknown provider posture",
                }
            )
        if bool(policy.get("fail_ci_on_banned_crypto", True)):
            region = _asset_region(asset)
            crypto_text = _crypto_tokens(latest)
            for rule in policy.get("banned_crypto_rules") or []:
                if not isinstance(rule, dict):
                    continue
                regions = {str(x or "").strip().lower() for x in (rule.get("regions") or [])}
                algorithms = [str(x or "").strip().lower().replace("_", "-") for x in (rule.get("algorithms") or [])]
                region_matches = not regions or region in regions
                algorithm_matches = any(algo and algo in crypto_text for algo in algorithms)
                if region_matches and algorithm_matches:
                    violations.append(
                        {
                            "kind": "crypto_policy",
                            "rule_id": str(rule.get("id") or "banned-crypto"),
                            "asset_key": asset.get("asset_key"),
                            "region": region,
                            "algorithms": algorithms,
                            "message": str(rule.get("message") or "Asset uses crypto banned by organization policy."),
                        }
                    )

    if require_verified_closed and violations:
        verified = [
            row
            for row in list_remediations(repo_id=int(repo_row.get("id") or 0), status="verified_closed", limit=1000)
        ] if repo_row else []
        if verified:
            violations = []

    if bool(policy.get("fail_ci_on_iac_policy_violation", True)):
        for file_item in changed_files or []:
            content = str((file_item or {}).get("content") or "")
            file_path = str((file_item or {}).get("file_path") or "main.tf")
            if not content.strip():
                continue
            check = evaluate_iac_security_content(content, file_path=file_path)
            for finding in check.get("findings") or []:
                violations.append({"kind": "iac_security", **finding})

    failed = bool(violations)
    return {
        "status": "FAIL" if failed else "PASS",
        "state": "failure" if failed else "success",
        "exit_code": 1 if failed else 0,
        "description": "PQC/security policy violations block merge" if failed else "PQC/security policy passed",
        "policy_version": policy.get("version") or "v1",
        "repo": repo_row or {"name": repo_name, "synced": False},
        "assets_checked": len(assets),
        "violations": violations,
    } | _enrich_gate_decision({"violations": violations})



