@app.post("/v1/code/github-crypto-discovery")
def api_v1_code_github_crypto_discovery(req: GithubCryptoDiscoveryRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    _require_role(request, allowed_roles=["operator", "admin"], action="v1.code.github_crypto_discovery", resource_type="repository", resource_id=req.repository)
    idem = _reserve_idempotency_or_raise(
        request,
        action="v1.code.github_crypto_discovery",
        payload=_model_payload(req),
    )
    if idem.get("replay"):
        return idem.get("response") or {}
    fetched = _github_fetch_repo_crypto_files(req)
    result = _discover_crypto_legacy_usage(fetched["files"], limit=req.max_files)
    remediation_candidates = []
    created = []
    migration_tasks = []
    created_migration_tasks = []
    repo_id = _repo_id_for_name(req.repository)
    asset_key = str(req.asset_key or "").strip()
    for finding in result.get("findings", [])[:50]:
        vuln = (
            f"Legacy crypto migration candidate in {req.repository}:{finding.get('path')}:{finding.get('line')}. "
            f"{finding.get('legacy_dependency')} -> {finding.get('migration_target')}. "
            f"Next step: {finding.get('safe_next_step')}"
        )
        candidate = {
            "repository": req.repository,
            "repository_id": repo_id,
            "asset_key": asset_key,
            "file_path": finding.get("path") or "",
            "rule_id": finding.get("rule_id") or "",
            "severity": finding.get("severity") or "",
            "safety_class": finding.get("safety_class") or "manual_review",
            "confidence": finding.get("confidence") or "low",
            "safety_reason": finding.get("safety_reason") or "",
            "recommended_workflow": finding.get("recommended_workflow") or "",
            "can_create_candidate": str(finding.get("can_create_candidate") or "").lower() == "true",
            "vulnerability": vuln,
            "suggested_fix": finding.get("safe_next_step") or "",
            "blocked": not bool(repo_id and asset_key) or str(finding.get("can_create_candidate") or "").lower() != "true",
            "blocker": (
                "" if repo_id and asset_key and str(finding.get("can_create_candidate") or "").lower() == "true"
                else ("asset_key and synced repository_id are required to create a remediation record" if not (repo_id and asset_key) else "finding is a migration task or manual review item, not a safe auto-candidate")
            ),
        }
        if bool(req.create_candidates) and repo_id and asset_key and str(finding.get("can_create_candidate") or "").lower() == "true":
            row = create_remediation(
                asset_key,
                repo_id,
                str(finding.get("path") or ""),
                vuln,
                str(finding.get("safe_next_step") or "Create a PQC migration patch and validate it."),
                original_content="",
                suggested_content="",
                status="candidate",
                review_note=f"Repository crypto discovery candidate. safety_class={finding.get('safety_class')}; confidence={finding.get('confidence')}; reason={finding.get('safety_reason')}",
                origin_kind="repo_crypto_discovery",
            )
            candidate["remediation_id"] = row.get("id")
            created.append(row)
        if str(finding.get("safety_class") or "").strip().lower() == "migration_task":
            task_candidate = {
                "repository": req.repository,
                "repository_id": repo_id,
                "asset_key": asset_key,
                "file_path": finding.get("path") or "",
                "rule_id": finding.get("rule_id") or "",
                "legacy_dependency": finding.get("legacy_dependency") or "",
                "migration_target": finding.get("migration_target") or "",
                "safety_class": finding.get("safety_class") or "migration_task",
                "confidence": finding.get("confidence") or "medium",
                "safety_reason": finding.get("safety_reason") or "",
                "recommended_workflow": finding.get("recommended_workflow") or "",
            }
            if bool(req.create_migration_tasks):
                row = create_migration_task(
                    asset_key_str=asset_key,
                    repository_name=req.repository,
                    repo_id=repo_id,
                    file_path=str(finding.get("path") or ""),
                    rule_id=str(finding.get("rule_id") or ""),
                    legacy_dependency=str(finding.get("legacy_dependency") or ""),
                    migration_target=str(finding.get("migration_target") or ""),
                    safety_class=str(finding.get("safety_class") or "migration_task"),
                    confidence=str(finding.get("confidence") or "medium"),
                    safety_reason=str(finding.get("safety_reason") or ""),
                    recommended_workflow=str(finding.get("recommended_workflow") or ""),
                    source="repo_crypto_discovery",
                )
                task_candidate["migration_task_id"] = row.get("id")
                created_migration_tasks.append(row)
            migration_tasks.append(task_candidate)
        remediation_candidates.append(candidate)
    response = {
        "api_version": "v1",
        "organization_id": org_id,
        "repository": req.repository,
        "ref": req.ref or "HEAD",
        "generated_at": _now_iso(),
        "tree_entries": fetched["tree_entries"],
        "candidate_files": fetched["candidate_files"],
        "fetched_files": fetched["fetched_files"],
        **result,
        "remediation_candidates": remediation_candidates,
        "created_total": len(created),
        "migration_tasks": migration_tasks,
        "created_migration_tasks_total": len(created_migration_tasks),
        "created_migration_tasks": created_migration_tasks,
    }
    if idem.get("enabled"):
        complete_idempotency_key(key=str(idem.get("key") or ""), action="v1.code.github_crypto_discovery", response=response)
    return response


