@app.post("/v1/cloud/hndl-audit")
def api_v1_cloud_hndl_audit(req: HndlAuditRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    _require_role(request, allowed_roles=["operator", "admin"], action="v1.cloud.hndl_audit", resource_type="organization", resource_id=org_id)
    objects = [_score_hndl_object(obj) for obj in req.objects]
    risk_rank = {"critical": 4, "high": 3, "medium": 2, "low": 1}
    critical = sum(1 for x in objects if x["risk"] == "critical")
    high = sum(1 for x in objects if x["risk"] == "high")
    avg_score = round(sum(float(x["score"]) for x in objects) / max(1, len(objects)), 1)
    return {
        "api_version": "v1",
        "organization_id": org_id,
        "generated_at": _now_iso(),
        "objects_total": len(objects),
        "critical_total": critical,
        "high_total": high,
        "average_hndl_score": avg_score,
        "portfolio_risk": max((x["risk"] for x in objects), key=lambda r: risk_rank.get(r, 0), default="none"),
        "objects": sorted(objects, key=lambda x: (-risk_rank.get(x["risk"], 0), -int(x["score"]))),
    }


@app.post("/v1/cloud/aws-s3-hndl-inventory")
def api_v1_cloud_aws_s3_hndl_inventory(req: AwsS3HndlInventoryRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    _require_role(request, allowed_roles=["operator", "admin"], action="v1.cloud.aws_s3_hndl_inventory", resource_type="organization", resource_id=org_id)
    idem = _reserve_idempotency_or_raise(request, action="v1.cloud.aws_s3_hndl_inventory", payload=_model_payload(req))
    if idem.get("replay"):
        return idem.get("response") or {}
    inventory = _aws_s3_hndl_inventory(req)
