# ── Cryptographically Signed PQC Compliance Attestations ─────────────────────

class ZkProofRequest(BaseModel):
    standard: str = Field(default="NIST_SP_800_208")


@app.post("/zk-compliance/generate")
@app.post("/v1/zk-compliance/generate")
def api_zk_generate(req: ZkProofRequest, request: Request):
    """
    Generate a cryptographically signed compliance attestation for your PQC posture.
    Uses a hash-based commitment scheme (NOT a ZK-SNARK). The attestation can be
    shared with auditors as supporting evidence without revealing the raw crypto config.
    """
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, allowed_roles=["operator", "admin"],
                  action="zk_compliance.generate", resource_type="organization", resource_id=org_id)

    from db import list_assets, latest_scan_result_for_asset
    assets_raw = list_assets(limit=200) or []
    assets = []
    for a in assets_raw:
        latest = latest_scan_result_for_asset(a.get("asset_key") or "") or {}
        assets.append({
            # An asset with no scan has no key. It used to be reported as RSA-2048 over TLS 1.2 —
            # a fabricated observation fed into an attestation an auditor reads. Unknown is
            # unknown: "" and 0, which every consumer already treats as "not observed".
            "key_type":   str(latest.get("cert_key_type") or latest.get("key_type") or ""),
            "key_bits":   int(latest.get("cert_key_bits") or latest.get("key_bits") or 0),
            "tls_version": str(latest.get("tls_version") or ""),
            "risk_level": str(latest.get("quantum_risk_level") or "unknown"),
        })

    proof = _generate_compliance_proof(
        org_id=org_id,
        scan_summary={"assets": assets},
        standard=req.standard,
    )
    proof["api_version"] = "v1"
    return proof


