@app.post("/binary/entropy-hunt")
@app.post("/v1/binary/entropy-hunt")
async def api_binary_entropy_hunt(request: Request, file: UploadFile = File(...), window_size: int = Query(4096, ge=256, le=65536)):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, allowed_roles=["operator", "analyst", "admin", "owner"],
                  action="binary.entropy_hunt", resource_type="organization", resource_id=org_id)
    data = await file.read()
    if len(data) > 100 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="File too large (max 100 MB)")
    result = _asm_entropy_hunt(file.filename or "upload.bin", data, window_size=window_size)
    result["api_version"] = "v1"
    result["organization_id"] = org_id
    return result


