@app.post("/insurance/proof-of-agility/verify")
@app.post("/v1/insurance/proof-of-agility/verify")
def api_insurance_proof_of_agility_verify(req: ProofOfAgilityVerifyRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="insurance.proof_of_agility_verify", resource_type="organization", resource_id=org_id)
    envelope = dict(req.envelope or {})
    supplied = envelope.pop("signature", {}) or {}
    expected = _airlock_sign(envelope)
    valid = bool(supplied.get("value")) and hmac.compare_digest(str(expected.get("value")), str(supplied.get("value")))
    payload = envelope.get("payload") or {}
    return {
        "api_version": "v1",
        "kind": "pqc_proof_of_agility_verification",
        "valid": valid,
        "signature": {"expected_kid": expected.get("kid"), "supplied_kid": supplied.get("kid")},
        "organization_id": envelope.get("organization_id") or "",
        "proof_hash": payload.get("proof_hash") or "",
        "public_claim": payload.get("public_claim") or {},
    }



