    """
    Scan package manifests for quantum-vulnerable cryptographic dependencies.
    Supports package.json, requirements.txt, Cargo.toml, pom.xml, go.mod.
    """
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
