class CicdGateScanRequest(BaseModel):
    filename: str
    content: str

class CicdGateDiffRequest(BaseModel):
    diff_text: str

class CicdGateWebhookRequest(BaseModel):
    payload: Dict[str, Any]
    diff_text: str = ""

class SastScanFileRequest(BaseModel):
    filename: str
    content: str

class SastScanRepoRequest(BaseModel):
    files: List[Dict[str, str]]  # [{filename, content}]

class SastScanGithubRequest(BaseModel):
    github_token: str
    repo_full_name: str
    branch: str = "main"
    max_files: int = Field(default=150, le=500)

class MaturityAssessRequest(BaseModel):
    domain_scores: Optional[Dict[str, float]] = None
    scan_summary: Optional[Dict[str, Any]] = None
    org_name: str = "Organization"
    has_canaries: bool = False
    has_qtisn: bool = False
    has_supply_chain: bool = False
    has_zk_proofs: bool = False
    has_autopilot: bool = False
    has_cicd_gate: bool = False
    has_regulatory_filings: bool = False

class ObsBaselineRequest(BaseModel):
    asset_key: str
    scan_result: Dict[str, Any]

class ObsRecordScanRequest(BaseModel):
    asset_key: str
    host: str
    port: int = 443
    scan_result: Dict[str, Any]

class ObsTriggerRequest(BaseModel):
    asset_keys: Optional[List[str]] = None
    max_assets: int = Field(default=50, le=200)

class VendorCompareRequest(BaseModel):
    vendor_ids: List[str] = Field(..., min_length=2, max_length=4)

class HybridCertRequest(BaseModel):
    common_name: str
    san_domains: List[str] = Field(default_factory=list)
    san_ips: List[str] = Field(default_factory=list)
    classical_algo: str = "RSA-2048"
    pqc_algo: str = "ML-KEM-768"
    validity_days: int = Field(default=365, ge=1, le=3650)
    org_name: str = "Organization"
    country: str = "US"

class HybridCsrRequest(BaseModel):
    common_name: str
    classical_algo: str = "RSA-2048"
    pqc_algo: str = "ML-KEM-768"
    org_name: str = ""
    country: str = "US"


