@app.post("/cicd-gate/scan-file")
@app.post("/v1/cicd-gate/scan-file")
def api_gate_scan_file(req: CicdGateScanRequest, request: Request):
    """Scan a single file for quantum-vulnerable crypto patterns."""
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, allowed_roles=["operator", "admin"],
                  action="cicd_gate.scan_file", resource_type="organization", resource_id=org_id)
    findings = _gate_scan_file(req.filename, req.content)
    critical = sum(1 for f in findings if f["severity"] == "critical")
    high = sum(1 for f in findings if f["severity"] == "high")
    return {"api_version": "v1", "findings": findings, "total": len(findings),
            "critical_count": critical, "high_count": high,
            "passed": critical == 0 and high == 0}


