@app.post("/v1/remediation-candidates")
def api_v1_remediation_candidates(req: RemediationCandidatesRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    _require_role(request, allowed_roles=["operator", "admin"], action="v1.remediation_candidates", resource_type="organization", resource_id=org_id)
    _require_org_feature(org_id, "remediation_candidates", "Remediation candidate creation")
    idem = _reserve_idempotency_or_raise(request, action="v1.remediation_candidates", payload=_model_payload(req))
    if idem.get("replay"):
        return idem.get("response") or {}
    wanted = {str(x).strip() for x in req.asset_keys if str(x or "").strip()}
    assets = list_assets(limit=10000)
    if wanted:
        assets = [a for a in assets if str(a.get("asset_key") or "").strip() in wanted]
    candidates = []
    created = []
    # One pass over the scan list for the whole inventory. Calling
    # _latest_full_scan_result_for_asset() per asset re-listed up to 100 scans and re-loaded every
    # one of them for each asset -- the same N+1 that made /hndl/dashboard take 82 s, here on a
    # write path. _latest_full_scan_result_lookup() answers identically and loads each scan once.
    scoped = assets[: max(1, min(int(req.limit or 100), 1000))]
    latest_for = _latest_full_scan_result_lookup(
        fallback_keys=[str(a.get("asset_key") or "").strip() for a in scoped])
    for asset in scoped:
        ak = str(asset.get("asset_key") or "").strip()
        latest = latest_for(ak)
        hndl = str(latest.get("harvest_now_decrypt_later_risk") or "unknown").lower()
        status = str(latest.get("pqc_migration_status") or "not_assessed")
        repo_id = int(asset.get("repository_id") or 0)
        if hndl not in {"critical", "high"} and status not in {"actionable_migration_path", "blocked_by_provider_or_config"}:
            continue
        provider = str(latest.get("provider_guess") or "unknown").lower()
        actions = latest.get("pqc_migration_actions") or []
        blockers = latest.get("pqc_blockers") or []
        vuln = (
            f"Post-quantum migration candidate for {ak}. "
            f"HNDL risk={hndl}; provider={provider}; status={status}. "
            f"Next action: {(blockers or actions or ['classify asset and link repository'])[0]}"
        )
        candidate = {
            "asset_key": ak,
            "repository_id": repo_id,
            "repository": asset.get("repository_name") or "",
            "provider": provider,
            "hndl_risk": hndl,
            "status": status,
            "file_path": "infra/tls-policy.tf",
            "vulnerability": vuln,
            "suggested_fix": "Create a crypto-agility/TLS policy change, validate it in the sandbox, then open a PR when repository access is available.",
            "blocked": not bool(repo_id),
            "blocker": "" if repo_id else "repository link missing",
        }
        if req.create_records and repo_id:
            row = create_remediation(
                ak,
                repo_id,
                "infra/tls-policy.tf",
                vuln,
                candidate["suggested_fix"],
                original_content="",
                suggested_content="",
                status="candidate",
                review_note="Autonomous remediation candidate. Requires human review and repository file selection.",
                origin_kind="auto_candidate",
            )
            candidate["remediation_id"] = row.get("id")
            created.append(row)
        candidates.append(candidate)
    response = {
        "api_version": "v1",
        "generated_at": _now_iso(),
        "candidates_total": len(candidates),
        "created_total": len(created),
        "candidates": candidates,
    }
    if idem.get("enabled"):
        complete_idempotency_key(key=str(idem.get("key") or ""), action="v1.remediation_candidates", response=response)
    return response


@app.post("/v1/policy/evaluate")
def api_v1_policy_evaluate(req: PolicyEvaluateRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    _require_role(request, allowed_roles=["operator", "admin"], action="v1.policy.evaluate", resource_type="organization", resource_id=org_id)
    policy = _load_org_policy(org_id)
    wanted = {str(x).strip() for x in req.asset_keys if str(x or "").strip()}
    assets = list_assets(limit=10000)
    if wanted:
        assets = [a for a in assets if str(a.get("asset_key") or "").strip() in wanted]
    decisions = []
    emitted = []
    # Same N+1 as /v1/remediation-candidates above, and the same fix: list and load each scan once.
    scoped = assets[: max(1, min(int(req.limit or 500), 5000))]
    latest_for = _latest_full_scan_result_lookup(
        fallback_keys=[str(a.get("asset_key") or "").strip() for a in scoped])
    for asset in scoped:
        ak = str(asset.get("asset_key") or "").strip()
        latest = latest_for(ak)
        decision = _decision_from_asset(asset, latest, policy)
        item = {"asset_key": ak, "decision": decision, "latest_scan_id": latest.get("scan_id") or "", "provider": latest.get("provider_guess") or "unknown"}
        decisions.append(item)
        if req.emit_events and decision.get("status") in {"warn", "block"}:
            ev_type = "asset.policy_blocked" if decision.get("status") == "block" else "asset.policy_warning"
            emitted.append(emit_platform_event(ev_type, item, dedupe_key=f"{ev_type}:{ak}:{latest.get('scan_id') or 'none'}"))
    return {"api_version": "v1", "generated_at": _now_iso(), "policy": policy, "decisions": decisions, "events": emitted}


