def _actor_from_request(request: Request) -> Dict[str, str]:
    claims = getattr(request.state, "auth_claims", {}) if hasattr(request.state, "auth_claims") else {}
    if isinstance(claims, dict) and claims:
        actor = _actor_from_claims(claims)
        actor_id = actor["actor_id"]
        actor_role = actor["actor_role"]
    else:
        actor_id = str(request.headers.get("x-user-id") or "local-user").strip() or "local-user"
        actor_role = str(request.headers.get("x-user-role") or DEFAULT_USER_ROLE).strip().lower()
    if actor_role not in VALID_USER_ROLES:
        actor_role = DEFAULT_USER_ROLE if DEFAULT_USER_ROLE in VALID_USER_ROLES else "viewer"
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    try:
        member = get_organization_member(org_id, actor_id)
        if member and str(member.get("status") or "").lower() == "active":
            member_role = str(member.get("role") or "").strip().lower()
            if member_role in VALID_USER_ROLES:
                actor_role = member_role
    except Exception as _actor_exc:
        logging.debug("[AUTH] Actor context resolution failed: %s", _actor_exc)
    return {"actor_id": actor_id, "actor_role": actor_role}


def _github_repo_token_or_502(credential_id: int, repo_name: str) -> str:
    resolved = resolve_github_repo_token(int(credential_id), str(repo_name or "").strip())
    if not resolved.get("ok"):
        raise HTTPException(status_code=502, detail={"error": "failed to resolve github repository token", "github": resolved})
    token = str(resolved.get("token") or "").strip()
    if not token:
        raise HTTPException(status_code=400, detail="github credential resolved to an empty token")
    return token


def _reserve_idempotency_or_raise(request: Request, *, action: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    key = idempotency_key_from_request(request)
    if not key:
        return {"enabled": False, "key": ""}
    reserved = reserve_idempotency_key(
        key=key,
        action=action,
        request_hash=idempotency_fingerprint(payload),
    )
    mode = str(reserved.get("mode") or "")
    if mode == "replay":
        return {"enabled": True, "key": key, "replay": True, "response": reserved.get("response") or {}}
    if mode == "conflict":
        raise HTTPException(status_code=409, detail=str(reserved.get("reason") or "idempotency key conflict"))
    if mode == "in_progress":
        raise HTTPException(status_code=409, detail="request with this idempotency key is already in progress")
    return {"enabled": True, "key": key, "replay": False}


#: Only the safe methods defer their "allowed" audit record. A write is recorded on the request,
#: so the entry is durable before the change it authorizes is answered for.
_AUDIT_DEFERRABLE_METHODS = frozenset({"GET", "HEAD", "OPTIONS"})


def _audit_event(
    request: Request,
    *,
    action: str,
    resource_type: str,
    resource_id: str = "",
    decision: str = "allow",
    reason: str = "",
    details: Optional[Dict[str, Any]] = None,
    required: bool = False,
    actor: Optional[Dict[str, str]] = None,
    defer: bool = False,
) -> None:
    """Record one authorization decision.

    `defer`: this is a routine `decision="allow"` record of a read, and may be written by the
    background audit writer instead of on the request (services/audit_queue). It is queued only
    while that writer is healthy and has room; otherwise, and for every other kind of entry, it is
    written here and `required=True` still fails the request closed when the write fails. A
    refusal, a cross-tenant attempt or an operator action is never deferred.
    """
    actor = actor or _actor_from_request(request)
    entry = {
        "actor_id": actor["actor_id"],
        "actor_role": actor["actor_role"],
        "action": action,
        "resource_type": resource_type,
        "resource_id": resource_id,
        "decision": decision,
        "reason": reason,
        "details": details or {},
    }
    if defer and decision == "allow" and _audit_queue.submit(current_organization_id(), entry):
        _security_journal.mark_success("actions")
        return
    try:
        append_audit_log(**entry)
        _security_journal.mark_success("actions")
    except Exception:
        _security_journal.mark_failure("actions")
        if PRODUCTION_ENVIRONMENT and required:
            raise HTTPException(503, "Audit storage unavailable; operation was not authorized")


#: Refused when a caller names an organization that is not theirs. Says where the capability does
#: live, because a platform operator hitting this is on the wrong route, not short of a permission.
CROSS_TENANT_DETAIL = (
    "This organization is not yours. A customer administrator manages only the organizations they "
    "belong to; cross-tenant administration is a platform-operator action under /platform/customers/."
)


def _caller_can_act_for_org(request: Request, organization_id: str, actor: Dict[str, str]) -> bool:
    """True when this caller is genuinely acting for `organization_id`.

    ONE rule: the organization must be the one this request resolved to -- the org claim on the
    verified token, or the organization an API key is bound to. Never the x-org-id header once
    authenticated, and never "the caller is an admin of some tenant".

    Holding a membership of the target is deliberately NOT enough. A credential is scoped to one
    tenant at a time, so a user who belongs to two organizations cannot act in one while carrying a
    token minted for the other; they switch with POST /auth/switch-organization, which checks the
    membership and mints a token for the new tenant. That keeps the authorization decision equal to
    the tenant the database connection is already scoped to under row-level security, instead of
    letting a request reach across the scope its own connection has open.
    """
    target = str(organization_id or "").strip()
    if not target:
        return False
    return target == _org(request)


def _require_role(
    request: Request,
    allowed_roles: List[str],
    action: str,
    resource_type: str,
    resource_id: str = "",
    organization_id: Optional[str] = None,
) -> Dict[str, str]:
    """Authorize a request by role and, when `organization_id` is given, by tenant.

    `organization_id` is the organization the handler is about to act on -- the one taken from the
    path, body or query. Passing it is what stops "role-checked but not tenant-checked": without it
    an administrator of any tenant satisfied every /admin/orgs/{org_id}/... route for every other
    tenant. Pass it on any route that names an organization it did not resolve from the request.
    """
    actor = _actor_from_request(request)
    allowed = {str(r or "").strip().lower() for r in allowed_roles}
    if actor["actor_role"] not in allowed:
        reason = f"role '{actor['actor_role']}' is not allowed for {action}"
        _audit_event(
            request,
            action=action,
            resource_type=resource_type,
            resource_id=resource_id,
            decision="deny",
            reason=reason,
            details={"allowed_roles": sorted(list(allowed))},
            actor=actor,
        )
        raise HTTPException(status_code=403, detail=reason)
    if organization_id is not None and not _caller_can_act_for_org(request, organization_id, actor):
        _audit_event(
            request,
            action=action,
            resource_type=resource_type,
            resource_id=resource_id,
            decision="deny",
            reason="target organization is outside the caller's tenant",
            details={"target_organization_id": str(organization_id or ""), "caller_organization_id": _org(request)},
            actor=actor,
        )
        raise HTTPException(status_code=403, detail=CROSS_TENANT_DETAIL)
    # Pass the actor through: resolving it again repeated the organization-membership lookup on every
    # authorized request.
    #
    # defer=True: this is the routine "allowed" record that every authorized request writes. It is
    # handed to the background audit writer -- in order, chained, and read back by anything that
    # lists or verifies the log -- so a dashboard read does not pay for an extra transaction. The
    # two denials above are never deferred, and this one falls back to a synchronous, fail-closed
    # write the moment that writer is unhealthy or its queue is full.
    _audit_event(
        request,
        action=action,
        resource_type=resource_type,
        resource_id=resource_id,
        decision="allow",
        details={"allowed_roles": sorted(list(allowed))},
        required=True,
        actor=actor,
        defer=request.method.upper() in _AUDIT_DEFERRABLE_METHODS,
    )
    _ai_privacy.ACTOR.set(str(actor["actor_id"]))
    return actor






def _org(request: Request) -> str:
    return str(
        getattr(request.state, "org_id", None) or current_organization_id() or DEFAULT_ORG_ID
    ).strip() or DEFAULT_ORG_ID


def _actor_id(request: Request) -> str:
    """Return the calling user's actor ID from JWT claims or request headers."""
    claims = getattr(request.state, "auth_claims", {}) or {}
    if claims:
        actor = str(
            claims.get("sub") or claims.get("email") or claims.get("user_id") or ""
        ).strip()
        if actor:
            return actor
    return str(
        request.headers.get("x-pqc-user-id")
        or request.headers.get("x-user-id")
        or "anon"
    ).strip() or "anon"


def _parse_tool_api_keys() -> Dict[str, Dict[str, Any]]:
    """Parse PQC_TOOL_API_KEYS as name:key:scope1|scope2,rawkey or name:key:* entries."""
    out: Dict[str, Dict[str, Any]] = {}
    raw = str(os.getenv("PQC_TOOL_API_KEYS") or "").strip()
    if not raw:
        return out
    for index, item in enumerate([x.strip() for x in raw.split(",") if x.strip()], start=1):
        parts = item.split(":", 2)
        if len(parts) == 1:
            name, key, scopes = f"tool-{index}", parts[0], {"*"}
        elif len(parts) == 2:
            name, key, scopes = parts[0] or f"tool-{index}", parts[1], {"*"}
        else:
            name, key = parts[0] or f"tool-{index}", parts[1]
            scopes = {s.strip() for s in re.split(r"[|;\s]+", parts[2]) if s.strip()} or {"*"}
        if key:
            out[key] = {"name": name, "scopes": scopes}
    return out


def _tool_actor_from_request(request: Request, required_scope: str) -> Optional[Dict[str, str]]:
    provided = str(request.headers.get("x-tool-api-key") or "").strip()
    if not provided:
        return None
    tools = _parse_tool_api_keys()
    cfg = tools.get(provided)
    if not cfg:
        raise HTTPException(status_code=401, detail="Invalid external tool API key")
    scopes = set(cfg.get("scopes") or set())
    if "*" not in scopes and required_scope not in scopes:
        raise HTTPException(status_code=403, detail=f"External tool API key lacks scope: {required_scope}")
    return {
        "actor_id": str(cfg.get("name") or "external-tool"),
        "actor_role": "operator",
    }


def _require_tool_or_role(
    request: Request,
    *,
    required_scope: str,
    allowed_roles: List[str],
    action: str,
    resource_type: str,
    resource_id: str = "",
) -> Dict[str, str]:
    tool_actor = _tool_actor_from_request(request, required_scope)
    if tool_actor:
        _audit_event(
            request,
            action=action,
            resource_type=resource_type,
            resource_id=resource_id,
            decision="allow",
            details={"auth_type": "tool_api_key", "scope": required_scope},
        )
        return tool_actor
    return _require_role(
        request,
        allowed_roles=allowed_roles,
        action=action,
        resource_type=resource_type,
        resource_id=resource_id,
    )


@app.post("/assistant/chat")
@limiter.limit(_RATE_ASSISTANT)
def assistant_chat(req: AssistantChatRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    actor = _require_role(
        request,
        allowed_roles=["viewer", "operator", "admin"],
        action="assistant.chat",
        resource_type="organization",
        resource_id=org_id,
    )
    ctx = _assistant_platform_context()
    fallback = _assistant_rule_response(req.message, ctx)
    safe_history: List[Dict[str, str]] = []
    for item in req.history[-8:]:
        if not isinstance(item, dict):
            continue
        safe_history.append({
            "role": str(item.get("role") or "")[:16],
            "content": _mask_secrets(str(item.get("content") or "")[:1000]),
        })
    result = _openai_assistant_intent(_mask_secrets(req.message), safe_history, ctx, fallback)
    result["organization_id"] = org_id
    result["actor_role"] = actor["actor_role"]
    result["platform_context"] = ctx
    result["allowed_intents"] = sorted(ASSISTANT_ALLOWED_INTENTS)
    _audit_event(
        request,
        action="assistant.intent",
        resource_type="organization",
        resource_id=org_id,
        decision="allow" if result.get("intent") != "out_of_scope" else "deny",
        reason=str(result.get("intent") or ""),
        details={
            "intent": result.get("intent"),
            "source": result.get("source"),
            "ai_enabled": bool(result.get("ai_enabled")),
            "actions": result.get("actions") or [],
            "missing_fields": result.get("missing_fields") or [],
            "target_present": bool(result.get("target")),
            "requires_confirmation": bool(result.get("requires_confirmation")),
        },
    )
    return result


# ── SSH scanning ──────────────────────────────────────────────────────────────

class SshScanRequest(BaseModel):
    targets: List[str] = Field(..., min_length=1, max_length=50)

@app.post("/scan/ssh")
def api_scan_ssh(req: SshScanRequest, request: Request):
    """Scan SSH endpoints for post-quantum readiness and weak algorithm detection."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="scan.ssh", resource_type="scan", resource_id="")
    from concurrent.futures import ThreadPoolExecutor as _TPE
    results = []
    with _TPE(max_workers=10) as pool:
        futures = {}
        for t in req.targets[:50]:
            t = t.strip()
            if not t:
                continue
            host, port = (t.rsplit(":", 1) if ":" in t else (t, "22"))
            try:
                port = int(port)
            except ValueError:
                port = 22
            futures[pool.submit(scan_ssh, host, port)] = t
        for fut, target in futures.items():
            try:
                results.append(fut.result(timeout=15))
            except Exception as exc:
                results.append({"host": target, "error": str(exc), "findings": []})
    return {"targets": len(results), "results": results}


# ── CBOM export ───────────────────────────────────────────────────────────────

@app.get("/scans/{scan_id}/cbom.json")
def api_cbom_export(scan_id: str, request: Request):
    """
    Export a CycloneDX 1.6 Cryptography Bill of Materials (CBOM) for a completed scan.
    Accepted by NIST, CISA, and enterprise procurement questionnaires.
    """
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="scan.cbom", resource_type="scan", resource_id=scan_id)
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    row = load_scan_row(scan_id)
    if not row:
        raise HTTPException(status_code=404, detail="Scan not found")
    results = row.get("results") or []
    cbom = generate_cbom(results, org_name=org_id, scan_id=scan_id)
    return JSONResponse(content=cbom, headers={
        "Content-Disposition": f'attachment; filename="cbom-{scan_id[:8]}.json"',
    })


