@app.get("/scans/{scan_id}/compliance/{framework}")
def api_compliance_report(scan_id: str, framework: str, request: Request):
    """
    Generate a compliance gap report mapping scan findings to a specific framework.

    Supported frameworks: nist-800-208, cnsa-2-0, iso-27001, pci-dss-4
    """
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="scan.compliance", resource_type="scan", resource_id=scan_id)
    if framework not in COMPLIANCE_FRAMEWORKS:
        raise HTTPException(status_code=400,
            detail=f"Unknown framework. Supported: {', '.join(COMPLIANCE_FRAMEWORKS)}")
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    row = load_scan_row(scan_id)
    if not row:
        raise HTTPException(status_code=404, detail="Scan not found")
    results = row.get("results") or []
    return generate_compliance_report(framework, results, org_name=org_id, scan_id=scan_id)


