class JiraCreateRequest(BaseModel):
    scan_id: str = Field(..., min_length=1)
    severity_filter: List[str] = Field(default_factory=lambda: ["critical", "high"])
    jira_url: str = Field("", max_length=256)
    jira_user: str = Field("", max_length=256)
    jira_api_token: str = Field("", max_length=512)
    project_key: str = Field("", max_length=32)
    issue_type: str = Field("Bug", max_length=64)
    extra_labels: List[str] = Field(default_factory=list, max_length=10)

class ServiceNowCreateRequest(BaseModel):
    scan_id: str = Field(..., min_length=1)
    severity_filter: List[str] = Field(default_factory=lambda: ["critical", "high"])
    snow_instance: str = Field("", max_length=256)
    snow_user: str = Field("", max_length=256)
    snow_password: str = Field("", max_length=512)
    table: str = Field("incident", max_length=64)
    assignment_group: str = Field("", max_length=128)

def _findings_for_ticketing(scan_id: str, severity_filter: List[str]) -> List[Dict[str, Any]]:
    row = load_scan_row(scan_id)
    if not row:
        raise HTTPException(status_code=404, detail="Scan not found")
    items = []
    for r in (row.get("results") or []):
        asset = f"{r.get('host', '')}:{r.get('port', 443)}"
        for f in (r.get("findings") or []):
            if f.get("severity") in severity_filter:
                items.append({"finding": f, "asset_key": asset})
    return items

@app.post("/integrations/jira/create-issues")
def api_jira_create(req: JiraCreateRequest, request: Request):
    """Push filtered findings from a scan to Jira as individual issues."""
    _require_role(request, allowed_roles=["operator", "admin"],
                  action="integration.jira.create", resource_type="scan", resource_id=req.scan_id)
    items = _findings_for_ticketing(req.scan_id, req.severity_filter)
    if not items:
        return {"created": 0, "message": "No findings matched the severity filter."}
    results = create_jira_issues_bulk(items,
        jira_url=req.jira_url, jira_user=req.jira_user,
        jira_api_token=req.jira_api_token, project_key=req.project_key,
        issue_type=req.issue_type, extra_labels=req.extra_labels)
    return {"created": sum(1 for r in results if r.get("success")),
            "failed":  sum(1 for r in results if not r.get("success")),
            "results": results}

@app.post("/integrations/servicenow/create-incidents")
def api_snow_create(req: ServiceNowCreateRequest, request: Request):
    """Push filtered findings from a scan to ServiceNow as incidents."""
    _require_role(request, allowed_roles=["operator", "admin"],
                  action="integration.snow.create", resource_type="scan", resource_id=req.scan_id)
    items = _findings_for_ticketing(req.scan_id, req.severity_filter)
    if not items:
        return {"created": 0, "message": "No findings matched the severity filter."}
    results = create_servicenow_bulk(items,
        snow_instance=req.snow_instance, snow_user=req.snow_user,
        snow_password=req.snow_password, table=req.table,
        assignment_group=req.assignment_group)
    return {"created": sum(1 for r in results if r.get("success")),
            "failed":  sum(1 for r in results if not r.get("success")),
            "results": results}


# ── Slack notification settings ───────────────────────────────────────────────

class SlackSettingsRequest(BaseModel):
    # All optional and defaulting to None so an omitted field is distinguishable
    # from one deliberately set. With concrete defaults here, the console's Save
    # -- which posts only webhook_url and channel -- silently reset min_severity
    # to "high", so an operator who had narrowed alerting to critical started
    # receiving high-severity ones again with nothing to indicate why.
    webhook_url: Optional[str] = Field(None, max_length=512)
    min_severity: Optional[str] = Field(None, pattern="^(critical|high|medium|low)$")
    enabled: Optional[bool] = None

@app.get("/integrations/slack/settings")
def api_slack_get(request: Request):
    _require_role(request, allowed_roles=["operator", "admin"],
                  action="integration.slack.read", resource_type="organization", resource_id="")
    return {
        "webhook_url":   get_integration_setting("slack_webhook_url", ""),
        "min_severity":  get_integration_setting("slack_min_severity", "high"),
        "enabled":       get_integration_setting("slack_enabled", "1") == "1",
    }

@app.post("/integrations/slack/settings")
def api_slack_save(req: SlackSettingsRequest, request: Request):
    _require_role(request, allowed_roles=["admin"],
                  action="integration.slack.write", resource_type="organization", resource_id="")
    # Only write what was actually sent; anything omitted keeps its value.
    if req.webhook_url is not None:
        set_integration_setting("slack_webhook_url", req.webhook_url.strip())
    if req.min_severity is not None:
        set_integration_setting("slack_min_severity", req.min_severity)
    if req.enabled is not None:
        set_integration_setting("slack_enabled", "1" if req.enabled else "0")
    return {"saved": True}

@app.post("/integrations/slack/test")
def api_slack_test(request: Request):
    _require_role(request, allowed_roles=["admin"],
                  action="integration.slack.test", resource_type="organization", resource_id="")
    url = get_integration_setting("slack_webhook_url", "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="No Slack webhook URL configured.")
    ok = _slack_test(url)
    if not ok:
        raise HTTPException(status_code=502, detail="Test message failed — check the webhook URL.")
    return {"sent": True}


