def _alert_notifications_snapshot() -> Dict[str, Any]:
    """The same notifications GET /platform/notifications derives, uncapped, for the alert dispatcher.

    The dispatcher runs outside any HTTP request, so it computes the go-live gate in-process without
    authentication instead of presenting the shared platform key (break-glass only in production).
    """
    from services import announcements as _ann
    hooks = {
        "go_live_gate": lambda: _platform_go_live_gate_result(),
        "security_findings": lambda: _list_external_findings(limit=200, status="open"),
        "incidents": lambda: _platform_incident_snapshot(),
        "abuse": lambda: {"generated_at": _platform_now_iso(), "rate_limited_events": list(_RATE_LIMIT_OBSERVATIONS)[-100:]},
        "maintenance": lambda: _ann.get_maintenance(),
    }
    return _platform_analytics.notifications(hooks, limit=1000)


# -----------------------------
# Helpers

def _severity_score(sev: str) -> int:
    s = (sev or "").lower()
    if s == "critical":
        return 4
    if s == "high":
        return 3
    if s == "medium":
        return 2
    if s == "low":
        return 1
    return 0


def _criticality_weight(crit: str) -> int:
    c = (crit or "").lower()
    if c == "tier-0":
        return 40
    if c == "tier-1":
        return 30
    if c == "tier-2":
        return 20
    if c == "tier-3":
        return 10
    return 0


def _conf_weight(conf: str) -> int:
    t = (conf or "").lower()
    # very rough parsing; user-entered field
    if "10" in t:
        return 15
    if "5" in t:
        return 10
    if "1" in t:
        return 5
    return 0


def _enrich_result_with_asset(result: Dict[str, Any]) -> Dict[str, Any]:
    """Attach inventory + baseline info to a scan result."""
    host = result.get("host") or ""
    port = result.get("port") if result.get("port") is not None else 443
    ak = f"{host}:{port}"
    result["asset_key"] = ak

    a = get_asset(ak)
    if a:
        result["asset"] = a
        # also flatten common fields for UI convenience
        for k in ["owner","team","environment","criticality","confidentiality_lifetime","notes","tags","updated_at"]:
            result[k] = a.get(k)
        # repo linkage
        result["repository_id"] = a.get("repository_id") or 0
        result["repository_name"] = a.get("repository_name") or ""
        result["repository_html_url"] = a.get("repository_html_url") or ""
    else:
        result["asset"] = None
        result["repository_id"] = 0
        result["repository_name"] = ""
        result["repository_html_url"] = ""

    b = get_baseline(ak)
    if b:
        result["baseline_scan_id"] = b.get("baseline_scan_id")
        result["baseline_set_at"] = b.get("set_at")
    return result


def _priority_score(result: Dict[str, Any]) -> float:
    # risk score (0-100 expected)
    rs = result.get("risk_score")
    if rs is None:
        rs = result.get("quantum_risk_score")
    try:
        rs_f = float(rs) if rs is not None else 0.0
    except Exception:
        rs_f = 0.0

    findings = result.get("findings") or []
    max_sev = 0
    for f in findings:
        max_sev = max(max_sev, _severity_score((f or {}).get("severity", "")))

    crit = (result.get("criticality") or (result.get("asset") or {}).get("criticality") or "")
    tags = (result.get("tags") or (result.get("asset") or {}).get("tags") or []) or []
    conf = (result.get("confidentiality_lifetime") or (result.get("asset") or {}).get("confidentiality_lifetime") or "")

    score = rs_f * 1.0 + max_sev * 20 + _criticality_weight(crit) + _conf_weight(conf)
    if any((t or "").lower() == "internet-facing" for t in tags):
        score += 15
    if any((t or "").lower() == "pqc" for t in tags):
        score += 5
    return float(round(score, 2))

# -----------------------------

def _progress(total: int, done: int) -> Dict[str, int]:
    pct = int((done * 100) / total) if total else 100
    if pct < 0:
        pct = 0
    if pct > 100:
        pct = 100
    return {"total": total, "done": done, "percent": pct}

def _utc_now() -> datetime:
    return datetime.now(timezone.utc)

def _format_utc_z(dt: datetime) -> str:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")

def _now_iso() -> str:
    """UTC timestamp in ISO 8601 with a trailing 'Z'."""
    return _format_utc_z(_utc_now())


def _parse_iso_datetime(value: Any) -> Optional[datetime]:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).astimezone(timezone.utc)
    except Exception:
        return None


def _openai_chat(prompt: str, *, model: str = "", timeout_s: int = 60) -> Dict[str, Any]:
    """Legacy response shape; every model dispatch uses the tenant's approved boundary."""
    try:
        conf = _ai_privacy.authorize(current_organization_id(), "remediation")
        if not conf["free_text"]:
            raise _ai_privacy.PrivacyError("Code generation requires explicit free-text sharing approval; metadata-only mode cannot send source code.")
        result = _ai_privacy.openai_completion(current_organization_id(), "remediation", {
            "model": model, "temperature": 0.2, "messages": [
                {"role": "system", "content": "You are a DevSecOps engineer. Return precise code changes for human review."},
                {"role": "user", "content": prompt},
            ]}, timeout=timeout_s)
        return {"ok": True, "json": result, "raw": json.dumps(result)}
    except _ai_privacy.PrivacyError as exc:
        raise HTTPException(exc.status, str(exc)) from None
    except Exception:
        return {"ok": False, "http_status": 503, "raw": "Approved AI request failed; no provider fallback was attempted."}


