def _emit_scan_telemetry(scan_id: str, result: Dict[str, Any], org_id: str, source: str) -> None:
    """Best-effort real telemetry emission for an actual scanner result."""
    try:
        host = str(result.get("host") or "").strip()
        port = int(result.get("port") or 443)
        risk = str(result.get("risk") or result.get("risk_level") or "unknown").lower()
        findings = result.get("findings") or []
        findings_count = len(findings) if isinstance(findings, list) else 0
        algorithm = str(result.get("algorithm") or result.get("cipher") or "")
        key_bits = int(result.get("key_bits") or result.get("rsa_bits") or 0)
        _tel_push("scan_complete", {
            "scan_id": scan_id,
            "host": host,
            "port": port,
            "risk_level": risk,
            "algorithm": algorithm,
            "key_bits": key_bits,
            "source": source,
        }, org_id or DEFAULT_ORG_ID)
        if risk in {"critical", "high"} or findings_count > 0:
            _tel_push("finding_new", {
                "scan_id": scan_id,
                "host": host,
                "port": port,
                "risk_level": risk,
                "findings_count": findings_count,
                "algorithm": algorithm,
                "description": "Scanner recorded high-risk or non-empty cryptographic findings.",
                "source": source,
            }, org_id or DEFAULT_ORG_ID)
    except Exception:
        logging.debug("[TELEMETRY] scan telemetry emission failed", exc_info=True)


@app.post("/scan")
@limiter.limit(_RATE_SCAN)
def scan_legacy(payload: ScanRequest, request: Request):
    results = []
    scan_id = str(uuid.uuid4())
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    for t in payload.targets:
        host, port = parse_target(t)
        result = scan_host(host, port)
        results.append(result)
        _emit_scan_telemetry(scan_id, result, org_id, "quick_scan")
    summary = summarize_results(results)
    return {"count": len(results), "scan_id": scan_id, "results": results, "summary": summary}


# -----------------------------
# Scans with IDs + progress
# -----------------------------

MAX_TARGETS = 200
MAX_TARGET_LEN = 255


def _scan_worker(scan_id: str, targets: List[str], organization_id: str = "") -> None:
    org_token = set_current_organization_id(organization_id or DEFAULT_ORG_ID)
    total = len(targets)
    done = 0
    results: List[Dict[str, Any]] = []

    try:
        # parallel-ish without overwhelming networks
        import concurrent.futures
        max_workers = min(20, max(1, total))
        with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as ex:
            future_map = {}
            for t in targets:
                host, port = parse_target(t)
                fut = ex.submit(scan_host, host, port)
                future_map[fut] = (host, port)

            for fut in concurrent.futures.as_completed(future_map):
                res = fut.result()
                results.append(res)
                _emit_scan_telemetry(scan_id, res, organization_id or DEFAULT_ORG_ID, "scan_worker")

                done += 1
                prog = _progress(total, done)

                _cache_update(scan_id, progress=prog, results=results)
                update_scan_progress(scan_id, status="running", progress=prog, error_text="")
                # keep partial results for reload
                save_scan_results(scan_id, results=results, summary={}, status="running")

        # finalize
        summary = summarize_results(results)
        prog = _progress(total, total)

        # The in-memory cache is a convenience, not a guarantee. A scan created by POST /scans is
        # persisted straight to SQLite without a cache entry, so _cache_get can legitimately return
        # None here; indexing it raised TypeError, which the handler below turned into status
        # "failed" even though every target had been scanned and saved successfully.
        cached = _cache_get(scan_id) or {}
        created_at = cached.get("created_at") or _utc_now()

        final_scan = {
            "id": scan_id,
            "status": "completed",
            "created_at": created_at,
            "progress": prog,
            "error": "",
            "results": results,
            "summary": summary,
        }
        _cache_put(final_scan)
        save_scan_results(scan_id, results=results, summary=summary, status="completed")
        # Sprint 5: persist per-asset summaries for history.
        #
        # Use _format_utc_z, not isoformat()+"Z": a timezone-aware datetime already ends in
        # "+00:00", so appending "Z" produced "...+00:00Z". SQLite stores that as text and never
        # complained, but Postgres rejects it as invalid timestamptz — which meant that on every
        # Postgres deployment this write raised, the exception below swallowed it, and scan_results
        # stayed permanently empty. Every report that reads it was therefore blank forever.
        try:
            scanned_at_iso = (
                _format_utc_z(created_at) if hasattr(created_at, "isoformat") else str(created_at)
            )
            save_scan_asset_summaries(scan_id, scanned_at_iso=scanned_at_iso, results=results)
        except Exception:
            # Still non-fatal — the scan itself succeeded — but never silent again.
            logging.exception("[SCAN] failed to persist per-asset summaries for %s", scan_id)
        update_scan_progress(scan_id, status="completed", progress=prog, error_text="")

        # Fire Slack alert (non-blocking, best-effort)
        try:
            from services.slack import notify_scan_complete
            app_url = str(os.getenv("PQC_APP_URL", "")).strip()
            notify_scan_complete(scan_id, targets, results,
                                 org_id=organization_id or DEFAULT_ORG_ID,
                                 app_url=app_url)
        except Exception:
            pass

    except Exception as e:
        prog = _progress(total, done)
        msg = str(e)
        # Log the traceback. Without it a failed scan surfaces only a bare message like
        # "'NoneType' object is not subscriptable" with no indication of where it came from,
        # which is close to undiagnosable in production.
        logging.exception("[SCAN] scan %s failed after %d/%d targets: %s", scan_id, done, total, msg)
        _cache_update(scan_id, status="failed", error=msg, progress=prog)
        update_scan_progress(scan_id, status="failed", progress=prog, error_text=msg)
    finally:
        reset_current_organization_id(org_token)


@app.post("/scans", response_model=ScanStatus)
@limiter.limit(_RATE_SCAN)
def create_scan(payload: ScanRequest, request: Request):
    if len(payload.targets) > MAX_TARGETS:
        raise HTTPException(status_code=400, detail=f"Too many targets. Max is {MAX_TARGETS}.")

    normalized: List[str] = []
    for t in payload.targets:
        if not t or len(t) > MAX_TARGET_LEN:
            raise HTTPException(status_code=400, detail="Invalid target.")
        normalized.append(t.strip())

    scan_id = str(uuid.uuid4())
    created_at = _utc_now()
    prog = _progress(len(normalized), 0)

    # Persist scan row immediately (queued)
    save_scan_row(
        scan_id=scan_id,
        status="queued",
        created_at=created_at,
        progress=prog,
        error_text="",
        results=[],
        summary={},
    )

    # Enqueue on Celery when a broker is reachable. That is the durable path: the job survives an
    # API restart and is retried by the worker. If the broker is unreachable, fall back to the same
    # in-process worker that _create_scan_and_start uses, so a single-node deployment with no
    # Celery/Redis still scans instead of returning 500. The fallback is not durable, which is why
    # the response reports "running" rather than "queued".
    org_id = getattr(request.state, "org_id", DEFAULT_ORG_ID)
    dispatch_error: Optional[str] = None
    res = None
    if _broker_reachable():
        try:
            res = run_scan_task.delay(scan_id, normalized, org_id)
        except Exception as exc:          # broker answered the probe but rejected the publish
            dispatch_error = str(exc)
    else:
        dispatch_error = "broker not reachable"

    if res is None:
        logging.warning(
            "[SCAN] Celery dispatch unavailable (%s); running scan %s in-process instead. "
            "Start a Celery worker and broker for durable, restart-safe scans.",
            dispatch_error, scan_id,
        )
        update_scan_job(scan_id, job_id="", job_state="INPROCESS")
        # Seed the in-memory cache the way _create_scan_and_start does, so progress polling and the
        # worker's finalize step see a consistent record.
        _cache_put({
            "id": scan_id, "status": "running", "created_at": created_at, "progress": prog,
            "error": "", "results": [], "summary": {},
            "meta": {"source": "api", "collection_id": None},
        })
        threading.Thread(
            target=_scan_worker, args=(scan_id, normalized, org_id), daemon=True
        ).start()
        return ScanStatus(
            job_id="",
            id=scan_id,
            status="running",
            created_at=created_at,
            progress=ScanProgress(**prog),
            error="",
        )

    update_scan_job(scan_id, job_id=res.id, job_state="PENDING")

    return ScanStatus(
        job_id=res.id,
        id=scan_id,
        status="queued",
        created_at=created_at,
        progress=ScanProgress(**prog),
        error="",
    )


def _normalize_synthetic_scan_results(results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(results, list) or not results:
        raise HTTPException(status_code=400, detail="results must contain at least one item")
    if len(results) > MAX_TARGETS:
        raise HTTPException(status_code=400, detail=f"Too many results. Max is {MAX_TARGETS}.")

    normalized: List[Dict[str, Any]] = []
    for idx, item in enumerate(results, start=1):
        if not isinstance(item, dict):
            raise HTTPException(status_code=400, detail=f"results[{idx}] must be an object")
        host = str(item.get("host") or item.get("hostname") or "").strip()
        if not host or len(host) > MAX_TARGET_LEN:
            raise HTTPException(status_code=400, detail=f"results[{idx}] has an invalid host")
        try:
            port = int(item.get("port") or 443)
        except Exception:
            raise HTTPException(status_code=400, detail=f"results[{idx}] has an invalid port")
        if port < 1 or port > 65535:
            raise HTTPException(status_code=400, detail=f"results[{idx}] has an invalid port")
        findings = item.get("findings")
        if findings is None:
            findings = []
        if not isinstance(findings, list):
            raise HTTPException(status_code=400, detail=f"results[{idx}] findings must be a list")

        row = dict(item)
        row["host"] = host
        row["port"] = port
        row["findings"] = findings
        if not (row.get("risk") or row.get("risk_level") or row.get("quantum_risk_level")):
            row["risk_level"] = "none" if not findings else "unknown"
        normalized.append(row)
    return normalized


@app.post("/scans/synthetic")
def create_synthetic_scan(request: SyntheticScanRequest, http_request: Request):
    actor = _require_role(
        http_request,
        allowed_roles=["admin"],
        action="scan.synthetic",
        resource_type="scan",
        resource_id=str(request.scan_id or "synthetic"),
    )
    results = _normalize_synthetic_scan_results(request.results)
    scan_id = str(request.scan_id or uuid.uuid4()).strip()
    created_at = request.created_at or _utc_now()
    progress = _progress(len(results), len(results))
    summary = summarize_results(results)

    save_scan_row(
        scan_id=scan_id,
        status="completed",
        created_at=created_at,
        progress=progress,
        error_text="",
        results=results,
        summary=summary,
    )
    save_scan_results(scan_id, results=results, summary=summary, status="completed")

    scanned_at_iso = created_at.isoformat()
    if created_at.tzinfo is None:
        scanned_at_iso += "Z"
    elif scanned_at_iso.endswith("+00:00"):
        scanned_at_iso = scanned_at_iso[:-6] + "Z"
    save_scan_asset_summaries(scan_id, scanned_at_iso=scanned_at_iso, results=results)

    verification = {"scan_id": scan_id, "assets_checked": 0, "closed": 0}
    if request.auto_close_merged:
        verification = auto_close_merged_remediations(scan_id, results)

    scan = load_scan_row(scan_id) or {
        "id": scan_id,
        "status": "completed",
        "created_at": created_at,
        "progress": progress,
        "error": "",
        "results": results,
        "summary": summary,
    }
    _cache_put(scan)
    return {
        "ok": True,
        "scan": ScanWithResults(
            job_id=str(scan.get("job_id") or ""),
            id=scan["id"],
            status=str(scan.get("status") or "completed"),
            created_at=scan["created_at"],
            progress=ScanProgress(**(scan.get("progress") or progress)),
            error=str(scan.get("error") or ""),
            results=scan.get("results") or results,
            summary=scan.get("summary") or summary,
        ).model_dump(),
        "verification": verification,
        "actor_id": actor["actor_id"],
        "actor_role": actor["actor_role"],
        # Results supplied directly by the caller (formerly labelled "synthetic";
        # nothing reads this field back, so older responses need no migration).
        "source": "direct",
    }



@app.get("/scans/{scan_id}", response_model=ScanStatus)
def get_scan(scan_id: str):
    # IMPORTANT: scans are executed asynchronously by Celery workers which update SQLite.
    # Do NOT rely on in-memory cache for non-terminal states, otherwise UI will never see updates.
    scan = load_scan_row(scan_id)
    if not scan:
        raise HTTPException(status_code=404, detail="Scan not found")

    # Cache only terminal states (optional perf)
    if (scan.get("status") or "").lower() in ("done", "completed", "failed"):
        _cache_put(scan)

    return ScanStatus(
        job_id=scan.get("job_id", "") or "",
        id=scan["id"],
        status=scan["status"],
        created_at=scan["created_at"],
        progress=ScanProgress(**(scan.get("progress") or {"total": 0, "done": 0, "percent": 0})),
        error=scan.get("error", "") or "",
    )



@app.get("/scans/{scan_id}/results", response_model=ScanWithResults)
def get_scan_results(scan_id: str):
    # Reload from SQLite so async worker updates are visible
    scan = load_scan_row(scan_id)
    if not scan:
        raise HTTPException(status_code=404, detail="Scan not found")

    if (scan.get("status") or "").lower() in ("done", "completed", "failed"):
        _cache_put(scan)

    # If scan is still running, you still get partial results.
    results = scan.get("results") or []
    # Enrich with asset inventory/baseline. Once: this line was duplicated, and
    # _enrich_result_with_asset issues two queries per result, so every scan's results were
    # costing twice the round trips they needed for an identical answer.
    results = [_enrich_result_with_asset(dict(r)) for r in results]
    summary = scan.get("summary") or (summarize_results(results) if results else {})

    return ScanWithResults(
        id=scan["id"],
        status=scan["status"],
        created_at=scan["created_at"],
        progress=ScanProgress(**(scan.get("progress") or {"total": 0, "done": 0, "percent": 0})),
        error=scan.get("error", "") or "",
        results=results,
        summary=summary,
    )


