@app.post("/assets/import-csv")
async def api_import_assets_csv(file: UploadFile = File(...), request: Request = None):
    """Bulk-import assets from a CSV file.

    Required column: ``host`` (or ``asset_key``).
    Optional columns: ``port``, ``owner``, ``team``, ``environment``, ``criticality``, ``tags``, ``description``.

    Returns a summary: imported, skipped, errors.
    """
    content = await file.read()
    try:
        text = content.decode("utf-8-sig")
    except Exception:
        text = content.decode("latin-1", errors="replace")

    reader = csv.DictReader(io.StringIO(text))
    imported, skipped, errors = 0, 0, []

    rows = list(reader)
    for i, row in enumerate(rows, start=2):  # row 1 is header
        host = str(row.get("host") or row.get("asset_key") or "").strip()
        if not host:
            skipped += 1
            continue
        try:
            port_raw = str(row.get("port") or "443").strip()
            port = int(port_raw) if port_raw.isdigit() else 443
            ak = f"{host}:{port}"
            tags_raw = str(row.get("tags") or "").strip()
            tags = [t.strip() for t in tags_raw.split(",") if t.strip()] if tags_raw else []
            upsert_asset(
                ak,
                owner=str(row.get("owner") or "").strip() or None,
                team=str(row.get("team") or "").strip() or None,
                environment=str(row.get("environment") or "").strip() or None,
                criticality=str(row.get("criticality") or "").strip() or None,
                tags=tags,
            )
            imported += 1
        except Exception as exc:
            errors.append({"row": i, "host": host, "error": str(exc)})

    return {"imported": imported, "skipped": skipped, "errors": errors}


