@app.get("/jobs/{job_id}")
def get_job(job_id: str):
    """Job state from the Celery result backend.

    Job state only exists while a broker is reachable. Without one this used to surface the raw
    driver error ("Error 10061 connecting to localhost:6379...") as a 500; report the dependency
    as unavailable instead, which is what it is.
    """
    if not _broker_reachable():
        raise HTTPException(
            status_code=503,
            detail=(
                "Job state is unavailable because the task broker cannot be reached. "
                "Start Redis and a Celery worker, or set CELERY_BROKER_URL. "
                "Scans still run in-process without a broker, but they do not produce job ids."
            ),
        )
    try:
        ar = celery_app.AsyncResult(job_id)
        meta = ar.info if isinstance(ar.info, dict) else {}
        return {
            "job_id": job_id,
            "state": ar.state,
            "meta": meta,
        }
    except Exception as e:
        logging.warning("[JOBS] result backend lookup failed for %s: %s", job_id, e)
        raise HTTPException(status_code=503, detail=f"Job state is unavailable: {e}")

