@app.post("/integrations/github/connect-token")
def api_connect_github_token(req: GithubTokenConnectRequest, request: Request):
    """
    One-step GitHub connection for demos and small customers.

    The token is stored as an org-scoped Vault credential, then optionally used
    immediately to sync repositories. The plaintext token is never returned.
    """
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="github.connect_token",
        resource_type="github_credential",
        resource_id=req.credential_name or "github-token",
    )
    token = str(req.token or "").strip()
    if not token:
        raise HTTPException(status_code=400, detail="GitHub token is required")

    visibility = str(req.visibility or "all").strip().lower() or "all"
    if visibility not in {"all", "private", "public"}:
        raise HTTPException(status_code=400, detail="visibility must be all, private, or public")
    org = str(req.org or "").strip()

    # Fail before storing the token if GitHub rejects it.
    try:
        from github import Github

        gh = Github(token)
        viewer = gh.get_user().login
        if org:
            gh.get_organization(org).login
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"GitHub token verification failed: {e}")

    base_name = str(req.credential_name or "").strip()
    if not base_name:
        suffix = org or viewer or "user"
        suffix = re.sub(r"[^A-Za-z0-9_.-]+", "-", suffix).strip("-") or "user"
        base_name = f"github-token-{suffix}"

    meta = {
        "kind": "github_pat",
        "org": org,
        "visibility": visibility,
        "created_by": getattr(request.state, "actor_id", "") or "ui",
        "created_from": "connect-token-ui",
    }
    row = None
    last_name = base_name
    for idx in range(0, 20):
        name = base_name if idx == 0 else f"{base_name}-{idx + 1}"
        row = create_credential(name, "github", token, meta)
        last_name = name
        if row:
            break
    if row is None:
        raise HTTPException(status_code=409, detail=f"credential name already exists: {last_name}")

    credential_id = int(row["id"])
    sync_result: Dict[str, Any] = {"ok": True, "skipped": True}
    if req.sync_now:
        sync_result = sync_github_repos(credential_id=credential_id, org=org or None, visibility=visibility)
        if not sync_result.get("ok"):
            return {
                "ok": False,
                "credential": row,
                "credential_id": credential_id,
                "verified_as": viewer,
                "sync": sync_result,
                "error": "credential saved, but repository sync failed",
            }

    return {
        "ok": True,
        "credential": row,
        "credential_id": credential_id,
        "verified_as": viewer,
        "sync": sync_result,
    }


def _normalize_bulk_targets(targets: List[str], targets_text: str) -> List[str]:
    raw: List[str] = []
    raw.extend([str(x or "").strip() for x in (targets or [])])
    for line in str(targets_text or "").replace(",", "\n").splitlines():
        line = line.strip()
        if line:
            raw.append(line)
    seen: set[str] = set()
    out: List[str] = []
    for item in raw:
        if not item:
            continue
        if "://" in item:
            item = item.split("://", 1)[1]
        if "/" in item:
            item = item.split("/", 1)[0]
        if ":" not in item:
            item = f"{item}:443"
        if len(item) > MAX_TARGET_LEN:
            raise HTTPException(status_code=400, detail=f"Invalid target: {item[:80]}")
        key = item.lower()
        if key not in seen:
            seen.add(key)
            out.append(item)
    if not out:
        raise HTTPException(status_code=400, detail="No targets provided")
    if len(out) > MAX_TARGETS:
        raise HTTPException(status_code=400, detail=f"Too many targets. Max is {MAX_TARGETS}.")
    return out


@app.post("/enterprise/bulk-onboard")
def api_enterprise_bulk_onboard(req: EnterpriseBulkOnboardRequest, request: Request):
    """Bulk enterprise onboarding: import endpoints, optionally sync repos, correlate, and start one portfolio scan."""
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="enterprise.bulk_onboard",
        resource_type="organization",
        resource_id=str(getattr(request.state, "org_id", DEFAULT_ORG_ID)),
    )
    targets = _normalize_bulk_targets(req.targets, req.targets_text)
    tags = [str(t).strip() for t in (req.tags or []) if str(t).strip()]
    if "pqc" not in [t.lower() for t in tags]:
        tags.append("pqc")
    if "hndl" not in [t.lower() for t in tags]:
        tags.append("hndl")

    assets: List[Dict[str, Any]] = []
    for target in targets:
        assets.append(
            upsert_asset(
                asset_key_str=target,
                owner=req.owner,
                team=req.team,
                environment=req.environment,
                criticality=req.criticality,
                confidentiality_lifetime=req.confidentiality_lifetime,
                tags=tags,
                metadata={"bulk_onboarded": True, "onboarded_at": _now_iso()},
            )
        )

    collection = upsert_collection(str(req.collection_name or "Enterprise Quantum Surface").strip(), "\n".join(targets))

    credential_id = 0
    verified_as = ""
    sync_result: Dict[str, Any] = {"skipped": True}
    correlate_result: Dict[str, Any] = {"skipped": True}
    token = str(req.github_token or "").strip()
    if token:
        connected = api_connect_github_token(
            GithubTokenConnectRequest(
                token=token,
                org=str(req.github_org or "").strip(),
                visibility=str(req.github_visibility or "all").strip() or "all",
                credential_name="enterprise-github-token",
                sync_now=bool(req.sync_repositories),
            ),
            request,
        )
        credential_id = int(connected.get("credential_id") or 0)
        verified_as = str(connected.get("verified_as") or "")
        sync_result = connected.get("sync") if isinstance(connected.get("sync"), dict) else {}
        if credential_id and req.correlate_repositories:
            correlate_result = correlate_assets(credential_id=credential_id, asset_limit=len(targets))

    scan: Dict[str, Any] = {"skipped": True}
    if req.run_scan:
        created_scan = create_scan(ScanRequest(targets=targets), request)
        if hasattr(created_scan, "model_dump"):
            scan = created_scan.model_dump(mode="json")
        else:
            scan = _model_payload(created_scan)

    portfolio = _build_quantum_migration_portfolio(
        str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID),
        scan_limit=50,
        asset_limit=10000,
    )

    return {
        "ok": True,
        "targets": targets,
        "assets_created_or_updated": len(assets),
        "collection": collection,
        "scan": scan,
        "credential_id": credential_id,
        "verified_as": verified_as,
        "sync": sync_result,
        "correlation": correlate_result,
        "portfolio_summary": portfolio.get("summary", {}),
        "next_steps": [
            "Wait for the scan to complete.",
            "Open Quantum Migration to review HNDL risk and blockers.",
            "Confirm owner/repo mappings that correlation could not resolve.",
            "Create remediations for assets with confirmed repository ownership.",
        ],
    }


