class WebhookIn(BaseModel):
    id: Optional[int] = None
    name: str = Field(..., min_length=1)
    url: str = Field(..., min_length=1)
    secret: str = ""  # legacy input (we will store in Vault)
    credential_id: Optional[int] = None  # NEW: preferred
    events: List[str] = Field(default_factory=lambda: ["*"])
    enabled: bool = True



@app.post("/integrations/webhooks")
def api_upsert_webhook(body: WebhookIn):
    """
    STRICT MODE:
    - enabled webhooks MUST have a credential_id (Vault secret).
    - If secret is provided once, we auto-create a Vault credential and store only credential_id.
    - We never store plaintext secrets in SQLite.
    """
    try:
        cred_id = int(body.credential_id) if body.credential_id else None
        if cred_id is None and body.id and not (body.secret or "").strip():
            existing = next((h for h in list_webhooks(limit=500) if int(h.get("id") or 0) == int(body.id)), None)
            if existing and existing.get("credential_id"):
                cred_id = int(existing["credential_id"])

        # If no credential_id but a secret is provided, auto-create Vault credential
        if cred_id is None and (body.secret or "").strip():
            meta = {"webhook_name": body.name, "url": body.url}
            cred = create_credential(
                name=f"webhook::{body.name}::{uuid.uuid4().hex}",
                provider="webhook",
                secret_plain=body.secret,
                meta=meta,
            )
            if not cred:
                raise HTTPException(status_code=500, detail="failed to create vault credential")
            cred_id = int(cred["id"])

        webhook_shape = {"url": body.url}
        if body.enabled and not cred_id and webhook_requires_credential(webhook_shape):
            raise HTTPException(
                status_code=400,
                detail="Vault required: set credential_id (or provide secret once to auto-create Vault credential) before enabling",
            )

        # Store NO plaintext secret in SQLite
        w = upsert_webhook(
            name=body.name,
            url=body.url,
            secret="",  # always blank now
            credential_id=cred_id,
            events=body.events,
            enabled=body.enabled,
            webhook_id=body.id,
        )
        w = dict(w or {})
        w.pop("secret", None)
        w["has_secret"] = bool(cred_id)
        w["secret_masked"] = "********" if cred_id else ""
        return {"ok": True, "webhook": w}
    except HTTPException:
        raise
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.post("/integrations/webhooks/{webhook_id}/rotate-secret")
def api_rotate_webhook_secret(webhook_id: int, body: dict | None = None):
    hooks = list_webhooks(limit=500)
    wh = next((h for h in hooks if int(h.get("id") or 0) == int(webhook_id)), None)
    if not wh:
        raise HTTPException(status_code=404, detail="webhook not found")
    secret = str((body or {}).get("secret") or "").strip()
    if not secret:
        raise HTTPException(status_code=400, detail="secret is required")
    cred_id = wh.get("credential_id")
    if not cred_id:
        cred = create_credential(
            name=f"webhook::{wh.get('name') or webhook_id}::{uuid.uuid4().hex}",
            provider="webhook",
            secret_plain=secret,
            meta={"webhook_name": wh.get("name"), "url": wh.get("url")},
        )
        if not cred:
            raise HTTPException(status_code=500, detail="failed to create vault credential")
        cred_id = int(cred["id"])
        upsert_webhook(
            name=str(wh.get("name") or ""),
            url=str(wh.get("url") or ""),
            secret="",
            credential_id=cred_id,
            events=wh.get("events") or ["*"],
            enabled=bool(wh.get("enabled")),
            webhook_id=int(webhook_id),
            rate_limit_per_minute=int(wh.get("rate_limit_per_minute") or 60),
            timeout_seconds=int(wh.get("timeout_seconds") or 10),
        )
    else:
        rotate_credential(int(cred_id), secret)
    out = next((h for h in list_webhooks(limit=500) if int(h.get("id") or 0) == int(webhook_id)), wh)
    out = dict(out or {})
    out.pop("secret", None)
    out["has_secret"] = True
    out["secret_masked"] = "********"
    return {"ok": True, "webhook": out}


@app.post("/integrations/webhooks/{webhook_id}/test")
def api_test_webhook(webhook_id: int):
    # STRICT MODE: do not allow unsigned test pings.
    try:
        # We need the webhook row to enforce credential_id presence.
        hooks = list_webhooks(limit=500, include_secret=False)
        wh = next((h for h in hooks if int(h.get("id")) == int(webhook_id)), None)
        if not wh:
            raise HTTPException(status_code=404, detail="webhook not found")

        if webhook_requires_credential(wh) and not wh.get("credential_id"):
            raise HTTPException(
                status_code=400,
                detail="This webhook has no credential_id (Vault secret). Attach a Vault credential before testing.",
            )

        return deliver_test_ping(int(webhook_id))

    except HTTPException:
        raise
    except Exception as e:
        # Never crash the API; this endpoint is for debugging integrations.
        return {"ok": False, "error": str(e)}


