@app.get("/integrations/settings")
def api_get_integration_settings():
    # UI settings live in SQLite (integrations_settings).
    # Keep this endpoint stable: old UIs expect cert_expiring_soon_days.
    try:
        days = int(get_integration_setting("cert_expiring_soon_days", "30"))
    except Exception:
        days = 30

    # Sprint 10.3: Cloudflare connector settings (optional)
    cf_raw = str(get_integration_setting("cloudflare_credential_id", "") or "").strip()
    try:
        cf_cred_id = int(cf_raw) if cf_raw else None
    except Exception:
        cf_cred_id = None

    # Extra toggles (safe defaults)
    record_suppressed = str(get_integration_setting("record_suppressed_events", "0") or "0").strip()

    return {
        "cert_expiring_soon_days": days,
        "cloudflare_credential_id": cf_cred_id,
        "cloudflare_connected_at": str(get_integration_setting("cloudflare_connected_at", "") or ""),
        "cloudflare_last_verified_at": str(get_integration_setting("cloudflare_last_verified_at", "") or ""),
        "cloudflare_last_verify_ok": str(get_integration_setting("cloudflare_last_verify_ok", "") or ""),
        "cloudflare_token_expires_on": str(get_integration_setting("cloudflare_token_expires_on", "") or ""),
        "cloudflare_last_zones_at": str(get_integration_setting("cloudflare_last_zones_at", "") or ""),
        "cloudflare_last_zones_count": str(get_integration_setting("cloudflare_last_zones_count", "") or ""),
        "cloudflare_last_rotated_at": str(get_integration_setting("cloudflare_last_rotated_at", "") or ""),
        "cloudflare_last_rotate_ok": str(get_integration_setting("cloudflare_last_rotate_ok", "") or ""),
        "cloudflare_last_rotate_error": str(get_integration_setting("cloudflare_last_rotate_error", "") or ""),
        "record_suppressed_events": 1 if record_suppressed == "1" else 0,
        "secret_backend": str(os.getenv("PQC_SECRET_BACKEND", "vault") or "vault").strip().lower(),
        "auth_mode": AUTH_MODE,
        "auth_required": AUTH_REQUIRED,
        "security_warnings": _security_warnings(),
    }


@app.put("/integrations/settings")
def api_put_integration_settings(body: dict):
    # Backward compatible: you can PUT only cert_expiring_soon_days like before.
    body = body or {}

    # --- cert_expiring_soon_days ---
    if "cert_expiring_soon_days" in body:
        try:
            days = int(body.get("cert_expiring_soon_days", 30))
        except Exception:
            days = 30
        days = max(1, min(36500, days))
        set_integration_setting("cert_expiring_soon_days", str(days))
    else:
        try:
            days = int(get_integration_setting("cert_expiring_soon_days", "30"))
        except Exception:
            days = 30

    # --- record_suppressed_events (0/1) ---
    if "record_suppressed_events" in body:
        v = str(body.get("record_suppressed_events", "0") or "0").strip()
        v = "1" if v in ("1", "true", "True", "yes", "on") else "0"
        set_integration_setting("record_suppressed_events", v)

    # --- cloudflare_credential_id (optional) ---
    if "cloudflare_credential_id" in body:
        raw = body.get("cloudflare_credential_id", None)
        if raw is None or str(raw).strip() == "":
            set_integration_setting("cloudflare_credential_id", "")
        else:
            try:
                cid = int(raw)
            except Exception:
                raise HTTPException(status_code=400, detail="cloudflare_credential_id must be an integer (or null to clear)")
            if cid < 1:
                raise HTTPException(status_code=400, detail="cloudflare_credential_id must be >= 1")
            # Validate Vault credential exists
            if not get_credential(cid, reveal=False):
                raise HTTPException(status_code=400, detail=f"Vault credential_id {cid} not found")
            set_integration_setting("cloudflare_credential_id", str(cid))
            # If we are newly connecting, set connected_at
            if not str(get_integration_setting("cloudflare_connected_at", "") or "").strip():
                set_integration_setting("cloudflare_connected_at", _now_iso())

    # Return the merged view
    return api_get_integration_settings()


