@app.post("/integrations/jira/create-issue")
async def api_jira_create_issue(request: Request):
    """Forward a finding directly to a Jira REST API instance.

    Body: { jira_url, project_key, issue_type, summary, description, api_token, email, asset_key, finding_ids }
    """
    body = await request.json()
    jira_url = str(body.get("jira_url") or "").rstrip("/")
    project_key = str(body.get("project_key") or "").strip()
    email = str(body.get("email") or "").strip()
    api_token = str(body.get("api_token") or "").strip()
    asset_key_val = str(body.get("asset_key") or "").strip()
    finding_ids = body.get("finding_ids") or []
    summary = str(body.get("summary") or f"[PQC] Quantum-vulnerable crypto detected: {asset_key_val}").strip()
    description_val = str(body.get("description") or (
        f"PQC Scanner detected quantum-vulnerable cryptography on asset: {asset_key_val}\n"
        f"Findings: {', '.join(str(x) for x in finding_ids)}\n\n"
        "Please review the remediation queue in PQC Scanner for suggested fixes."
    )).strip()
    issue_type = str(body.get("issue_type") or "Bug").strip()

    if not jira_url or not project_key or not email or not api_token:
        raise HTTPException(status_code=400, detail="jira_url, project_key, email, and api_token are required")

    import base64 as _b64
    credentials = _b64.b64encode(f"{email}:{api_token}".encode()).decode()
    payload = json.dumps({
        "fields": {
            "project": {"key": project_key},
            "summary": summary,
            "description": {
                "type": "doc",
                "version": 1,
                "content": [{"type": "paragraph", "content": [{"type": "text", "text": description_val}]}],
            },
            "issuetype": {"name": issue_type},
            "labels": ["pqc-scanner", "quantum-migration"],
        }
    }).encode()

    import urllib.request as _req
    import urllib.error as _uerr
    try:
        req = _req.Request(
            f"{jira_url}/rest/api/3/issue",
            data=payload,
            headers={"Content-Type": "application/json", "Authorization": f"Basic {credentials}"},
            method="POST",
        )
        with _req.urlopen(req, timeout=15) as resp:
            result = json.loads(resp.read(65536))
        return {"ok": True, "issue_key": result.get("key"), "issue_id": result.get("id"), "url": f"{jira_url}/browse/{result.get('key', '')}"}
    except _uerr.HTTPError as e:
        body_txt = ""
        try:
            body_txt = e.read(2048).decode("utf-8", "ignore")
        except Exception:
            pass
        raise HTTPException(status_code=e.code, detail=f"Jira API error: {e.reason}. {body_txt}")
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Could not reach Jira: {exc}")


