class CredentialCreate(BaseModel):
    name: str
    provider: str = "generic"
    secret: str
    meta: Dict[str, Any] = Field(default_factory=dict)

class CredentialRotate(BaseModel):
    secret: str


def _vault_or_503(fn, *args, **kwargs):
    """Run a credential-vault call, turning "not configured" into 503 rather than 500.

    The vault is Fernet encryption over PostgreSQL and has no SQLite equivalent, so on a
    SQLite-only deployment every one of these endpoints raised RuntimeError and surfaced as an
    opaque 500. Absent configuration is a deployment state, so report it as one and name the
    variables to set.
    """
    try:
        return fn(*args, **kwargs)
    except RuntimeError as exc:
        raise HTTPException(
            status_code=503,
            detail=(
                "Credential vault is not configured on this server. It requires "
                "DATABASE_URL (postgresql://...) and PQC_VAULT_MASTER_KEY. "
                f"({exc})"
            ),
        )


@app.post("/vault/credentials")
def vault_create(req: CredentialCreate, request: Request):
    _require_role(
        request,
        allowed_roles=["admin"],
        action="vault.create_credential",
        resource_type="vault_credential",
        resource_id=req.name,
    )
    row = _vault_or_503(create_credential, req.name, req.provider, req.secret, req.meta)
    if row is None:
        raise HTTPException(status_code=409, detail="credential name already exists")
    return row



