@app.post("/integrations/cloudflare/verify")
def api_cloudflare_verify():
    tok = _cf_get_token()
    r = _cf_api("GET", "/user/tokens/verify", tok, timeout_s=20)
    j = r.get("json") or {}
    ok = bool(j.get("success")) and int(r.get("http_status") or 0) == 200

    # Audit: store token metadata (no secret)
    try:
        res = j.get("result") or {}
        set_integration_setting("cloudflare_token_id", str(res.get("id") or ""))
        set_integration_setting("cloudflare_token_status", str(res.get("status") or ""))
        set_integration_setting("cloudflare_token_not_before", str(res.get("not_before") or ""))
        set_integration_setting("cloudflare_token_expires_on", str(res.get("expires_on") or ""))
    except Exception:
        pass

    set_integration_setting("cloudflare_last_verified_at", _now_iso())
    set_integration_setting("cloudflare_last_verify_ok", "1" if ok else "0")

    # DO NOT return the token (ever). Only return token metadata.
    return {
        "ok": ok,
        "http_status": int(r.get("http_status") or 0),
        "result": j.get("result") or {},
        "errors": j.get("errors") or [],
        "messages": j.get("messages") or [],
    }


@app.get("/integrations/cloudflare/zones")
def api_cloudflare_zones(per_page: int = 50):
    tok = _cf_get_token()
    per_page = max(1, min(int(per_page or 50), 200))
    r = _cf_api("GET", f"/zones?per_page={per_page}", tok, timeout_s=30)
    j = r.get("json") or {}

    if int(r.get("http_status") or 0) >= 400 or not isinstance(j, dict):
        raise HTTPException(status_code=502, detail={"http_status": int(r.get("http_status") or 0), "raw": r.get("raw")})

    res = j.get("result") or []
    zones = []
    for z in (res or []):
        if not isinstance(z, dict):
            continue
        zones.append(
            {
                "id": z.get("id"),
                "name": z.get("name"),
                "status": z.get("status"),
                "type": z.get("type"),
            }
        )
    # Audit: store last zones pull
    set_integration_setting("cloudflare_last_zones_at", _now_iso())
    set_integration_setting("cloudflare_last_zones_count", str(len(zones)))
    return {"ok": bool(j.get("success")), "zones_count": len(zones), "zones": zones}


@app.get("/integrations/cloudflare/my-ip")
def api_cloudflare_my_ip(req: Request):
    # Helpful for Cloudflare token IP allow-list setup.
    ip = (req.client.host if req and req.client else "") or ""
    return {"ip": ip}


@app.get("/integrations/cloudflare/summary")
def api_cloudflare_summary(req: Request):
    # One endpoint to quickly see "is it connected / does it work / do I have any zones"
    cid = _cf_get_credential_id()
    ip = (req.client.host if req and req.client else "") or ""
    if not cid:
        return {"connected": False, "cloudflare_credential_id": None, "ip": ip, "note": "Not connected. POST /integrations/cloudflare/connect with a Vault credential_id."}

    # Verify + Zones (never fail hard; return what we got)
    verify = api_cloudflare_verify()
    out: Dict[str, Any] = {
        "connected": True,
        "cloudflare_credential_id": int(cid),
        "ip": ip,
        "verify": verify,
    }

    try:
        zones = api_cloudflare_zones()
        out["zones_count"] = zones.get("zones_count", 0)
        out["zones"] = zones.get("zones", [])
        if int(out.get("zones_count") or 0) == 0:
            out["note"] = "zones_count=0 usually means: (1) your Cloudflare account has no zones, or (2) the token lacks 'Zone:Read' permission for any zone."
    except HTTPException as e:
        out["zones_count"] = 0
        out["zones"] = []
        out["zones_error"] = getattr(e, "detail", str(e))

    return out

