@app.get("/integrations/cloudflare/audit")
def api_cloudflare_audit():
    """
    Returns the latest Cloudflare policy-apply audit info recorded by _audit_cf_apply().
    Safe for UI display.
    """
    def _g(key: str, default: str = "") -> str:
        return str(get_integration_setting(key, default) or default)

    ops_raw = _g("cloudflare_last_apply_ops_json", "")
    ops: Any = []
    if ops_raw.strip():
        try:
            ops = json.loads(ops_raw)
        except Exception:
            ops = ops_raw  # fall back to raw string

    return {
        "ok": True,
        "last_apply_at": _g("cloudflare_last_apply_at", ""),
        "last_apply_zone_id": _g("cloudflare_last_apply_zone_id", ""),
        "last_apply_dry_run": _g("cloudflare_last_apply_dry_run", ""),
        "last_apply_ok": _g("cloudflare_last_apply_ok", ""),
        "last_apply_error": _g("cloudflare_last_apply_error", ""),
        "last_apply_ops": ops,
    }
