@app.post("/integrations/cloudflare/zones/mock/apply-policy")
def api_cloudflare_apply_policy_mock(body: CloudflareApplyMockIn, request: Request, dry_run: int = Query(1, ge=0, le=1)):
    """
    DRY-RUN apply without needing a real domain/zone.
    Uses simulated 'current' values from request body.
    """
    if PRODUCTION_ENVIRONMENT and not _ALLOW_DEMO_IN_PRODUCTION:
        raise HTTPException(status_code=403, detail="Cloudflare mock apply is disabled in production. Use the real zone endpoint with dry_run=1.")
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="cloudflare.mock_apply",
        resource_type="integration",
        resource_id="cloudflare",
    )
    try:
        pol = body.policy_override if isinstance(body.policy_override, dict) else _cf_load_policy()
        desired = _cf_policy_to_zone_settings(pol)

        current = {
            "always_use_https": str(body.current_always_use_https or "off").strip(),
            "min_tls_version": str(body.current_min_tls_version or "1.0").strip(),
        }
        zone_id = "mock-zone"
        ops = _cf_compute_patch_ops(zone_id, current=current, desired=desired)

        _audit_cf_apply(dry_run=bool(dry_run), zone_id=zone_id, ok=True, error="", ops=ops)
        return {
            "ok": True,
            "dry_run": bool(dry_run),
            "zone_id": zone_id,
            "current": current,
            "desired": desired,
            "would_patch_count": len(ops),
            "would_patch": ops,
            "note": "This is a mock apply. When you own a domain, use /integrations/cloudflare/zones/{zone_id}/apply-policy",
        }
    except Exception as e:
        _audit_cf_apply(dry_run=bool(dry_run), zone_id="mock-zone", ok=False, error=str(e), ops=[])
        return {"ok": False, "dry_run": bool(dry_run), "error": str(e)}

@app.post("/integrations/cloudflare/zones/{zone_id}/apply-policy")
def api_cloudflare_apply_policy_real(zone_id: str, request: Request, dry_run: int = Query(1, ge=0, le=1)):
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="cloudflare.apply_policy",
        resource_type="cloudflare_zone",
        resource_id=zone_id,
    )
    enforce_enabled = str(get_integration_setting("cloudflare_enforce_enabled", "0") or "0").strip() == "1"
    if int(dry_run) == 0 and not enforce_enabled:
        raise HTTPException(status_code=400, detail="Cloudflare enforcement disabled. Set integration setting cloudflare_enforce_enabled=1 to allow dry_run=0.")

    """
    Real zone apply.
    For now you will use dry_run=1 (no Cloudflare calls).
    Later when you own a domain: dry_run=0 will GET current settings + PATCH differences.
    """
    pol = _cf_load_policy()
    desired = _cf_policy_to_zone_settings(pol)

    # DRY RUN: don't call Cloudflare at all
    if int(dry_run) == 1:
        current = {"always_use_https": "(unknown)", "min_tls_version": "(unknown)"}
        ops = _cf_compute_patch_ops(zone_id, current=current, desired=desired)
        _audit_cf_apply(dry_run=True, zone_id=zone_id, ok=True, error="", ops=ops)
        return {
            "ok": True,
            "dry_run": True,
            "zone_id": zone_id,
            "desired": desired,
            "would_patch_count": len(ops),
            "would_patch": ops,
            "note": "Dry-run only. No Cloudflare API calls were made.",
        }

    # REAL MODE (later): GET current settings then PATCH diffs
    try:
        tok = _cf_get_token()

        cur_https = _cf_api("GET", f"/zones/{zone_id}/settings/always_use_https", tok)
        cur_tls = _cf_api("GET", f"/zones/{zone_id}/settings/min_tls_version", tok)

        if int(cur_https.get("http_status") or 0) >= 400:
            raise HTTPException(status_code=cur_https.get("http_status") or 400, detail=cur_https.get("raw") or "failed to read always_use_https")
        if int(cur_tls.get("http_status") or 0) >= 400:
            raise HTTPException(status_code=cur_tls.get("http_status") or 400, detail=cur_tls.get("raw") or "failed to read min_tls_version")

        # Cloudflare response format: { success, result: { id, value, ... } }
        cur_https_val = ""
        cur_tls_val = ""
        try:
            cur_https_val = str(((cur_https.get("json") or {}).get("result") or {}).get("value") or "")
            cur_tls_val = str(((cur_tls.get("json") or {}).get("result") or {}).get("value") or "")
        except Exception:
            pass

        current = {"always_use_https": cur_https_val, "min_tls_version": cur_tls_val}
        ops = _cf_compute_patch_ops(zone_id, current=current, desired=desired)

        applied: List[Dict[str, Any]] = []
        for op in ops:
            resp = _cf_api("PATCH", op["path"], tok, body_obj=op["body"])
            if int(resp.get("http_status") or 0) >= 400:
                raise HTTPException(status_code=resp.get("http_status") or 400, detail=resp.get("raw") or "patch failed")
            applied.append({"path": op["path"], "body": op["body"], "http_status": resp.get("http_status")})

        _audit_cf_apply(dry_run=False, zone_id=zone_id, ok=True, error="", ops=ops)
        return {
            "ok": True,
            "dry_run": False,
            "zone_id": zone_id,
            "current": current,
            "desired": desired,
            "applied_count": len(applied),
            "applied": applied,
        }
    except HTTPException as he:
        _audit_cf_apply(dry_run=False, zone_id=zone_id, ok=False, error=str(getattr(he, "detail", he)), ops=[])
        raise
    except Exception as e:
        _audit_cf_apply(dry_run=False, zone_id=zone_id, ok=False, error=str(e), ops=[])
        return {"ok": False, "dry_run": False, "zone_id": zone_id, "error": str(e)}


