def _circuit_breaker_mode(policy: Dict[str, Any], requested_mode: str = "") -> str:
    requested = str(requested_mode or "").strip().lower().replace("-", "_")
    configured = str(
        policy.get("circuit_breaker_mode")
        or policy.get("enforcement_mode")
        or "block"
    ).strip().lower().replace("-", "_")
    mode = requested if requested in {"monitor", "warn", "block"} else configured
    return mode if mode in {"monitor", "warn", "block"} else "block"


def _circuit_breaker_decision(req: CircuitBreakerEvaluateRequest, org_id: str) -> Dict[str, Any]:
    policy = _load_org_policy(org_id)
    require_verified = (
        bool(req.require_verified_closed)
        if req.require_verified_closed is not None
        else bool(policy.get("require_verified_closed_for_ci_gate", True))
    )
    gate = _repo_enforcement_decision(
        req.repo,
        changed_files=req.changed_files,
        require_verified_closed=require_verified,
    )
    mode = _circuit_breaker_mode(policy, req.mode)
    raw_violations = gate.get("violations") or []
    violation_count = len(raw_violations)
    has_violations = violation_count > 0
    if not has_violations:
        action = "allow"
        status = "PASS"
        state = "success"
        exit_code = 0
        description = "Deployment allowed: no blocking crypto/security policy violations found."
    elif mode == "monitor":
        action = "allow"
        status = "MONITOR"
        state = "success"
        exit_code = 0
        description = "Deployment allowed in monitor mode; violations recorded for governance review."
    elif mode == "warn":
        action = "warn"
        status = "WARN"
        state = "neutral"
        exit_code = 0
        description = "Deployment allowed with warning; violations require follow-up."
    else:
        action = "block"
        status = "BLOCK"
        state = "failure"
        exit_code = 1
        description = "Circuit breaker blocked deployment because crypto/security policy violations were found."
    ref = str(req.ref or req.branch or "").strip()
    return {
        "api_version": "v1",
        "organization_id": org_id,
        "generated_at": _now_iso(),
        "provider": str(req.provider or "github").strip().lower(),
        "repo": req.repo,
        "ref": ref,
        "branch": str(req.branch or "").strip(),
        "intent": str(req.intent or "deploy").strip() or "deploy",
        "actor_type": str(req.actor_type or "ci").strip().lower() or "ci",
        "actor_id": str(req.actor_id or "").strip(),
        "enforcement_mode": mode,
        "decision": action,
        "status": status,
        "state": state,
        "exit_code": exit_code,
        "description": description,
        "violations_total": violation_count,
        "blocking": action == "block",
        "policy_version": gate.get("policy_version") or policy.get("version") or "v1",
        "required_check_context": gate.get("required_check_context") or "pqc-scanner/security-policy",
        "merge_gate": gate.get("merge_gate") or {},
        "violations": raw_violations,
        "fix_suggestions": gate.get("fix_suggestions") or [],
        "deployment_context": req.deployment_context or {},
        "base_gate": gate,
    }


def _record_circuit_breaker_event(req: CircuitBreakerEvaluateRequest, request: Request, actor: Dict[str, Any], result: Dict[str, Any], action: str) -> None:
    str(result.get("organization_id") or current_organization_id())
    decision = str(result.get("decision") or "allow")
    append_flight_recorder_event(
        actor_id=str(req.actor_id or actor.get("actor_id") or "ci"),
        actor_type=str(req.actor_type or "ci"),
        actor_role=str(actor.get("actor_role") or "operator"),
        intent="block_deploy" if decision == "block" else "evaluate_deploy",
        resource_type="repository",
        resource_id=str(req.repo or ""),
        policy_version=str(result.get("policy_version") or "v1"),
        decision="blocked" if decision == "block" else ("warning" if decision == "warn" else "allowed"),
        outcome="succeeded",
        reason=str(result.get("description") or ""),
        evidence_refs={
            "repo": req.repo,
            "ref": result.get("ref") or "",
            "policy_version": result.get("policy_version") or "v1",
            "violations_total": result.get("violations_total") or 0,
            "required_check_context": result.get("required_check_context") or "",
        },
        details={
            "action": action,
            "enforcement_mode": result.get("enforcement_mode"),
            "deployment_context": req.deployment_context or {},
        },
    )
    append_audit_log(
        actor_id=str(actor.get("actor_id") or req.actor_id or "ci"),
        actor_role=str(actor.get("actor_role") or "operator"),
        action=action,
        resource_type="repository",
        resource_id=str(req.repo or ""),
        decision="deny" if decision == "block" else "allow",
        reason=str(result.get("description") or ""),
        details={
            "decision": decision,
            "status": result.get("status"),
            "enforcement_mode": result.get("enforcement_mode"),
            "violations_total": result.get("violations_total"),
            "ref": result.get("ref") or "",
        },
    )


def _changed_files_from_diff(diff_text: str) -> List[Dict[str, str]]:
    """Best-effort extraction of added lines from a unified diff for policy scanning."""
    raw = str(diff_text or "")
    if not raw.strip():
        return []
    files: List[Dict[str, str]] = []
    current_path = ""
    added: List[str] = []
    for line in raw.splitlines():
        if line.startswith("+++ "):
            if current_path and added:
                files.append({"file_path": current_path, "content": "\n".join(added)})
            current_path = line[4:].strip()
            if current_path.startswith("b/"):
                current_path = current_path[2:]
            if current_path == "/dev/null":
                current_path = ""
            added = []
            continue
        if not current_path:
            continue
        if line.startswith("+") and not line.startswith("+++"):
            added.append(line[1:])
        elif line.startswith(" ") and added:
            # Keep nearby context once a hunk starts so simple IaC regexes can match single-line and multi-line snippets.
            added.append(line[1:])
    if current_path and added:
        files.append({"file_path": current_path, "content": "\n".join(added)})
    return files


def _guardrails_changed_files(req: GuardrailsEvaluateChangeRequest) -> List[Dict[str, str]]:
    files: List[Dict[str, str]] = []
    for item in req.changed_files or []:
        if not isinstance(item, dict):
            continue
        file_path = str(item.get("file_path") or item.get("path") or "main.tf")[:500]
        content = str(item.get("content") or item.get("new_content") or item.get("patch") or "")[:200000]
        files.append({"file_path": file_path, "content": content})
    if req.proposed_diff:
        files.extend(_changed_files_from_diff(req.proposed_diff))
    return files[:200]


def _guardrails_result(req: GuardrailsEvaluateChangeRequest, org_id: str) -> Dict[str, Any]:
    changed_files = _guardrails_changed_files(req)
    cb_req = CircuitBreakerEvaluateRequest(
        repo=str(req.repo or "unscoped/change").strip() or "unscoped/change",
        ref=str(req.ref or req.branch or "").strip(),
        branch=str(req.branch or "").strip(),
        provider=str(req.provider or "github").strip() or "github",
        actor_type=str(req.actor_type or "ai_agent").strip() or "ai_agent",
        actor_id=str(req.actor_id or "").strip(),
        intent=str(req.intent or "propose_change").strip() or "propose_change",
        mode=str(req.mode or "block").strip(),
        require_verified_closed=req.require_verified_closed,
        changed_files=changed_files,
        deployment_context={
            "tool_source": str(req.tool_source or "").strip(),
            "metadata": req.metadata or {},
            "input_changed_files": len(req.changed_files or []),
            "diff_supplied": bool(str(req.proposed_diff or "").strip()),
        },
    )
    circuit = _circuit_breaker_decision(cb_req, org_id)
    decision = str(circuit.get("decision") or "allow").strip().lower()
    violations = circuit.get("violations") or []
    evidence_id = f"guardrail-{uuid.uuid4().hex[:16]}"
    return {
        "api_version": "v1",
        "kind": "guardrails.evaluate_change",
        "evidence_id": evidence_id,
        "organization_id": org_id,
        "generated_at": _now_iso(),
        "repo": cb_req.repo,
        "ref": cb_req.ref,
        "branch": cb_req.branch,
        "provider": cb_req.provider,
        "actor": {
            "type": cb_req.actor_type,
            "id": cb_req.actor_id,
            "tool_source": str(req.tool_source or "").strip(),
        },
        "intent": cb_req.intent,
        "decision": decision,
        "status": circuit.get("status"),
        "state": circuit.get("state"),
        "blocking": bool(circuit.get("blocking")),
        "enforcement_mode": circuit.get("enforcement_mode"),
        "required_check_context": circuit.get("required_check_context"),
        "policy_version": circuit.get("policy_version"),
        "summary": circuit.get("description"),
        "changed_files_evaluated": len(changed_files),
        "violations_total": len(violations),
        "violations": violations,
        "fix_suggestions": circuit.get("fix_suggestions") or [],
        "required_actions": (
            ["Fix blocking policy violations", "Run validation before merge", "Re-submit this endpoint before PR merge"]
            if decision == "block"
            else ["Run validation before merge", "Attach this evidence ID to the PR/check"]
        ),
        "mcp": {
            "tool_name": "evaluate_change_guardrails",
            "is_error": decision == "block",
        },
        "base_enforcement": circuit,
    }


