def _github_publish_state_for_circuit(result: Dict[str, Any], publish_mode: str) -> str:
    decision = str(result.get("decision") or "").strip().lower()
    if publish_mode == "check_run":
        if decision == "block":
            return "failure"
        if decision == "warn":
            return "neutral"
        return "success"
    return "failure" if decision == "block" else "success"


def _publish_circuit_breaker_github_check(req: CircuitBreakerEvaluateRequest, result: Dict[str, Any]) -> Dict[str, Any]:
    provider = str(req.provider or "github").strip().lower()
    if provider != "github":
        raise HTTPException(status_code=400, detail="required-check publishing currently supports provider=github only")
    ref = str(result.get("ref") or req.ref or "").strip()
    if not ref:
        raise HTTPException(status_code=400, detail="ref is required to publish a GitHub required check")
    if int(req.github_credential_id or 0) <= 0:
        raise HTTPException(status_code=400, detail="github_credential_id is required to publish a GitHub required check")
    publish_mode = str(req.publish_mode or "check_run").strip().lower().replace("-", "_")
    if publish_mode not in {"check_run", "status"}:
        raise HTTPException(status_code=400, detail="publish_mode must be either check_run or status")
    owner, repo = split_owner_repo(str(req.repo or "").strip())
    token = _github_repo_token_or_502(int(req.github_credential_id), str(req.repo or "").strip())
    context = str(result.get("required_check_context") or "pqc-scanner/security-policy")
    state = _github_publish_state_for_circuit(result, publish_mode)
    check_text = _github_check_text({
        **result,
        "violations": result.get("violations") or [],
    })
    if publish_mode == "check_run":
        published = github_create_check_run(
            owner,
            repo,
            ref,
            token,
            name=context,
            conclusion=state,
            summary=str(result.get("description") or "PQC circuit breaker decision"),
            text=check_text,
            details_url=str(req.target_url or "").strip(),
        )
    else:
        published = github_create_commit_status(
            owner,
            repo,
            ref,
            token,
            state=state,
            context=context,
            description=str(result.get("description") or "PQC circuit breaker decision"),
            target_url=str(req.target_url or "").strip(),
        )
    record_github_status_publish(
        repo=str(req.repo or "").strip(),
        ref=ref,
        context=context,
        publish_mode=publish_mode,
        state=state,
        target_url=str(req.target_url or "").strip(),
        ok=bool(published.get("ok")),
        http_status=int(published.get("http_status") or 0),
        response=published,
    )
    if not published.get("ok"):
        raise HTTPException(status_code=502, detail={"error": "failed to publish GitHub required check", "github": published})
    return {
        "published": True,
        "provider": "github",
        "publish_mode": publish_mode,
        "http_status": int(published.get("http_status") or 0),
        "context": context,
        "state": state,
        "target_url": str(req.target_url or "").strip(),
        "response": published,
    }


@app.post("/enforcement/evaluate")
@app.post("/v1/enforcement/evaluate")
def api_v1_enforcement_evaluate(req: CircuitBreakerEvaluateRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    # Called for its authorization check, which raises on denial; the returned actor is not needed
    # here. Kept as a bare call so that removing an unused binding can never remove the check.
    _require_role(request, allowed_roles=["viewer", "operator", "admin"], action="enforcement.evaluate", resource_type="repository", resource_id=req.repo)
    result = _circuit_breaker_decision(req, org_id)
    return result


@app.post("/guardrails/evaluate-change")
@app.post("/v1/guardrails/evaluate-change")
def api_v1_guardrails_evaluate_change(req: GuardrailsEvaluateChangeRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    actor = _require_tool_or_role(
        request,
        required_scope="guardrails:evaluate",
        allowed_roles=["viewer", "operator", "admin"],
        action="guardrails.evaluate_change",
        resource_type="repository",
        resource_id=str(req.repo or "unscoped/change"),
    )
    result = _guardrails_result(req, org_id)
    _record_guardrails_event(req, request, actor, result)
    return result


def _normalize_external_finding(f: ExternalFindingIn, tool_source: str) -> Dict[str, Any]:
    severity = str(f.severity or "medium").strip().lower()
    if severity not in {"critical", "high", "medium", "low", "info"}:
        severity = "medium"
    category = str(f.category or "").strip().lower().replace(" ", "_")
    external_id = str(f.external_id or "").strip() or f"{tool_source}-{uuid.uuid4().hex[:10]}"
    return {
        "external_id": external_id,
        "title": str(f.title or f.description or "External security finding").strip()[:500],
        "severity": severity,
        "category": category or "external",
        "resource_type": str(f.resource_type or "").strip(),
        "resource_id": str(f.resource_id or "").strip(),
        "repo": str(f.repo or "").strip(),
        "file_path": str(f.file_path or "").strip(),
        "line": int(f.line or 0),
        "description": str(f.description or "").strip(),
        "remediation": str(f.remediation or "").strip(),
        "evidence": f.evidence or {},
        "source": tool_source,
    }


def _ensure_security_truth_tables() -> None:
    if postgres_main_db_requested():
        with pg_product_conn() as conn, tolerate_missing_ddl_privilege(
            conn, ("external_findings",), "security truth"
        ):
            with conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS external_findings (
                        id BIGSERIAL PRIMARY KEY,
                        organization_id TEXT NOT NULL,
                        batch_id TEXT NOT NULL,
                        tool_source TEXT NOT NULL,
                        integration_type TEXT NOT NULL,
                        external_id TEXT DEFAULT '',
                        title TEXT DEFAULT '',
                        severity TEXT DEFAULT 'medium',
                        category TEXT DEFAULT 'external',
                        resource_type TEXT DEFAULT '',
                        resource_id TEXT DEFAULT '',
                        repo TEXT DEFAULT '',
                        file_path TEXT DEFAULT '',
                        line INTEGER DEFAULT 0,
                        description TEXT DEFAULT '',
                        remediation TEXT DEFAULT '',
                        evidence_json JSONB DEFAULT '{}'::jsonb,
                        status TEXT DEFAULT 'open',
                        write_path_request_id TEXT DEFAULT '',
                        created_at TEXT NOT NULL,
                        updated_at TEXT NOT NULL
                    )
                    """
                )
                for idx in (
                    "CREATE INDEX IF NOT EXISTS idx_external_findings_org ON external_findings(organization_id)",
                    "CREATE INDEX IF NOT EXISTS idx_external_findings_batch ON external_findings(batch_id)",
                    "CREATE INDEX IF NOT EXISTS idx_external_findings_severity ON external_findings(severity)",
                    "CREATE INDEX IF NOT EXISTS idx_external_findings_status ON external_findings(status)",
                    "CREATE INDEX IF NOT EXISTS idx_external_findings_repo ON external_findings(repo)",
                ):
                    cur.execute(idx)
            conn.commit()
        return
    with closing(get_connection()) as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS external_findings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                organization_id TEXT NOT NULL,
                batch_id TEXT NOT NULL,
                tool_source TEXT NOT NULL,
                integration_type TEXT NOT NULL,
                external_id TEXT DEFAULT '',
                title TEXT DEFAULT '',
                severity TEXT DEFAULT 'medium',
                category TEXT DEFAULT 'external',
                resource_type TEXT DEFAULT '',
                resource_id TEXT DEFAULT '',
                repo TEXT DEFAULT '',
                file_path TEXT DEFAULT '',
                line INTEGER DEFAULT 0,
                description TEXT DEFAULT '',
                remediation TEXT DEFAULT '',
                evidence_json TEXT DEFAULT '{}',
                status TEXT DEFAULT 'open',
                write_path_request_id TEXT DEFAULT '',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            )
            """
        )
        for idx in (
            "CREATE INDEX IF NOT EXISTS idx_external_findings_org ON external_findings(organization_id)",
            "CREATE INDEX IF NOT EXISTS idx_external_findings_batch ON external_findings(batch_id)",
            "CREATE INDEX IF NOT EXISTS idx_external_findings_severity ON external_findings(severity)",
            "CREATE INDEX IF NOT EXISTS idx_external_findings_status ON external_findings(status)",
            "CREATE INDEX IF NOT EXISTS idx_external_findings_repo ON external_findings(repo)",
        ):
            conn.execute(idx)
        conn.commit()


def _external_finding_from_row(row: Any) -> Dict[str, Any]:
    out = dict(row)
    raw_evidence = out.pop("evidence_json", "{}")
    if isinstance(raw_evidence, dict):
        out["evidence"] = raw_evidence
    else:
        try:
            out["evidence"] = json.loads(raw_evidence or "{}")
        except Exception:
            out["evidence"] = {}
    return out


def _save_external_findings(
    *,
    organization_id: str,
    batch_id: str,
    tool_source: str,
    integration_type: str,
    findings: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    _ensure_security_truth_tables()
    now = _now_iso()
    inserted: List[Dict[str, Any]] = []
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                for f in findings:
                    cur.execute(
                        """
                        INSERT INTO external_findings (
                            organization_id, batch_id, tool_source, integration_type, external_id, title, severity,
                            category, resource_type, resource_id, repo, file_path, line, description, remediation,
                            evidence_json, status, write_path_request_id, created_at, updated_at
                        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'open', '', %s, %s)
                        RETURNING *
                        """,
                        (
                            organization_id,
                            batch_id,
                            tool_source,
                            integration_type,
                            str(f.get("external_id") or ""),
                            str(f.get("title") or ""),
                            str(f.get("severity") or "medium"),
                            str(f.get("category") or "external"),
                            str(f.get("resource_type") or ""),
                            str(f.get("resource_id") or ""),
                            str(f.get("repo") or ""),
                            str(f.get("file_path") or ""),
                            int(f.get("line") or 0),
                            str(f.get("description") or ""),
                            str(f.get("remediation") or ""),
                            Json(f.get("evidence") or {}),
                            now,
                            now,
                        ),
                    )
                    row = cur.fetchone()
                    if row:
                        inserted.append(_external_finding_from_row(row))
            conn.commit()
        return inserted
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        for f in findings:
            cur = conn.execute(
                """
                INSERT INTO external_findings (
                    organization_id, batch_id, tool_source, integration_type, external_id, title, severity,
                    category, resource_type, resource_id, repo, file_path, line, description, remediation,
                    evidence_json, status, write_path_request_id, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'open', '', ?, ?)
                """,
                (
                    organization_id,
                    batch_id,
                    tool_source,
                    integration_type,
                    str(f.get("external_id") or ""),
                    str(f.get("title") or ""),
                    str(f.get("severity") or "medium"),
                    str(f.get("category") or "external"),
                    str(f.get("resource_type") or ""),
                    str(f.get("resource_id") or ""),
                    str(f.get("repo") or ""),
                    str(f.get("file_path") or ""),
                    int(f.get("line") or 0),
                    str(f.get("description") or ""),
                    str(f.get("remediation") or ""),
                    json.dumps(f.get("evidence") or {}, separators=(",", ":"), sort_keys=True),
                    now,
                    now,
                ),
            )
            row = conn.execute("SELECT * FROM external_findings WHERE id=?", (int(cur.lastrowid or 0),)).fetchone()
            if row:
                inserted.append(_external_finding_from_row(row))
        conn.commit()
    return inserted


def _list_external_findings(
    *,
    organization_id: str = "",
    limit: int = 100,
    severity: str = "",
    status: str = "",
    tool_source: str = "",
) -> List[Dict[str, Any]]:
    _ensure_security_truth_tables()
    limit = max(1, min(int(limit or 100), 500))
    clauses: List[str] = []
    params: List[Any] = []
    if organization_id:
        clauses.append("organization_id=?")
        params.append(organization_id)
    if severity:
        clauses.append("severity=?")
        params.append(str(severity).strip().lower())
    if status:
        clauses.append("status=?")
        params.append(str(status).strip().lower())
    if tool_source:
        clauses.append("tool_source=?")
        params.append(str(tool_source).strip())
    if postgres_main_db_requested():
        pg_clauses = [c.replace("?", "%s") for c in clauses]
        where = f"WHERE {' AND '.join(pg_clauses)}" if pg_clauses else ""
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    f"SELECT * FROM external_findings {where} ORDER BY id DESC LIMIT %s",
                    (*params, limit),
                )
                rows = cur.fetchall()
        return [_external_finding_from_row(r) for r in rows]
    where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            f"SELECT * FROM external_findings {where} ORDER BY id DESC LIMIT ?",
            (*params, limit),
        ).fetchall()
    return [_external_finding_from_row(r) for r in rows]


def _get_external_finding(finding_id: int, organization_id: str = "") -> Dict[str, Any]:
    _ensure_security_truth_tables()
    clauses = ["id=?"]
    params: List[Any] = [int(finding_id)]
    if organization_id:
        clauses.append("organization_id=?")
        params.append(organization_id)
    if postgres_main_db_requested():
        pg_clauses = [c.replace("?", "%s") for c in clauses]
        with pg_product_conn() as conn:
            with conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute(
                    f"SELECT * FROM external_findings WHERE {' AND '.join(pg_clauses)}",
                    tuple(params),
                )
                row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="External finding not found")
        return _external_finding_from_row(row)
    with closing(get_connection()) as conn:
        conn.row_factory = sqlite3.Row
        row = conn.execute(
            f"SELECT * FROM external_findings WHERE {' AND '.join(clauses)}",
            tuple(params),
        ).fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="External finding not found")
    return _external_finding_from_row(row)


def _mark_external_finding_write_path(finding_id: int, organization_id: str, request_id: str) -> None:
    _ensure_security_truth_tables()
    if postgres_main_db_requested():
        with pg_product_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE external_findings
                    SET status='fix_requested', write_path_request_id=%s, updated_at=%s
                    WHERE id=%s AND organization_id=%s
                    """,
                    (request_id, _now_iso(), int(finding_id), organization_id),
                )
                updated = int(cur.rowcount or 0)
            conn.commit()
        if updated <= 0:
            raise HTTPException(status_code=404, detail="External finding not found")
        return
    with closing(get_connection()) as conn:
        cur = conn.execute(
            """
            UPDATE external_findings
            SET status='fix_requested', write_path_request_id=?, updated_at=?
            WHERE id=? AND organization_id=?
            """,
            (request_id, _now_iso(), int(finding_id), organization_id),
        )
        conn.commit()
    if int(getattr(cur, "rowcount", 0) or 0) <= 0:
        raise HTTPException(status_code=404, detail="External finding not found")


def _create_write_path_fix_response(
    req: WritePathFixRequest,
    *,
    org_id: str,
    actor: Dict[str, str],
) -> Dict[str, Any]:
    request_id = f"fixreq-{uuid.uuid4().hex[:16]}"
    guardrails = _guardrails_result(
        GuardrailsEvaluateChangeRequest(
            repo=req.repo,
            ref=req.ref,
            branch=req.branch,
            actor_type="security_tool",
            actor_id=str(actor.get("actor_id") or ""),
            tool_source=req.tool_source,
            intent="request_fix",
            changed_files=req.changed_files,
            proposed_diff=req.proposed_diff,
            metadata={"finding_id": req.finding_id, **(req.metadata or {})},
        ),
        org_id,
    )
    blocked = str(guardrails.get("decision") or "").lower() == "block"
    status = "blocked_by_guardrails" if blocked else ("dry_run_ready" if req.dry_run else "accepted")
    plan = {
        "request_id": request_id,
        "status": status,
        "human_approval_required": True,
        "validation_required_before_pr": True,
        "create_remediation_requested": bool(req.create_remediation),
        "dry_run": bool(req.dry_run),
        "steps": [
            "Normalize external finding and proposed fix.",
            "Evaluate proposed change through Security Truth guardrails.",
            "Require human approval before write-path execution.",
            "Run validation sandbox before PR creation.",
            "Attach evidence ID to PR/check before merge.",
        ],
    }
    append_audit_log(
        actor_id=actor.get("actor_id") or "external-tool",
        actor_role=actor.get("actor_role") or "operator",
        action="write_path.fix_request",
        resource_type="repository",
        resource_id=str(req.repo or req.asset_key or "unscoped"),
        decision="deny" if blocked else "allow",
        reason=status,
        details={
            "request_id": request_id,
            "tool_source": req.tool_source,
            "finding_id": req.finding_id,
            "guardrails_evidence_id": guardrails.get("evidence_id"),
            "guardrails_decision": guardrails.get("decision"),
            "dry_run": bool(req.dry_run),
        },
    )
    return {
        "api_version": "v1",
        "organization_id": org_id,
        "request_id": request_id,
        "status": status,
        "repo": req.repo,
        "asset_key": req.asset_key,
        "finding_id": req.finding_id,
        "tool_source": req.tool_source,
        "desired_outcome": req.desired_outcome,
        "plan": plan,
        "guardrails": guardrails,
    }


@app.post("/integrations/findings/ingest")
@app.post("/v1/integrations/findings/ingest")
def api_v1_external_findings_ingest(req: ExternalFindingsIngestRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    actor = _require_tool_or_role(
        request,
        required_scope="findings:write",
        allowed_roles=["operator", "admin"],
        action="integrations.findings.ingest",
        resource_type="external_findings",
        resource_id=str(req.tool_source or "external"),
    )
    batch_id = f"findings-{uuid.uuid4().hex[:16]}"
    normalized = [_normalize_external_finding(f, req.tool_source) for f in req.findings]
    sev_rank = {"critical": 4, "high": 3, "medium": 2, "low": 1, "info": 0}
    counts: Dict[str, int] = defaultdict(int)
    for item in normalized:
        counts[str(item.get("severity") or "medium")] += 1
    top = sorted(normalized, key=lambda x: sev_rank.get(str(x.get("severity") or "medium"), 2), reverse=True)[:25]
    saved = _save_external_findings(
        organization_id=org_id,
        batch_id=batch_id,
        tool_source=req.tool_source,
        integration_type=req.integration_type,
        findings=normalized,
    )
    append_audit_log(
        actor_id=actor.get("actor_id") or "external-tool",
        actor_role=actor.get("actor_role") or "operator",
        action="integrations.findings.ingest",
        resource_type="external_findings",
        resource_id=batch_id,
        decision="allow",
        reason=f"ingested {len(normalized)} external findings from {req.tool_source}",
        details={
            "tool_source": req.tool_source,
            "integration_type": req.integration_type,
            "counts_by_severity": dict(counts),
            "top_findings": top,
            "metadata": req.metadata or {},
        },
    )
    return {
        "api_version": "v1",
        "batch_id": batch_id,
        "organization_id": org_id,
        "tool_source": req.tool_source,
        "integration_type": req.integration_type,
        "ingested": len(normalized),
        "persisted": len(saved),
        "finding_ids": [int(i.get("id") or 0) for i in saved],
        "counts_by_severity": dict(counts),
        "top_findings": top,
        "next_actions": [
            "Call /v1/write-path/fix-requests for findings that should enter remediation.",
            "Call /v1/guardrails/evaluate-change before opening or merging a proposed fix.",
        ],
    }


