@app.post("/integrations/ci/status-check")
def api_ci_status_check(req: CiStatusCheckRequest, request: Request):
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="ci.status_check",
        resource_type="repository",
        resource_id=req.repo,
    )
    decision = _repo_enforcement_decision(
        req.repo,
        changed_files=req.changed_files,
        require_verified_closed=bool(req.require_verified_closed),
    )
    idem = _reserve_idempotency_or_raise(
        request,
        action="ci.status_check",
        payload={
            "repo": req.repo,
            "ref": req.ref,
            "provider": req.provider,
            "require_verified_closed": req.require_verified_closed,
            "changed_files": req.changed_files,
            "github_credential_id": req.github_credential_id,
            "publish_to_github": req.publish_to_github,
            "publish_mode": req.publish_mode,
            "target_url": req.target_url,
        },
    )
    if idem.get("replay"):
        return idem.get("response") or {}
    context = "pqc-scanner/security-policy"
    github_status: Dict[str, Any] = {"published": False}
    provider = str(req.provider or "github").strip().lower()
    ref = str(req.ref or "").strip()
    publish_mode = str(req.publish_mode or "status").strip().lower().replace("-", "_")
    if bool(req.publish_to_github):
        if provider != "github":
            raise HTTPException(status_code=400, detail="publish_to_github currently supports provider=github only")
        if publish_mode not in {"status", "check_run"}:
            raise HTTPException(status_code=400, detail="publish_mode must be either status or check_run")
        if not ref:
            raise HTTPException(status_code=400, detail="ref is required when publishing a GitHub status/check")
        if int(req.github_credential_id or 0) <= 0:
            raise HTTPException(status_code=400, detail="github_credential_id is required when publishing a GitHub status/check")
        owner, repo = split_owner_repo(str(req.repo or "").strip())
        token = _github_repo_token_or_502(int(req.github_credential_id), str(req.repo or "").strip())
        check_text = _github_check_text(decision)
        if publish_mode == "check_run":
            conclusion = "success" if str(decision.get("state") or "") == "success" else "failure"
            published = github_create_check_run(
                owner,
                repo,
                ref,
                token,
                name=context,
                conclusion=conclusion,
                summary=str(decision.get("description") or "PQC/security policy decision"),
                text=check_text,
                details_url=str(req.target_url or "").strip(),
            )
        else:
            published = github_create_commit_status(
                owner,
                repo,
                ref,
                token,
                state=str(decision.get("state") or "failure"),
                context=context,
                description=str(decision.get("description") or "PQC/security policy decision"),
                target_url=str(req.target_url or "").strip(),
            )
        record_github_status_publish(
            repo=str(req.repo or "").strip(),
            ref=ref,
            context=context,
            publish_mode=publish_mode,
            state=str(decision.get("state") or "failure"),
            target_url=str(req.target_url or "").strip(),
            ok=bool(published.get("ok")),
            http_status=int(published.get("http_status") or 0),
            response=published,
        )
        if not published.get("ok"):
            raise HTTPException(status_code=502, detail={"error": "failed to publish GitHub status/check", "github": published})
        github_status = {
            "published": True,
            "publish_mode": publish_mode,
            "http_status": int(published.get("http_status") or 0),
            "context": context,
            "state": str(decision.get("state") or ""),
            "target_url": str(req.target_url or "").strip(),
        }
    response = {
        "provider": provider,
        "ref": ref,
        "context": context,
        "github_status": github_status,
        **decision,
    }
    if idem.get("enabled"):
        complete_idempotency_key(key=str(idem.get("key") or ""), action="ci.status_check", response=response)
    return response


@app.get("/api/v1/compliance/gate")
def api_compliance_gate(repo: str = Query("", min_length=1)):
    repo_row = get_repository_by_name(repo)
    if not repo_row:
        raise HTTPException(status_code=404, detail="repository not found; sync GitHub first")

    assets = list_assets_by_repository(repo_row["id"])
    if not assets:
        return {
            "repo": repo_row,
            "assets_checked": 0,
            "critical_assets": [],
            "exit_code": 0,
            "note": "No assets linked to this repository.",
        }

    critical_assets: List[Dict[str, Any]] = []
    inspected: List[Dict[str, Any]] = []

    for a in assets:
        latest = latest_scan_result_for_asset(a["asset_key"]) or {}
        risk = str(latest.get("risk_level") or "").lower()
        item = {
            "asset_key": a["asset_key"],
            "risk_level": risk or "unknown",
            "findings_count": int(latest.get("findings_count") or 0),
            "scanned_at": latest.get("scanned_at") or "",
            "scan_id": latest.get("scan_id") or "",
            "tags": a.get("tags") or [],
            "metadata": a.get("metadata") or {},
        }
        inspected.append(item)
        if risk == "critical":
            critical_assets.append(item)

    exit_code = 1 if critical_assets else 0
    status = "FAIL" if exit_code else "PASS"
    return {
        "repo": repo_row,
        "assets_checked": len(inspected),
        "critical_assets": critical_assets,
        "assets": inspected,
        "exit_code": exit_code,
        "status": status,
    }


@app.post("/mcp")
def api_mcp(req: McpRequest, request: Request):
    """Lightweight JSON-RPC MCP-style interface for IDE assistants."""
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="mcp.call",
        resource_type="mcp",
        resource_id=str(req.method or ""),
    )
    if req.method == "tools/list":
        return {
            "jsonrpc": "2.0",
            "id": req.id,
            "result": {
                "tools": [
                    {
                        "name": "check_iac_compliance",
                        "description": "Check Terraform/IaC text against the organization's PQC Scanner policy.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "content": {"type": "string"},
                                "file_path": {"type": "string"},
                            },
                            "required": ["content"],
                        },
                    },
                    {
                        "name": "check_repo_enforcement",
                        "description": "Check whether a repository currently passes the PQC/security merge gate.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "repo": {"type": "string"},
                                "changed_files": {"type": "array"},
                            },
                            "required": ["repo"],
                        },
                    },
                    {
                        "name": "evaluate_change_guardrails",
                        "description": "Security Truth API for AI agents: evaluate proposed repo/IaC changes before merge and return allow/warn/block with evidence.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "repo": {"type": "string"},
                                "ref": {"type": "string"},
                                "branch": {"type": "string"},
                                "tool_source": {"type": "string"},
                                "intent": {"type": "string"},
                                "mode": {"type": "string"},
                                "changed_files": {"type": "array"},
                                "proposed_diff": {"type": "string"},
                            },
                        },
                    },
                    {
                        "name": "get_asset_evidence",
                        "description": "Return machine-readable evidence for one asset, including quantum readiness, policy decision, remediations, validations, and evidence hash.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {"asset_key": {"type": "string"}},
                            "required": ["asset_key"],
                        },
                    },
                    {
                        "name": "get_repo_evidence",
                        "description": "Return machine-readable evidence and gate decision for one repository.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {"repo": {"type": "string"}},
                            "required": ["repo"],
                        },
                    },
                    {
                        "name": "discover_repo_ownership",
                        "description": "Score likely asset-to-repository ownership mappings from synced assets and repositories.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "asset_keys": {"type": "array"},
                                "repository_names": {"type": "array"},
                                "link_high_confidence": {"type": "boolean"},
                            },
                        },
                    },
                    {
                        "name": "get_provider_capabilities",
                        "description": "Return provider PQC/hybrid TLS capability guidance for Cloudflare, AWS, Google, Azure, Fastly, Akamai, customer TLS, and unknown.",
                        "inputSchema": {"type": "object", "properties": {"provider": {"type": "string"}}},
                    },
                    {
                        "name": "get_org_policy",
                        "description": "Return the active organization policy-as-code profile used by gates and evidence decisions.",
                        "inputSchema": {"type": "object", "properties": {}},
                    },
                ]
            },
        }
    if req.method == "tools/call":
        params = req.params or {}
        name = str(params.get("name") or "").strip()
        args = params.get("arguments") if isinstance(params.get("arguments"), dict) else {}
        if name == "check_iac_compliance":
            content = str((args or {}).get("content") or "")
            file_path = str((args or {}).get("file_path") or "main.tf")
            result = evaluate_iac_security_content(content, file_path=file_path)
        elif name == "check_repo_enforcement":
            result = _repo_enforcement_decision(
                str((args or {}).get("repo") or ""),
                changed_files=(args or {}).get("changed_files") or [],
            )
        elif name == "evaluate_change_guardrails":
            org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
            result = _guardrails_result(
                GuardrailsEvaluateChangeRequest(
                    repo=str((args or {}).get("repo") or ""),
                    ref=str((args or {}).get("ref") or ""),
                    branch=str((args or {}).get("branch") or ""),
                    provider=str((args or {}).get("provider") or "github"),
                    actor_type=str((args or {}).get("actor_type") or "ai_agent"),
                    actor_id=str((args or {}).get("actor_id") or ""),
                    tool_source=str((args or {}).get("tool_source") or "mcp"),
                    intent=str((args or {}).get("intent") or "propose_change"),
                    mode=str((args or {}).get("mode") or ""),
                    changed_files=(args or {}).get("changed_files") or [],
                    proposed_diff=str((args or {}).get("proposed_diff") or ""),
                    metadata=(args or {}).get("metadata") if isinstance((args or {}).get("metadata"), dict) else {},
                ),
                org_id,
            )
        elif name == "get_asset_evidence":
            result = _asset_evidence(str((args or {}).get("asset_key") or ""), str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID))
        elif name == "get_repo_evidence":
            result = _repo_evidence(str((args or {}).get("repo") or ""), str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID))
        elif name == "discover_repo_ownership":
            result = _repo_discovery_scores(
                asset_keys=(args or {}).get("asset_keys") or [],
                repository_names=(args or {}).get("repository_names") or [],
                repository_files=(args or {}).get("repository_files") or [],
                link_high_confidence=bool((args or {}).get("link_high_confidence") or False),
                threshold=float((args or {}).get("high_confidence_threshold") or 0.82),
            )
        elif name == "get_provider_capabilities":
            provider = str((args or {}).get("provider") or "").strip().lower()
            result = {"providers": PQC_PROVIDER_CAPABILITY_MATRIX}
            if provider:
                result = {"provider": provider, "capabilities": PQC_PROVIDER_CAPABILITY_MATRIX.get(provider) or PQC_PROVIDER_CAPABILITY_MATRIX.get("unknown")}
        elif name == "get_org_policy":
            result = _load_org_policy(str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID))
        else:
            return {"jsonrpc": "2.0", "id": req.id, "error": {"code": -32602, "message": "unknown tool"}}
        return {
            "jsonrpc": "2.0",
            "id": req.id,
            "result": {
                "content": [{"type": "json", "json": result}],
                "isError": bool(result.get("exit_code")) or str(result.get("decision") or "").lower() == "block",
            },
        }
    return {"jsonrpc": "2.0", "id": req.id, "error": {"code": -32601, "message": "method not found"}}


