@app.get("/audit/logs/export.csv")
def api_export_audit_logs_csv(
    request: Request,
    limit: int = Query(2000, ge=1, le=10000),
    actor_id: str = Query("", max_length=128),
    action: str = Query("", max_length=128),
    decision: str = Query("", max_length=32),
):
    _require_role(
        request,
        allowed_roles=["admin"],
        action="audit.export",
        resource_type="audit_log",
        resource_id="*",
    )
    rows = list_audit_logs(limit=limit, actor_id=actor_id, action=action, decision=decision)
    buf = io.StringIO()
    fields = [
        "id",
        "organization_id",
        "actor_id",
        "actor_role",
        "action",
        "resource_type",
        "resource_id",
        "decision",
        "reason",
        "details",
        "prev_hash",
        "entry_hash",
        "created_at",
    ]
    writer = csv.DictWriter(buf, fieldnames=fields, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        item = dict(row or {})
        if isinstance(item.get("details"), (dict, list)):
            item["details"] = json.dumps(item.get("details"), sort_keys=True)
        writer.writerow(item)
    return Response(
        content=buf.getvalue(),
        media_type="text/csv",
        headers={"Content-Disposition": "attachment; filename=pqc-audit-log.csv"},
    )


def _flight_recorder_summary(events: List[Dict[str, Any]]) -> Dict[str, Any]:
    by_intent: Dict[str, int] = defaultdict(int)
    by_decision: Dict[str, int] = defaultdict(int)
    by_outcome: Dict[str, int] = defaultdict(int)
    for event in events:
        by_intent[str(event.get("intent") or "unknown")] += 1
        by_decision[str(event.get("decision") or "unknown")] += 1
        by_outcome[str(event.get("outcome") or "unknown")] += 1
    return {
        "returned": len(events),
        "counts_by_intent": dict(sorted(by_intent.items())),
        "counts_by_decision": dict(sorted(by_decision.items())),
        "counts_by_outcome": dict(sorted(by_outcome.items())),
    }


@app.post("/flight-recorder/events")
@app.post("/v1/flight-recorder/events")
def api_v1_create_flight_recorder_event(req: FlightRecorderEventRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID).strip() or DEFAULT_ORG_ID
    actor = _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="flight_recorder.create",
        resource_type=str(req.resource_type or "event"),
        resource_id=str(req.resource_id or ""),
    )
    policy = _load_org_policy(org_id)
    event = append_flight_recorder_event(
        actor_type=req.actor_type,
        actor_id=actor["actor_id"],
        actor_role=actor["actor_role"],
        intent=req.intent,
        resource_type=req.resource_type,
        resource_id=req.resource_id,
        policy_version=req.policy_version or str(policy.get("version") or "v1"),
        decision=req.decision,
        outcome=req.outcome,
        reason=req.reason,
        evidence_refs=req.evidence_refs or {},
        details=req.details or {},
    )
    append_audit_log(
        actor_id=actor["actor_id"],
        actor_role=actor["actor_role"],
        action="flight_recorder.event_recorded",
        resource_type=str(req.resource_type or "event"),
        resource_id=str(req.resource_id or ""),
        decision="allow",
        reason=str(req.intent or ""),
        details={"flight_event_id": event.get("id"), "outcome": req.outcome, "decision": req.decision},
    )
    return {"api_version": "v1", "organization_id": org_id, "event": event}


