def _vendor_attestation_portal_payload(token: str) -> Dict[str, Any]:
    invite = get_vendor_attestation_invite_by_token(token)
    if not invite:
        raise HTTPException(status_code=404, detail="attestation invite not found")
    return {
        "api_version": "v1",
        "portal": "vendor_self_attestation",
        "invite": {
            "id": invite.get("id"),
            "vendor_name": invite.get("vendor_name"),
            "status": invite.get("status"),
            "expires_at": invite.get("expires_at"),
        },
        "submit": {
            "method": "POST",
            "path": f"/vendor-attestation/{token}/submit",
            "required_fields": ["submitted_by"],
            "optional_fields": ["signer_title", "domains", "answers", "evidence_refs", "readiness_score"],
        },
    }


# Stylesheet for the public vendor self-attestation portal, kept out of the
# f-string below so its braces need no escaping. This page is filled in by a
# third party the customer invited -- it is the most externally visible surface
# after /launch -- so it uses the same palette, type stack and card geometry.
_VENDOR_ATTESTATION_CSS = """
  :root {
    --bg: #05070d; --bg-raise: #080c15;
    --ink: #f4f8ff; --ink-soft: #c3d0e4; --ink-muted: #8595ad;
    --line: rgba(148,176,220,.14); --line-bright: rgba(148,176,220,.28);
    --q1: #5eead4; --q2: #38bdf8; --q3: #818cf8; --q4: #c084fc;
    --warn: #fbbf24; --danger: #fb7185;
    --sans: "Aptos","Segoe UI Variable Display","Segoe UI",system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;
    --mono: "Cascadia Code","Consolas",ui-monospace,SFMono-Regular,monospace;
    --r-lg: 24px; --r-md: 14px; --r-sm: 10px;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; background: var(--bg); color: var(--ink);
    font-family: var(--sans); font-size: 16px; line-height: 1.6;
    -webkit-font-smoothing: antialiased; overflow-x: hidden;
  }
  body::before {
    content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 0;
    background:
      radial-gradient(880px 580px at 10% -10%, rgba(94,234,212,.14), transparent 60%),
      radial-gradient(720px 520px at 94% 2%, rgba(129,140,248,.13), transparent 58%),
      radial-gradient(1000px 640px at 50% 110%, rgba(56,189,248,.08), transparent 66%);
  }
  .wrap { position: relative; z-index: 1; max-width: 1060px; margin: 0 auto; padding: 44px 24px 72px; }
  h1, h2 { margin: 0; line-height: 1.06; letter-spacing: -.03em; font-weight: 640; }
  p { margin: 0; }

  .hero {
    padding: 42px 40px 36px; border: 1px solid var(--line); border-radius: var(--r-lg);
    background:
      radial-gradient(120% 130% at 0% 0%, rgba(94,234,212,.1), transparent 58%),
      linear-gradient(158deg, rgba(14,20,33,.9), rgba(6,9,16,.94));
    box-shadow: 0 30px 90px rgba(0,0,0,.45);
  }
  .eyebrow {
    display: inline-block; padding: 6px 13px; border-radius: 999px;
    border: 1px solid var(--line-bright); background: rgba(148,176,220,.07);
    font-size: 12px; letter-spacing: .1em; text-transform: uppercase;
    color: var(--ink-soft); font-weight: 600;
  }
  /* The launch page gets its white-into-gradient headline by wrapping the tail in
     a span. Here the heading is a single text node on purpose -- it is asserted
     verbatim by test_vendor_attestation -- so the same effect is produced with one
     gradient that simply stays white through its first half. */
  h1 {
    font-size: clamp(30px, 4.4vw, 48px); margin: 20px 0 16px;
    background: linear-gradient(100deg, #f4f8ff 0%, #f4f8ff 34%, var(--q1) 52%, var(--q2) 72%, var(--q3) 92%);
    -webkit-background-clip: text; background-clip: text; color: transparent;
  }
  .sub { color: var(--ink-soft); max-width: 70ch; font-size: 16px; }
  .meta { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 26px; }
  .pill {
    padding: 7px 13px; border-radius: 999px;
    border: 1px solid var(--line-bright); background: rgba(148,176,220,.06);
    font-family: var(--mono); font-size: 11.5px; letter-spacing: .04em; color: var(--ink-soft);
  }

  .grid { display: grid; grid-template-columns: 1.05fr .95fr; gap: 16px; margin-top: 16px; align-items: start; }
  .card {
    position: relative; overflow: hidden; min-width: 0;
    padding: 28px 28px 26px; border: 1px solid var(--line); border-radius: var(--r-lg);
    background: linear-gradient(158deg, rgba(14,20,33,.86), rgba(6,9,16,.9));
  }
  .card::before {
    content: ""; position: absolute; inset: 0 0 auto 0; height: 1px;
    background: linear-gradient(90deg, transparent, var(--q2), transparent); opacity: .4;
  }
  h2 { font-size: 19px; margin-bottom: 6px; }
  .cardSub { color: var(--ink-muted); font-size: 13.5px; margin-bottom: 22px; }

  /* Field labels only. The checklist rows are <label> too -- so that clicking the
     text toggles the box -- and must not inherit the uppercase mono treatment. */
  label:not(.check) {
    display: block; margin: 18px 0 7px;
    font-family: var(--mono); font-size: 11px; text-transform: uppercase;
    letter-spacing: .14em; color: var(--ink-muted);
  }
  form label:first-of-type { margin-top: 0; }
  input[type=text], input:not([type]), textarea {
    width: 100%; padding: 12px 14px; font: inherit; font-size: 15px;
    border: 1px solid var(--line-bright); border-radius: var(--r-sm);
    background: rgba(5,7,13,.55); color: var(--ink); outline: none;
    transition: border-color .18s ease, box-shadow .18s ease;
  }
  textarea { min-height: 96px; resize: vertical; font-family: var(--mono); font-size: 13px; }
  ::placeholder { color: rgba(133,149,173,.7); }
  input:focus, textarea:focus { border-color: rgba(94,234,212,.6); box-shadow: 0 0 0 4px rgba(94,234,212,.1); }

  button {
    margin-top: 24px; width: 100%; padding: 13px 22px; border-radius: 12px; cursor: pointer;
    font: inherit; font-size: 15px; font-weight: 620; border: 1px solid transparent; color: #04120f;
    background: linear-gradient(135deg, var(--q1), var(--q2));
    box-shadow: 0 12px 30px rgba(56,189,248,.26);
    transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
  }
  button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 16px 38px rgba(56,189,248,.38); }
  button:disabled { cursor: progress; filter: saturate(.35) brightness(.8); box-shadow: none; }

  .msg { margin-top: 14px; min-height: 20px; font-family: var(--mono); font-size: 12.5px; color: var(--ink-muted); white-space: pre-wrap; line-height: 1.5; }
  .msg.ok { color: #b8f5e8; }
  .msg.bad { color: #ffcdd6; }

  /* Checklist rows light up as they are ticked, so progress is legible without
     reading the number. Driven purely by :checked -- the scoring script is
     untouched. */
  .check {
    display: flex; align-items: flex-start; gap: 12px; padding: 13px 15px;
    margin-bottom: 9px; border: 1px solid var(--line); border-left: 2px solid var(--line-bright);
    border-radius: var(--r-sm); background: rgba(148,176,220,.045);
    font-size: 14px; color: var(--ink-soft); cursor: pointer;
    transition: border-left-color .2s ease, background .2s ease, color .2s ease;
  }
  .check:hover { background: rgba(148,176,220,.075); }
  .check input { accent-color: var(--q1); width: 16px; height: 16px; margin: 3px 0 0; flex: none; cursor: pointer; }
  .check:has(input:checked) { border-left-color: var(--q1); background: rgba(94,234,212,.07); color: var(--ink); }

  .score {
    margin-top: 4px; font-size: 52px; font-weight: 660; letter-spacing: -.04em; line-height: 1;
    font-variant-numeric: tabular-nums;
    background: linear-gradient(104deg, var(--q1), var(--q2) 45%, var(--q3));
    -webkit-background-clip: text; background-clip: text; color: transparent;
  }
  .card .sub { margin-top: 14px; font-size: 13.5px; color: var(--ink-muted); }

  .foot { margin-top: 34px; padding-top: 22px; border-top: 1px solid var(--line); color: var(--ink-muted); font-size: 13px; }

  @media (max-width: 860px) {
    .grid { grid-template-columns: 1fr; }
    .hero { padding: 28px 22px; }
    .card { padding: 22px; }
  }
  @media (prefers-reduced-motion: reduce) {
    * { transition: none !important; }
  }
"""


def _vendor_attestation_portal_html(token: str) -> str:
    payload = _vendor_attestation_portal_payload(token)
    invite = payload.get("invite") or {}
    vendor = _html_escape(invite.get("vendor_name") or "Vendor")
    status = _html_escape(invite.get("status") or "open")
    expires = _html_escape(invite.get("expires_at") or "")
    token_js = json.dumps(str(token or ""))
    return f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>PQC Vendor Attestation - {vendor}</title>
  <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
  <style>{_VENDOR_ATTESTATION_CSS}</style>
</head>
<body>
  <main class="wrap">
    <section class="hero">
      <div class="eyebrow">Vendor self-attestation portal</div>
      <h1>{vendor} PQC readiness attestation</h1>
      <p class="sub">Submit the cryptographic readiness evidence requested by your customer. This portal is isolated to this invite and does not expose the customer's internal dashboard.</p>
      <div class="meta"><span class="pill">Status: {status}</span><span class="pill">Expires: {expires}</span><span class="pill">Scope: public systems and governance evidence</span></div>
    </section>
    <section class="grid">
      <form id="attestForm" class="card">
        <h2>Signed submission</h2>
        <p class="cardSub">The signer is recorded with the attestation and shared with the requesting customer.</p>
        <label for="submitted_by">Signer name / email</label>
        <input id="submitted_by" required placeholder="security.owner@vendor.com" />
        <label for="signer_title">Signer title</label>
        <input id="signer_title" placeholder="CISO / Head of Security" />
        <label for="domains">Domains or systems in scope</label>
        <textarea id="domains" placeholder="api.vendor.com:443&#10;login.vendor.com:443"></textarea>
        <label for="evidence">Evidence references</label>
        <textarea id="evidence" placeholder="SOC2 report available under NDA&#10;PQC migration roadmap Q3&#10;TLS inventory export link"></textarea>
        <button id="submitBtn" type="submit">Sign and submit attestation</button>
        <div id="msg" class="msg"></div>
      </form>
      <aside class="card">
        <h2>Readiness checklist</h2>
        <p class="cardSub">Tick what is true today. Each item carries equal weight in the score below.</p>
        <label class="check"><input type="checkbox" class="q" id="q_tls13" /><span>TLS 1.2+ enforced; TLS 1.0/1.1 disabled for public systems.</span></label>
        <label class="check"><input type="checkbox" class="q" id="q_inventory" /><span>Cryptographic asset inventory exists for public and critical internal services.</span></label>
        <label class="check"><input type="checkbox" class="q" id="q_pqc" /><span>PQC migration owner and roadmap are defined.</span></label>
        <label class="check"><input type="checkbox" class="q" id="q_vendor" /><span>Third-party cryptographic dependencies are reviewed.</span></label>
        <label class="check"><input type="checkbox" class="q" id="q_hndl" /><span>Harvest-now/decrypt-later exposure has been assessed.</span></label>
        <label>Readiness score</label>
        <div class="score"><span id="score">0</span>%</div>
        <p class="sub">The score is an attested vendor signal, not a replacement for independent scanning. Your customer can combine this with technical evidence.</p>
      </aside>
    </section>
    <footer class="foot">PQC Scanner &middot; this invite-scoped portal collects only what is shown above. No credentials, source code, or private keys are requested.</footer>
  </main>
  <script>
    const token = {token_js};
    const checks = [...document.querySelectorAll('.q')];
    const scoreEl = document.getElementById('score');
    function score() {{
      const checked = checks.filter(x => x.checked).length;
      const value = Math.round((checked / Math.max(1, checks.length)) * 100);
      scoreEl.textContent = String(value);
      return value;
    }}
    checks.forEach(x => x.addEventListener('change', score));
    document.getElementById('attestForm').addEventListener('submit', async (ev) => {{
      ev.preventDefault();
      const btn = document.getElementById('submitBtn');
      const msg = document.getElementById('msg');
      btn.disabled = true;
      msg.className = 'msg';
      msg.textContent = 'Submitting attestation...';
      const domains = document.getElementById('domains').value.split(/\\r?\\n|,/).map(x => x.trim()).filter(Boolean);
      const evidenceLines = document.getElementById('evidence').value.split(/\\r?\\n/).map(x => x.trim()).filter(Boolean);
      const payload = {{
        submitted_by: document.getElementById('submitted_by').value.trim(),
        signer_title: document.getElementById('signer_title').value.trim(),
        domains,
        readiness_score: score(),
        answers: Object.fromEntries(checks.map(x => [x.id.replace(/^q_/, ''), x.checked])),
        evidence_refs: {{ notes: evidenceLines }}
      }};
      try {{
        const res = await fetch(`/vendor-attestation/${{encodeURIComponent(token)}}/submit`, {{
          method:'POST',
          headers: {{'Content-Type':'application/json'}},
          body: JSON.stringify(payload)
        }});
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || 'submission failed');
        msg.className = 'msg ok';
        msg.textContent = `Submitted. Attestation id: ${{data.submission && data.submission.id ? data.submission.id : 'recorded'}}`;
      }} catch (e) {{
        msg.className = 'msg bad';
        msg.textContent = e.message || String(e);
      }} finally {{
        btn.disabled = false;
      }}
    }});
    score();
  </script>
</body>
</html>"""


