@app.post("/integrations/github/webhook")
async def api_github_webhook(request: Request):
    """
    Inbound GitHub webhook receiver for PR lifecycle events.
    When a PR is merged, remediations with matching pr_url are marked as merged.
    """
    body = await request.body()
    event = str(request.headers.get("X-GitHub-Event") or "").strip().lower()
    delivery = str(request.headers.get("X-GitHub-Delivery") or "").strip()

    # Optional signature verification for production hardening
    secret = str(os.getenv("GITHUB_WEBHOOK_SECRET", "") or "").strip()
    if secret:
        got = str(request.headers.get("X-Hub-Signature-256") or "").strip()
        expected = "sha256=" + hmac.new(secret.encode("utf-8"), body, hashlib.sha256).hexdigest()
        if not got or not hmac.compare_digest(got, expected):
            raise HTTPException(status_code=401, detail="invalid GitHub webhook signature")

    try:
        payload = json.loads(body.decode("utf-8")) if body else {}
    except Exception:
        raise HTTPException(status_code=400, detail="invalid JSON payload")

    if event == "ping":
        return {"ok": True, "event": "ping", "delivery": delivery}

    if event != "pull_request":
        return {"ok": True, "ignored": True, "reason": "unsupported_event", "event": event, "delivery": delivery}

    action = str(payload.get("action") or "").strip().lower()
    pr = payload.get("pull_request") or {}
    merged = bool(pr.get("merged"))
    pr_url = str(pr.get("html_url") or "").strip()
    if not pr_url:
        return {"ok": True, "ignored": True, "reason": "missing_pr_url", "delivery": delivery}

    if action == "closed" and not merged:
        stats = update_remediation_status_by_pr_url(
            pr_url=pr_url,
            status="pr_closed",
            review_note="GitHub PR closed without merge",
        )
        record_github_pr_event(
            pr_url=pr_url,
            event=event,
            action=action,
            delivery=delivery,
            status="pr_closed",
            remediation_ids=list(stats.get("remediation_ids") or []),
            payload={"merged": merged, "number": pr.get("number") or 0},
        )
        try:
            append_audit_log(
                actor_id="github-webhook",
                actor_role="system",
                action="remediation.webhook_pr_closed",
                resource_type="remediation",
                resource_id=pr_url,
                decision="allow",
                reason="github pull_request closed without merge",
                details={"delivery": delivery, **stats},
            )
            emit_platform_event(
                "remediation.pr_closed",
                {"pr_url": pr_url, "status": "pr_closed", "delivery": delivery, **stats},
                dedupe_key=hashlib.sha256(f"remediation.pr_closed:{pr_url}:{delivery}".encode("utf-8")).hexdigest(),
            )
        except Exception:
            pass
        return {"ok": True, "event": event, "action": action, "delivery": delivery, "pr_url": pr_url, **stats}

    if action in {"reopened", "synchronize"}:
        next_status = "pr_created" if action == "reopened" else "pr_updated"
        stats = update_remediation_status_by_pr_url(
            pr_url=pr_url,
            status=next_status,
            review_note=f"GitHub PR {action}",
        )
        record_github_pr_event(
            pr_url=pr_url,
            event=event,
            action=action,
            delivery=delivery,
            status=next_status,
            remediation_ids=list(stats.get("remediation_ids") or []),
            payload={"merged": merged, "number": pr.get("number") or 0},
        )
        try:
            append_audit_log(
                actor_id="github-webhook",
                actor_role="system",
                action=f"remediation.webhook_pr_{action}",
                resource_type="remediation",
                resource_id=pr_url,
                decision="allow",
                reason=f"github pull_request {action}",
                details={"delivery": delivery, **stats},
            )
            emit_platform_event(
                f"remediation.pr_{action}",
                {"pr_url": pr_url, "status": next_status, "delivery": delivery, **stats},
                dedupe_key=hashlib.sha256(f"remediation.pr_{action}:{pr_url}:{delivery}".encode("utf-8")).hexdigest(),
            )
        except Exception:
            pass
        return {"ok": True, "event": event, "action": action, "delivery": delivery, "pr_url": pr_url, **stats}

    if action != "closed" or not merged:
        return {
            "ok": True,
            "ignored": True,
            "reason": "unsupported_pull_request_action",
            "event": event,
            "action": action,
            "delivery": delivery,
            "pr_url": pr_url,
        }

    merged_at = str(pr.get("merged_at") or "").strip()
    stats = mark_remediation_merged_by_pr_url(pr_url=pr_url, merged_at_iso=merged_at)
    record_github_pr_event(
        pr_url=pr_url,
        event=event,
        action=action,
        delivery=delivery,
        status="merged",
        remediation_ids=list(stats.get("remediation_ids") or []),
        payload={"merged": merged, "merged_at": merged_at, "number": pr.get("number") or 0},
    )
    try:
        append_audit_log(
            actor_id="github-webhook",
            actor_role="system",
            action="remediation.webhook_merged",
            resource_type="remediation",
            resource_id=pr_url,
            decision="allow",
            reason="github pull_request merged",
            details={"delivery": delivery, **stats},
        )
    except Exception:
        pass
    if int(stats.get("updated") or 0) > 0 or int(stats.get("already_merged") or 0) > 0:
        try:
            emit_platform_event(
                "remediation.merged",
                {
                    "remediation_id": int(((stats.get("remediation_ids") or [0]) or [0])[0] or 0),
                    "remediation_ids": list(stats.get("remediation_ids") or []),
                    "asset_key": "",
                    "repository": "",
                    "file_path": "",
                    "pr_url": pr_url,
                    "merged_at": merged_at,
                    "status": "merged",
                    "delivery": delivery,
                },
                dedupe_key=hashlib.sha256(f"remediation.merged:{pr_url}:{merged_at}".encode("utf-8")).hexdigest(),
            )
        except Exception:
            pass
    return {
        "ok": True,
        "event": event,
        "action": action,
        "delivery": delivery,
        "pr_url": pr_url,
        **stats,
    }


