@app.post("/v1/runtime/traffic/import")
def api_import_runtime_traffic(req: RuntimeTrafficImportRequest, request: Request):
    _require_role(
        request,
        allowed_roles=["operator", "admin"],
        action="runtime_traffic.import",
        resource_type="runtime_traffic",
        resource_id=str(req.source or "manual"),
    )
    raw_records = []
    parsed_log_records, parsed_log_invalid = parse_runtime_log_lines(
        list(req.raw_logs or []),
        source=str(req.source or "runtime-log").strip().lower(),
        provider=str(req.provider or "unknown").strip().lower(),
        log_format=str(req.log_format or "auto").strip().lower(),
    )
    for parsed in parsed_log_records:
        raw_records.append(parsed.get("raw") if isinstance(parsed.get("raw"), dict) else parsed)
    for item in req.records or []:
        try:
            raw = item.model_dump()
        except AttributeError:
            raw = _model_payload(item)
        if not raw.get("source"):
            raw["source"] = str(req.source or "manual").strip().lower()
        if not raw.get("provider"):
            raw["provider"] = str(req.provider or "unknown").strip().lower()
        raw_records.append(raw)
    idem = _reserve_idempotency_or_raise(
        request,
        action="runtime_traffic.import",
        payload={
            "source": req.source,
            "provider": req.provider,
            "log_format": req.log_format,
            "raw_logs": req.raw_logs,
            "records": raw_records,
            "create_assets": req.create_assets,
            "defaults": {
                "owner": req.default_owner,
                "team": req.default_team,
                "environment": req.default_environment,
                "criticality": req.default_criticality,
                "confidentiality_lifetime": req.default_confidentiality_lifetime,
                "tags": req.tags,
            },
        },
    )
    if idem.get("replay"):
        return idem.get("response") or {}

    normalized = [normalize_runtime_record(r) for r in raw_records]
    valid = [r for r in normalized if r.get("ok")]
    invalid = [*parsed_log_invalid, *[r for r in normalized if not r.get("ok")]]
    stored = record_runtime_traffic_observations(valid)
    summary = summarize_runtime_records(valid)
    asset_updates = []
    if bool(req.create_assets):
        for item in summary.get("assets") or []:
            asset_key_str = str(item.get("asset_key") or "").strip()
            if not asset_key_str:
                continue
            existing = get_asset(asset_key_str) or {}
            existing_meta = existing.get("metadata") if isinstance(existing.get("metadata"), dict) else {}
            runtime_meta = {
                "observed_from_runtime": True,
                "runtime_sources": item.get("sources") or [],
                "runtime_providers": item.get("providers") or [],
                "runtime_protocols": item.get("protocols") or [],
                "runtime_tls_versions": item.get("tls_versions") or [],
                "runtime_observed_count": int(item.get("observed_count") or 0),
                "runtime_first_seen": item.get("first_seen") or "",
                "runtime_last_seen": item.get("last_seen") or "",
                "runtime_paths_sample": item.get("paths_sample") or [],
            }
            tags = sorted(
                {
                    *[str(t or "").strip() for t in (existing.get("tags") or [])],
                    *[str(t or "").strip() for t in (req.tags or [])],
                    "runtime-observed",
                }
                - {""}
            )
            updated = upsert_asset(
                asset_key_str,
                owner=str(existing.get("owner") or req.default_owner or ""),
                team=str(existing.get("team") or req.default_team or ""),
                environment=str(existing.get("environment") or req.default_environment or ""),
                criticality=str(existing.get("criticality") or req.default_criticality or ""),
                confidentiality_lifetime=str(existing.get("confidentiality_lifetime") or req.default_confidentiality_lifetime or ""),
                notes=str(existing.get("notes") or ""),
                tags=tags,
                metadata={**existing_meta, **runtime_meta},
                repository_id=int(existing.get("repository_id") or 0),
            )
            asset_updates.append(updated)

    response = {
        "ok": True,
        "source": str(req.source or "").strip().lower(),
        "provider": str(req.provider or "").strip().lower(),
        "received": len(raw_records),
        "raw_logs_received": len(req.raw_logs or []),
        "raw_logs_parsed": len(parsed_log_records),
        "valid": len(valid),
        "invalid": len(invalid),
        "stored": int(stored.get("inserted") or 0),
        "assets_upserted": len(asset_updates),
        "summary": summary,
        "invalid_records": invalid[:25],
    }
    if idem.get("enabled"):
        complete_idempotency_key(key=str(idem.get("key") or ""), action="runtime_traffic.import", response=response)
    return response


