_LEGACY_TLS_VALUES = {"ssl", "sslv2", "sslv3", "tlsv1", "tlsv1.0", "tls1.0", "tlsv1.1", "tls1.1"}
_WEAK_CIPHER_MARKERS = ("RC4", "3DES", "DES-CBC", "_DES_", "NULL", "EXPORT", "MD5")


def _runtime_crypto_risk(tls_version: str = "", cipher: str = "") -> Dict[str, Any]:
    tls = str(tls_version or "").strip()
    cipher_text = str(cipher or "").strip()
    tls_key = tls.lower().replace(" ", "")
    cipher_upper = cipher_text.upper()
    reasons: List[str] = []
    risk = "low"
    if not tls:
        risk = "medium"
        reasons.append("tls_version_unknown")
    elif tls_key in _LEGACY_TLS_VALUES:
        risk = "critical"
        reasons.append("legacy_tls")
    elif tls_key in {"tlsv1.2", "tls1.2"}:
        risk = "medium"
        reasons.append("pre_pqc_tls")
    if cipher_upper and any(marker in cipher_upper for marker in _WEAK_CIPHER_MARKERS):
        risk = "critical"
        reasons.append("weak_cipher")
    elif not cipher_text:
        if risk == "low":
            risk = "medium"
        reasons.append("cipher_unknown")
    return {"risk": risk, "reasons": sorted(set(reasons))}


def _build_runtime_traffic_topology(limit: int = 1000) -> Dict[str, Any]:
    observations = list_runtime_traffic_observations(limit=int(limit))
    nodes: Dict[str, Dict[str, Any]] = {}
    edges: Dict[str, Dict[str, Any]] = {}
    risky_edges = 0
    legacy_tls_edges = 0
    unknown_tls_edges = 0
    total_observed = 0

    for obs in observations:
        source_label = str(obs.get("source") or obs.get("provider") or "runtime").strip().lower()
        provider = str(obs.get("provider") or "unknown").strip().lower()
        asset = str(obs.get("asset_key") or "").strip()
        host = str(obs.get("host") or "").strip()
        if not asset:
            continue
        source_id = f"source:{source_label}"
        service_id = f"service:{asset}"
        nodes.setdefault(
            source_id,
            {"id": source_id, "type": "source", "label": source_label, "provider": provider, "observed_count": 0},
        )
        nodes.setdefault(
            service_id,
            {
                "id": service_id,
                "type": "service",
                "label": host or asset,
                "asset_key": asset,
                "host": host,
                "port": int(obs.get("port") or 0),
                "observed_count": 0,
                "tls_versions": [],
                "ciphers": [],
            },
        )
        tls_version = str(obs.get("tls_version") or "").strip()
        cipher = str(obs.get("cipher") or "").strip()
        risk = _runtime_crypto_risk(tls_version, cipher)
        count = int(obs.get("observed_count") or 0)
        total_observed += count
        nodes[source_id]["observed_count"] += count
        nodes[service_id]["observed_count"] += count
        if tls_version and tls_version not in nodes[service_id]["tls_versions"]:
            nodes[service_id]["tls_versions"].append(tls_version)
        if cipher and cipher not in nodes[service_id]["ciphers"]:
            nodes[service_id]["ciphers"].append(cipher)

        edge_key = "|".join([source_id, service_id, str(obs.get("protocol") or ""), tls_version, cipher])
        edge_id = hashlib.sha256(edge_key.encode("utf-8")).hexdigest()[:16]
        edge = edges.setdefault(
            edge_id,
            {
                "id": edge_id,
                "source": source_id,
                "target": service_id,
                "source_label": source_label,
                "asset_key": asset,
                "host": host,
                "port": int(obs.get("port") or 0),
                "protocol": str(obs.get("protocol") or ""),
                "tls_version": tls_version,
                "cipher": cipher,
                "observed_count": 0,
                "risk": risk["risk"],
                "reasons": risk["reasons"],
                "first_seen": str(obs.get("first_seen") or ""),
                "last_seen": str(obs.get("last_seen") or ""),
                "paths_sample": [],
            },
        )
        edge["observed_count"] += count
        if str(obs.get("first_seen") or "") and (not edge["first_seen"] or str(obs.get("first_seen")) < edge["first_seen"]):
            edge["first_seen"] = str(obs.get("first_seen"))
        if str(obs.get("last_seen") or "") and str(obs.get("last_seen")) > edge["last_seen"]:
            edge["last_seen"] = str(obs.get("last_seen"))
        path = str(obs.get("path") or "").strip()
        if path and path not in edge["paths_sample"] and len(edge["paths_sample"]) < 5:
            edge["paths_sample"].append(path)

    edge_items = sorted(edges.values(), key=lambda item: (item["risk"] != "critical", item["risk"] != "medium", -int(item["observed_count"] or 0)))
    for edge in edge_items:
        if edge["risk"] in {"critical", "medium"}:
            risky_edges += 1
        if "legacy_tls" in edge.get("reasons", []):
            legacy_tls_edges += 1
        if "tls_version_unknown" in edge.get("reasons", []):
            unknown_tls_edges += 1

    node_items = sorted(nodes.values(), key=lambda item: (item.get("type") != "source", str(item.get("label") or "")))
    return {
        "api_version": "v1",
        "organization_id": current_organization_id(),
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "nodes": len(node_items),
            "edges": len(edge_items),
            "risky_edges": risky_edges,
            "legacy_tls_edges": legacy_tls_edges,
            "unknown_tls_edges": unknown_tls_edges,
            "observed_count": total_observed,
        },
        "nodes": node_items,
        "edges": edge_items,
        "hotspots": edge_items[:10],
    }


