# =============================================================================
# Wave 5 — Unified Executive Dashboard + Multi-Channel Alerting + Timeline
# =============================================================================

# ─────────────────────────────────────────────────────────────────────────────
# Pydantic models
# ─────────────────────────────────────────────────────────────────────────────

class TeamsAlertRequest(BaseModel):
    webhook_url: str
    title: str
    summary: str
    severity: str = "warning"
    facts: Optional[List[Dict[str, str]]] = None
    action_url: str = ""


class PagerDutyAlertRequest(BaseModel):
    routing_key: str
    summary: str
    severity: str = "warning"
    dedup_key: str = ""
    details: Optional[Dict[str, Any]] = None


class PagerDutyResolveRequest(BaseModel):
    routing_key: str
    dedup_key: str


class MultiChannelAlertRequest(BaseModel):
    event_type: str
    title: str
    summary: str
    severity: str = "warning"
    facts: Optional[List[Dict[str, str]]] = None
    details: Optional[Dict[str, Any]] = None
    dedup_key: str = ""
    slack_webhook: str = ""
    teams_webhook: str = ""
    pagerduty_routing_key: str = ""
    action_url: str = ""


# ─────────────────────────────────────────────────────────────────────────────
# Unified Executive Dashboard
# ─────────────────────────────────────────────────────────────────────────────

def _exec_dashboard_aggregate(org_id: str) -> Dict[str, Any]:
    """Assemble the single-pane-of-glass executive view from all sub-services."""
    now = datetime.now(timezone.utc)
    current_year = now.year
    out: Dict[str, Any] = {"generated_at": now.isoformat(), "organization_id": org_id}

    # ── Q-Day probability ──────────────────────────────────────────────────
    try:
        q_model = _compute_q_day_model(years=[current_year, current_year + 1, current_year + 2,
                                               current_year + 3, current_year + 5])
        rsa2048_series = q_model.get("algorithms", {}).get("RSA-2048", [])
        q_prob_now = next((p["probability"] for p in rsa2048_series if p["year"] == current_year), 0.0)
        q_prob_3y  = next((p["probability"] for p in rsa2048_series if p["year"] == current_year + 3), 0.0)
        q_prob_5y  = next((p["probability"] for p in rsa2048_series if p["year"] == current_year + 5), 0.0)
        out["q_day"] = {
            "rsa2048_prob_now": round(q_prob_now * 100, 2),
            "rsa2048_prob_3y":  round(q_prob_3y  * 100, 2),
            "rsa2048_prob_5y":  round(q_prob_5y  * 100, 2),
            "threat_label": ("CRITICAL" if q_prob_now > 0.30 else
                             "HIGH"     if q_prob_now > 0.10 else
                             "ELEVATED" if q_prob_now > 0.03 else "MONITORING"),
        }
    except Exception as ex:
        out["q_day"] = {"error": str(ex)[:100]}

    # ── Maturity score ─────────────────────────────────────────────────────
    try:
        assessments = _maturity_list(org_id, limit=1)
        if assessments:
            a = assessments[0]
            out["maturity"] = {
                "level": a.get("maturity_level"),
                "label": a.get("maturity_label"),
                "composite_score": a.get("composite_score"),
                "certificate_id": a.get("certificate_id"),
                "assessed_at": a.get("assessed_at"),
            }
        else:
            out["maturity"] = {"level": None, "label": "Not assessed yet"}
    except Exception as ex:
        out["maturity"] = {"error": str(ex)[:100]}

    # ── Observatory health ─────────────────────────────────────────────────
    try:
        obs = _obs_dashboard(org_id)
        out["observatory"] = {
            "health": obs.get("health"),
            "total_assets": obs.get("total_assets", 0),
            "active_alerts": obs.get("active_alerts", 0),
            "drift_last_7d": obs.get("drift_last_7d", 0),
            "last_scan_at": obs.get("last_scan_at"),
        }
    except Exception as ex:
        out["observatory"] = {"error": str(ex)[:100]}

    # ── Regulatory countdown ───────────────────────────────────────────────
    try:
        frameworks = _reg_list_frameworks()
        # Pick the nearest deadline that's in the future and NOT compliant (score < 100)
        nearest = None
        for fw in frameworks:
            days = fw.get("days_until_deadline")
            if days is not None and days > 0:
                if nearest is None or days < nearest.get("days_until_deadline", 999999):
                    nearest = fw
        out["regulatory"] = {
            "nearest_deadline": nearest.get("id") if nearest else None,
            "nearest_deadline_name": nearest.get("name") if nearest else None,
            "days_remaining": nearest.get("days_until_deadline") if nearest else None,
            "deadline_date": nearest.get("deadline_date") if nearest else None,
            "total_frameworks": len(frameworks),
        }
    except Exception as ex:
        out["regulatory"] = {"error": str(ex)[:100]}

    # ── Canary network status ──────────────────────────────────────────────
    try:
        canary_dash = _canary_dashboard(org_id)
        out["canary"] = {
            "total": canary_dash.get("total", 0),
            "active": canary_dash.get("active", 0),
            "triggered_30d": canary_dash.get("triggered_30d", 0),
            "highest_tier_triggered": canary_dash.get("highest_tier_triggered"),
        }
    except Exception as ex:
        out["canary"] = {"error": str(ex)[:100]}

    # ── Q-TISN threat level ────────────────────────────────────────────────
    try:
        qtisn_dash = _qtisn_dashboard(org_id)
        out["qtisn"] = {
            "threat_level": qtisn_dash.get("threat_level"),
            "network_signals_24h": qtisn_dash.get("signals_24h", 0),
            "member_count": qtisn_dash.get("network_size", 0),
        }
    except Exception as ex:
        out["qtisn"] = {"error": str(ex)[:100]}

    # ── Scan inventory summary ─────────────────────────────────────────────
    try:
        # count_scans dispatches to Postgres or SQLite; a direct get_db() query would always
        # read the local SQLite file and report zero scans on a Postgres deployment. It is a
        # COUNT(*): this used to be len(list_scan_rows(limit=10000)), which fetched and parsed
        # up to a thousand scan rows to produce one integer.
        total_scans = count_scans()
        # Per-asset risk comes from scan_results. `scans` has one row per scan and no
        # quantum_risk_level column, so the previous counts raised "no such column" and — being
        # inside this try/except — silently reported zero assets at every risk level.
        _rc = _asset_risk_counts(org_id)
        total_assets = _rc["total"]
        high_risk_assets = _rc["at_risk"]
        safe_assets = _rc.get("safe", 0) + _rc.get("low", 0)
        # Migration progress is a proportion of assets, not of scans.
        pqc_pct = round(safe_assets / total_assets * 100, 1) if total_assets else 0
        out["inventory"] = {
            # total_assets must be the asset count, not the scan count: one scan covers many
            # assets, so reporting scans here produced impossible dashboards such as
            # "1 total asset, 2 high risk".
            "total_assets": total_assets,
            "high_risk_assets": high_risk_assets,
            "pqc_ready_assets": safe_assets,
            "pqc_migration_pct": pqc_pct,
            "total_scans": total_scans,
        }
    except Exception as ex:
        out["inventory"] = {"error": str(ex)[:100]}

    # ── Overall executive risk signal ──────────────────────────────────────
    signals = []
    q_prob = out.get("q_day", {}).get("rsa2048_prob_now", 0)
    maturity_lvl = out.get("maturity", {}).get("level") or 0
    active_alerts = out.get("observatory", {}).get("active_alerts", 0)
    canary_triggered = out.get("canary", {}).get("triggered_30d", 0)
    pqc_pct_val = out.get("inventory", {}).get("pqc_migration_pct", 0)

    total_assets_known = int(out.get("inventory", {}).get("total_assets") or 0)

    if q_prob > 20: signals.append("Q-Day risk elevated")
    if maturity_lvl and maturity_lvl < 2: signals.append("Maturity below baseline")
    if active_alerts > 0: signals.append(f"{active_alerts} observatory alert(s)")
    if canary_triggered > 0: signals.append("Canary triggered in last 30 days")
    # "Only 0% of assets are PQC-ready" is a statement about an estate that does
    # not exist yet. The flag needs at least one asset on record to mean anything.
    if total_assets_known > 0 and pqc_pct_val < 25:
        signals.append(f"Only {pqc_pct_val}% assets PQC-ready")

    if total_assets_known < 1:
        out["executive_signal"] = {
            "available": False,
            "reason": (
                "No assets are on record for this organization, so no executive risk signal can be "
                "raised. Run a TLS scan (or import a CBOM/SBOM) to build the inventory."
            ),
            "minimum_data": {
                "assets": 1,
                "how_to_get_it": "Run a TLS scan from the Scans view, or import a CBOM/SBOM.",
            },
            "risk_flags": signals,
            "flag_count": len(signals),
            "status": None,
        }
    else:
        out["executive_signal"] = {
            "available": True,
            "reason": "",
            "minimum_data": {
                "assets": 1,
                "how_to_get_it": "Run a TLS scan from the Scans view, or import a CBOM/SBOM.",
            },
            "risk_flags": signals,
            "flag_count": len(signals),
            "status": ("RED" if len(signals) >= 3 else "AMBER" if signals else "GREEN"),
        }

    return out


