# Wave 5 — PQC Timeline data (serves the SVG visualizer)
# ─────────────────────────────────────────────────────────────────────────────

@app.get("/timeline/data")
@app.get("/v1/timeline/data")
def api_timeline_data(request: Request):
    """
    Return structured data for the PQC Timeline Visualizer.

    Includes:
    - Q-Day probability series (RSA-2048, ECC-256) from 2024 to 2040
    - Regulatory deadline markers
    - Org migration progress snapshot (current % safe)
    """
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="timeline.view", resource_type="organization", resource_id=org_id)

    years = list(range(2024, 2041))

    # Q-Day model series
    q_model = _compute_q_day_model(years=years)
    rsa_series = q_model.get("algorithms", {}).get("RSA-2048", [])
    ecc_series = q_model.get("algorithms", {}).get("ECC-256", [])

    # Regulatory deadlines
    try:
        frameworks = _reg_list_frameworks()
        deadlines = [
            {
                "id": f["id"],
                "name": f["name"],
                "deadline_date": f.get("deadline_date"),
                "days_until": f.get("days_until_deadline"),
                "penalty_risk": f.get("penalty_risk"),
            }
            for f in frameworks
            if f.get("deadline_date")
        ]
    except Exception:
        deadlines = []

    # Org migration progress, measured over assets (scan_results) rather than scan rows.
    try:
        _rc = _asset_risk_counts(org_id)
        total = _rc["total"]
        safe = _rc.get("safe", 0) + _rc.get("low", 0)
        migration_pct = round(safe / total * 100, 1) if total else 0
    except Exception:
        migration_pct = 0
        total = 0

    return {
        "api_version": "v1",
        "years": years,
        "q_day_series": {
            "RSA-2048": rsa_series,
            "ECC-256":  ecc_series,
        },
        "regulatory_deadlines": deadlines,
        "org_migration": {
            "current_pct": migration_pct,
            "total_assets": total,
            "as_of": datetime.now(timezone.utc).isoformat(),
        },
    }


