@app.post("/digest/send")
@app.post("/v1/digest/send")
def api_digest_send(req: DigestSendRequest, request: Request):
    """Generate and immediately send a digest to configured channels."""
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, allowed_roles=["operator", "admin"],
                  action="digest.send", resource_type="organization", resource_id=org_id)

    current_year = datetime.now(timezone.utc).year
    q_prob = 0.0
    try:
        q_model = _compute_q_day_model(years=[current_year])
        rsa = q_model.get("algorithms", {}).get("RSA-2048", [])
        q_prob = next((p["probability"] * 100 for p in rsa if p["year"] == current_year), 0.0)
    except Exception:
        pass

    migration_pct, total_assets, high_risk = 0.0, 0, 0
    try:
        _rc = _asset_risk_counts(org_id)
        total_assets = _rc["total"]
        safe = _rc.get("safe", 0) + _rc.get("low", 0)
        high_risk = _rc["at_risk"]
        migration_pct = round(safe / total_assets * 100, 1) if total_assets else 0
    except Exception:
        pass

    maturity_level, maturity_label = None, ""
    try:
        assessments = _maturity_list(org_id, limit=1)
        if assessments:
            maturity_level = assessments[0].get("maturity_level")
            maturity_label = assessments[0].get("maturity_label", "")
    except Exception:
        pass

    nearest_deadline_name, days_until_deadline = "", None
    try:
        frameworks = _reg_list_frameworks()
        nearest = min((f for f in frameworks if f.get("days_until_deadline") and f["days_until_deadline"] > 0),
                      key=lambda f: f["days_until_deadline"], default=None)
        if nearest:
            nearest_deadline_name = nearest.get("name", "")
            days_until_deadline   = nearest.get("days_until_deadline")
    except Exception:
        pass

    canary_triggered_30d = 0
    try:
        cd = _canary_dashboard(org_id)
        canary_triggered_30d = cd.get("triggered_30d", 0)
    except Exception:
        pass

    active_alerts = 0
    try:
        obs = _obs_dashboard(org_id)
        active_alerts = obs.get("active_alerts", 0)
    except Exception:
        pass

    digest = _build_digest(
        org_id=org_id,
        org_name=req.org_name or org_id,
        migration_pct=migration_pct,
        total_assets=total_assets,
        high_risk=high_risk,
        maturity_level=maturity_level,
        maturity_label=maturity_label,
        nearest_deadline_name=nearest_deadline_name,
        days_until_deadline=days_until_deadline,
        q_day_prob=q_prob,
        canary_triggered_30d=canary_triggered_30d,
        active_alerts=active_alerts,
    )

    # Determine channels — prefer request params, fall back to stored config
    cfg = _digest_get_config(org_id)
    slack  = req.slack_webhook  or cfg.get("slack_webhook","")
    teams  = req.teams_webhook  or cfg.get("teams_webhook","")
    pd_key = req.pd_routing_key or cfg.get("pd_routing_key","")

    send_result = _send_digest(digest, slack_webhook=slack, teams_webhook=teams, pd_routing_key=pd_key)

    return {"api_version": "v1", "digest": digest, "send_result": send_result}


