@app.get("/badge/{token}")
def api_badge_svg(token: str):
    """
    Public SVG badge endpoint — no auth required.

    Returns an SVG badge showing the org's PQC maturity level.
    Embed in README: ![PQC Maturity](https://your-scanner/badge/{token})
    """
    org_id = _resolve_badge_token(token)
    if not org_id:
        return Response(content="Not Found", status_code=404, media_type="text/plain")

    maturity_level, migration_pct, org_name = None, 0.0, org_id
    try:
        assessments = _maturity_list(org_id, limit=1)
        if assessments:
            maturity_level = assessments[0].get("maturity_level")
    except Exception:
        pass
    try:
        _rc = _asset_risk_counts(org_id)
        total = _rc["total"]
        safe = _rc.get("safe", 0) + _rc.get("low", 0)
        migration_pct = round(safe / total * 100, 1) if total else 0
    except Exception:
        pass

    svg = _generate_badge_svg(maturity_level, migration_pct, org_name)
    return Response(
        content=svg,
        media_type="image/svg+xml",
        headers={"Cache-Control": "max-age=300", "X-Content-Type-Options": "nosniff"},
    )


