def _invite_acceptor_identity(request: Request) -> Dict[str, str]:
    """The signed-in account accepting an invitation; anonymous acceptance is refused.

    Verified token claims are the identity. Header identity is honoured only in non-production
    header-auth development mode, which is already trust-the-caller by design.
    """
    claims = getattr(request.state, "auth_claims", {}) or {}
    user_id = email = ""
    if isinstance(claims, dict) and claims and claims.get("auth_method") != "api_key":
        user_id = str(claims.get("sub") or claims.get("user_id") or "").strip()
        email = str(claims.get("email") or "").strip().lower()
    elif AUTH_MODE != "jwt" and not PRODUCTION_ENVIRONMENT:
        user_id = str(request.headers.get("x-user-id") or "").strip()
        email = str(request.headers.get("x-user-email") or (user_id if "@" in user_id else "")).strip().lower()
    if not user_id or user_id in {"local-user", "anon", "jwt-user"}:
        raise HTTPException(status_code=401, detail="Sign in before accepting an invitation; it is bound to the account that accepts it.")
    return {"user_id": user_id[:200], "email": email[:320]}


class AcceptInviteRequest(BaseModel):
    token: str = Field(..., min_length=8, max_length=256)


@app.post("/admin/accept-invite")
@app.post("/v1/admin/accept-invite")
@limiter.limit(str(os.getenv("PQC_RATE_LIMIT_AUTH", "10/minute") or "10/minute").strip())
def api_admin_accept_invite(body: AcceptInviteRequest, request: Request):
    """Accept an invitation: the token must exist, be unexpired and unused, and name the signed-in email.

    Acceptance claims the invitation atomically (single use under concurrency) and records an
    organization membership for the accepting user id.

    The token is read from the JSON body, not from `?token=`. The landing link carries it in a URL
    fragment, which a browser never sends to a server -- but the acceptance call used to put the
    same live token in the request line, where every proxy, WAF, load balancer and APM in front of
    the app writes it to an access log. POST /auth/invite/preview already took it in the body; this
    matches, and the design's "the token is never in a URL" is now true end to end.
    """
    identity = _invite_acceptor_identity(request)
    try:
        result = _platform_access.accept_invitation_for_user(body.token, user_id=identity["user_id"], email=identity["email"])
    except _platform_access.InvitationError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail) from None
    return {"api_version": "v1", **result}


