@app.post("/agent/chat")
@app.post("/v1/agent/chat")
async def api_agent_chat(body: AgentChatRequest, request: Request):
    """
    Non-streaming AI agent endpoint.
    Buffers the full response and returns JSON: {reply, evidence, error}.

    Shadowed: routers/agent.py is mounted earlier and serves /agent/chat (including the built-in
    guidance when no AI provider is configured, see _agent_builtin_answer below).
    """
    actor = _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                          action="agent.chat", resource_type="organization", resource_id="")
    org_id = str((actor or {}).get("org_id") or
                 getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)

    text_parts: List[str] = []
    evidence: Dict[str, Any] = {}
    error: str = ""

    async for event_str in _agent_stream(body.message, body.history, org_id):
        raw = event_str.strip()
        if not raw.startswith("data:"):
            continue
        try:
            evt = json.loads(raw[5:].strip())
        except Exception:
            continue
        t = evt.get("type", "")
        if t == "token":
            text_parts.append(evt.get("text", ""))
        elif t == "evidence":
            evidence = evt.get("data") or {}
        elif t == "error":
            error = evt.get("text", "")

    return {"api_version": "v1", "reply": "".join(text_parts), "evidence": evidence, "error": error}


_AGENT_LAUNCH_WORDS = re.compile(r"go.?live|launch|blocker|production|market.?ready|ready|readiness|fix first|priorit|next|plan",
                                 re.IGNORECASE)


def _agent_builtin_answer(question: str) -> Dict[str, Any]:
    """routers/agent.py calls this (in a worker thread) when no AI provider is configured."""
    ctx = _assistant_platform_context()
    return _agent_builtin_guidance(_mask_secrets(str(question or "")[:2000]), ctx)


def _agent_builtin_guidance(question: str, ctx: Dict[str, Any]) -> Dict[str, Any]:
    """Rule-based CipherLens answer (the /assistant/chat rules) for servers without an AI provider.

    Launch and prioritisation questions, which the console's CipherLens prompts ask most, get the
    workspace status summary rather than the generic "I can only help with..." reply."""
    rule = _assistant_rule_response(question, ctx)
    if rule.get("intent") in {"out_of_scope", "answer"} and _AGENT_LAUNCH_WORDS.search(question or ""):
        rule = {
            "intent": "summarize_status",
            "reply": (
                f"Current posture: {ctx.get('assets', 0)} assets, {ctx.get('repositories', 0)} repos, "
                f"{ctx.get('active_work', 0)} active work cards, workflow readiness {ctx.get('readiness', 0)}%. "
                "For go-live blockers open Administration > Launch readiness. Recommended next steps: scan your "
                "external endpoints for evidence, connect repository ownership, then move one remediation through "
                "validation and export the evidence report."
            ),
            "actions": ["open_workflow", "open_remediation_queue", "open_report"],
        }
    return rule


@app.post("/agent/chat/stream")
@app.post("/v1/agent/chat/stream")
async def api_agent_chat_stream(body: AgentChatRequest, request: Request):
    """
    Streaming AI agent endpoint — returns text/event-stream SSE.

    Event types the client receives:
      status   — progress update (Thinking…, Scanning foo.com…, etc.)
      token    — one chunk of the final markdown answer text
      evidence — structured scan/compliance data attached at end
      error    — fatal error string
      done     — end-of-stream sentinel
    """
    from fastapi.responses import StreamingResponse

    actor = _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                          action="agent.chat.stream", resource_type="organization", resource_id="")
    org_id = str((actor or {}).get("org_id") or
                 getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    user_id = _get_actor_id(request)

    async def _generate():
        async for chunk in _agent_stream(body.message, body.history, org_id, user_id):
            yield chunk

    return StreamingResponse(
        _generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


# =============================================================================
# GitHub OAuth — per-user token management
# =============================================================================

try:
    from services.github_oauth import (
        get_authorization_url as _gh_auth_url,
        exchange_code as _gh_exchange_code,
        store_token as _gh_store_token,
        get_connection_info as _gh_connection_info,
        delete_token as _gh_delete_token,
        get_token as _gh_get_token,
        GITHUB_CLIENT_ID as _GH_CLIENT_ID,
    )
    _GH_OAUTH_AVAILABLE = bool(_GH_CLIENT_ID)
except Exception:
    _GH_OAUTH_AVAILABLE = False


def _get_actor_id(request: Request) -> str:
    """Extract current user ID from request (headers mode or JWT claims)."""
    claims = getattr(request.state, "auth_claims", {}) or {}
    if isinstance(claims, dict):
        uid = (claims.get("sub") or claims.get("email") or
               claims.get("user_id") or claims.get("actor_id") or "")
        if uid:
            return str(uid).strip()
    return str(request.headers.get("x-user-id") or "local-user").strip()


@app.get("/auth/github/connect")
async def github_oauth_connect(request: Request):
    """Redirect user to GitHub for OAuth authorization."""
    from fastapi.responses import RedirectResponse
    if not _GH_OAUTH_AVAILABLE:
        from fastapi.responses import JSONResponse
        return JSONResponse({"error": "GitHub OAuth not configured. Set GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET."}, status_code=503)
    org_id = _extract_org_id_from_request(request)
    user_id = _get_actor_id(request)
    import base64 as _b64
    import json as _json
    state = _b64.urlsafe_b64encode(_json.dumps({"org": org_id, "uid": user_id}).encode()).decode()
    url = _gh_auth_url(state=state)
    return RedirectResponse(url)


@app.get("/auth/github/callback")
async def github_oauth_callback(code: str = "", state: str = "", error: str = ""):
    """GitHub redirects here after the user authorises. Exchange code for token."""
    from fastapi.responses import HTMLResponse
    if error:
        return HTMLResponse(_gh_callback_page(success=False, message=f"GitHub declined: {error}"))
    if not code:
        return HTMLResponse(_gh_callback_page(success=False, message="No code received from GitHub."))
    try:
        import base64 as _b64
        import json as _json
        ctx: dict = {}
        try:
            ctx = _json.loads(_b64.urlsafe_b64decode(state + "==").decode())
        except Exception:
            pass
        org_id = str(ctx.get("org") or DEFAULT_ORG_ID)
        user_id = str(ctx.get("uid") or "local-user")
        token_info = _gh_exchange_code(code)
        _gh_store_token(
            org_id=org_id, user_id=user_id,
            access_token=token_info["access_token"],
            scope=token_info["scope"],
            github_login=token_info["github_login"],
            github_id=token_info["github_id"],
            avatar_url=token_info["avatar_url"],
        )
        return HTMLResponse(_gh_callback_page(
            success=True,
            message=f"Connected as @{token_info['github_login']}. You can close this tab.",
            login=token_info["github_login"],
            avatar=token_info["avatar_url"],
        ))
    except Exception as exc:
        return HTMLResponse(_gh_callback_page(success=False, message=f"Connection failed: {exc}"))


def _gh_callback_page(success: bool, message: str, login: str = "", avatar: str = "") -> str:
    """The window GitHub returns the user to after an OAuth round trip.

    Styled to the same palette as /launch and the console so the popup does not
    look like it came from somewhere else mid-flow. The postMessage handshake and
    auto-close behaviour are unchanged -- only the presentation.
    """
    accent = "var(--q1)" if success else "var(--danger)"
    icon = "✓" if success else "✕"
    heading = "GitHub connected" if success else "Connection failed"
    action = "Close tab" if success else "Try again"
    avatar_html = (
        f'<img class="avatar" src="{_html_escape(avatar)}" alt="" width="52" height="52">'
        if avatar else ""
    )
    login_html = f'<div class="login">@{_html_escape(login)}</div>' if login and success else ""
    return f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>GitHub Connection</title>
  <link rel="icon" href="/favicon.svg" type="image/svg+xml">
  <style>
    :root {{
      --bg: #05070d; --ink: #f4f8ff; --ink-muted: #8595ad;
      --line: rgba(148,176,220,.14); --line-bright: rgba(148,176,220,.28);
      --q1: #5eead4; --q2: #38bdf8; --q3: #818cf8; --danger: #fb7185;
      --sans: "Aptos","Segoe UI Variable Display","Segoe UI",system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;
      --mono: "Cascadia Code","Consolas",ui-monospace,SFMono-Regular,monospace;
    }}
    * {{ box-sizing: border-box; }}
    body {{
      margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px;
      background: var(--bg); color: var(--ink); font-family: var(--sans);
      -webkit-font-smoothing: antialiased;
    }}
    body::before {{
      content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 0;
      background:
        radial-gradient(700px 480px at 12% -10%, rgba(94,234,212,.14), transparent 60%),
        radial-gradient(620px 440px at 92% 4%, rgba(129,140,248,.14), transparent 58%);
    }}
    .box {{
      position: relative; z-index: 1; width: min(420px, 100%); text-align: center;
      padding: 40px 34px 32px; border: 1px solid var(--line); border-radius: 24px;
      background: linear-gradient(158deg, rgba(14,20,33,.9), rgba(6,9,16,.94));
      box-shadow: 0 30px 90px rgba(0,0,0,.5);
    }}
    .avatar {{ border-radius: 50%; margin-bottom: 16px; border: 1px solid var(--line-bright); }}
    .icon {{
      width: 52px; height: 52px; margin: 0 auto 20px; display: grid; place-items: center;
      border-radius: 16px; font-size: 24px; color: #04120f; font-weight: 700;
      background: {accent};
      box-shadow: 0 10px 30px rgba(56,189,248,.28);
    }}
    h1 {{ margin: 0 0 10px; font-size: 22px; font-weight: 640; letter-spacing: -.02em; }}
    p {{ margin: 0; color: var(--ink-muted); font-size: 14.5px; line-height: 1.55; }}
    .login {{ margin: 0 0 14px; font-family: var(--mono); font-size: 12.5px; color: var(--ink-muted); }}
    button {{
      margin-top: 26px; padding: 11px 22px; border-radius: 12px; cursor: pointer;
      font: inherit; font-size: 14.5px; font-weight: 600;
      border: 1px solid var(--line-bright); background: rgba(148,176,220,.06); color: var(--ink);
      transition: transform .18s ease, border-color .18s ease, background .18s ease;
    }}
    button:hover {{ transform: translateY(-2px); border-color: rgba(148,176,220,.5); background: rgba(148,176,220,.12); }}
    @media (prefers-reduced-motion: reduce) {{ button {{ transition: none; }} }}
  </style>
</head>
<body>
  <div class="box">
    {avatar_html}
    <div class="icon" aria-hidden="true">{icon}</div>
    <h1>{heading}</h1>
    {login_html}
    <p>{_html_escape(message)}</p>
    <button type="button" onclick="window.close()">{action}</button>
  </div>
  <script>
    if ({str(success).lower()}) {{
      // Notify the opener that GitHub is now connected
      if (window.opener) {{
        window.opener.postMessage({{type:'github_connected',login:'{login}'}}, '*');
      }}
      setTimeout(() => window.close(), 2000);
    }}
  </script>
</body>
</html>"""


@app.get("/v1/integrations/github/status")
async def github_integration_status(request: Request):
    """Return GitHub connection status for the current user."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="integrations.github.status", resource_type="organization", resource_id="")
    org_id = _extract_org_id_from_request(request)
    user_id = _get_actor_id(request)
    info = _gh_connection_info(org_id, user_id) if _GH_OAUTH_AVAILABLE else None
    return {
        "oauth_configured": _GH_OAUTH_AVAILABLE,
        "connected": info is not None,
        "github_login": info.get("github_login") if info else None,
        "avatar_url": info.get("avatar_url") if info else None,
        "scope": info.get("scope") if info else None,
        "connected_at": info.get("connected_at") if info else None,
        "connect_url": "/auth/github/connect" if _GH_OAUTH_AVAILABLE else None,
    }


@app.delete("/v1/integrations/github")
async def github_integration_disconnect(request: Request):
    """Disconnect (revoke) the current user's GitHub token."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="integrations.github.disconnect", resource_type="organization", resource_id="")
    org_id = _extract_org_id_from_request(request)
    user_id = _get_actor_id(request)
    ok = _gh_delete_token(org_id, user_id) if _GH_OAUTH_AVAILABLE else False
    return {"disconnected": ok}


