def _board_risk_aggregate(org_id: str) -> Dict[str, Any]:
    """Pull the data Board Risk needs from the existing DB tables."""
    compliance: Dict[str, Any] = {"summary": {}, "vulnerabilities": [], "remediations": []}
    portfolio:  Dict[str, Any] = {"summary": {}, "items": []}
    metrics:    Dict[str, Any] = {"roi": {}, "drift_analytics": {}}
    policy:     Dict[str, Any] = {"version": "v1"}

    try:
        # No direct database handle here: _latest_asset_scan_facts reads through the
        # backend-agnostic layer, so this works on both SQLite and Postgres.
        scans = _latest_asset_scan_facts(org_id, limit=5000)

        total_assets = len({f"{r['host']}:{r['port']}" for r in scans})
        high_risk    = sum(1 for r in scans if (r["risk_level"] or "").lower() in ("critical", "high"))
        safe_assets  = sum(1 for r in scans if (r["risk_level"] or "").lower() in ("safe", "low"))

        migration_pct = round(safe_assets / total_assets * 100, 1) if total_assets else 0

        portfolio["summary"] = {
            "assets_total": total_assets,
            "assets_with_quantum_data": len(scans),
            "blocked_assets": 0,
            "actionable_migration_paths": high_risk,
            "average_crypto_agility_score": migration_pct,
        }
        portfolio["items"] = [
            {
                "asset_key": r["asset_key"],
                "tls_version": r["tls_version"] or "",
                "classical_algorithm": r["algorithm"] or "",
                "harvest_now_decrypt_later_risk": "high" if (r["risk_level"] or "").lower() in ("critical", "high") else "low",
                "classical_crypto_dependency": (r["algorithm"] or "").upper() not in ("ML-KEM", "ML-DSA", "KYBER", "DILITHIUM"),
                "provider_pqc_support_status": "unknown",
                # No per-asset agility score is invented here. The old value (80 for
                # anything not high-risk) was a made-up constant; an asset's agility
                # is not measured until a migration path is tracked for it.
                "crypto_agility_score": None,
            }
            for r in scans
        ]

        compliance["summary"] = {
            "assets_total": total_assets,
            "open_assets": high_risk,
            "remediations_total": 0,
            "validated_passed_total": 0,
            "verified_closed_total": 0,
            "drifted_total": 0,
        }
    except Exception:
        logging.warning("[BOARD RISK] aggregate failed", exc_info=True)

    return compliance, portfolio, metrics, policy


