# ── Crypto Governance ─────────────────────────────────────────────────────────

@app.get("/crypto-governance/certs")
@app.get("/v1/crypto-governance/certs")
def api_cert_lifecycle(request: Request, warning_days: int = 30):
    """Certificate expiry lifecycle report for all assets in this org."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="crypto_governance.certs", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    # _latest_asset_scan_facts already returns one row per asset, newest first. Certificate
    # expiry (cert_not_after) is not persisted per asset, so the lifecycle report will report it
    # as unknown rather than crashing on a column that does not exist.
    seen = {r["asset_key"]: dict(r) for r in _latest_asset_scan_facts(org_id, limit=500)}

    def latest_for_asset(asset_key: str):
        return seen.get(asset_key, {})

    assets = [{"asset_key": k, "owner": "", "team": "", "repository_id": 0} for k in seen]
    report = _cert_lifecycle_report(assets=assets, latest_for_asset=latest_for_asset, warning_days=warning_days)
    return {"api_version": "v1", "org_id": org_id, **report}


@app.get("/crypto-governance/shadow-it")
@app.get("/v1/crypto-governance/shadow-it")
def api_shadow_it(request: Request):
    """Shadow IT report — runtime-observed hosts not in the managed asset inventory."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="crypto_governance.shadow_it", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    # list_assets() dispatches to Postgres or SQLite and already scopes to the current org; the
    # previous inline query (with a sqlite_master existence probe) only ever read SQLite, so on a
    # Postgres deployment every managed asset looked unmanaged and everything showed as shadow IT.
    asset_rows = list_assets(limit=1000) or []

    # Scanned hosts come from scan_results (one row per asset); `scans` has no host column.
    seen_scan = {r["asset_key"]: dict(r) for r in _latest_asset_scan_facts(org_id, limit=500)}

    managed_keys = {str(r.get("asset_key") or "") for r in asset_rows if r.get("asset_key")}

    def latest_for_asset(asset_key: str):
        return seen_scan.get(asset_key, {})

    assets = [{"asset_key": k} for k in managed_keys]
    runtime = [{"asset_key": k, "observed_count": 1} for k in seen_scan]
    report = _shadow_it_report(assets=assets, runtime_assets=runtime, latest_for_asset=latest_for_asset)
    return {"api_version": "v1", "org_id": org_id, **report}


# ── Remediation Feed ──────────────────────────────────────────────────────────

@app.get("/remediation-feed")
@app.get("/v1/remediation-feed")
def api_remediation_feed(
    request: Request,
    include_closed: bool = False,
    asset_key: str = "",
    repository: str = "",
    kind: str = "",
):
    """Kanban-style remediation feed cards for the active org."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="remediation_feed.list", resource_type="organization", resource_id="*")
    remeds = list_remediations()
    mig_tasks = list_migration_tasks()
    cards = []
    for r in remeds:
        val = get_latest_validation_job_for_remediation(int(r.get("id") or 0))
        cards.append(_feed_card(r, val))
    for t in mig_tasks:
        cards.append(_feed_migration_card(t))
    filtered = _feed_filter(
        cards,
        include_closed=include_closed,
        asset_key=asset_key,
        repository=repository,
        kind=kind,
    )
    # Sort by priority descending
    filtered.sort(key=lambda c: -int(c.get("priority") or 0))
    summary = _feed_summary(filtered)
    return {"api_version": "v1", "summary": summary, "cards": filtered}


# ── PR Readiness ──────────────────────────────────────────────────────────────

@app.get("/remediations/{remediation_id}/pr-readiness-check")
@app.get("/v1/remediations/{remediation_id}/pr-readiness-check")
def api_pr_readiness_check(remediation_id: int, request: Request, github_credential_id: int = 0):
    """Machine-readable PR readiness checklist for a remediation before GitHub PR creation."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="remediations.pr_readiness", resource_type="remediation", resource_id=str(remediation_id))
    rem = get_remediation(remediation_id)
    if not rem:
        raise HTTPException(status_code=404, detail="Remediation not found")
    repo = None
    repo_id = int(rem.get("repo_id") or 0)
    if repo_id:
        try:
            repo = get_repository_by_id(repo_id)
        except Exception:
            pass
    val = get_latest_validation_job_for_remediation(remediation_id)
    result = _build_pr_readiness(rem, repo, val, github_credential_id=github_credential_id)
    return {"api_version": "v1", **result}


