    """Compare this org's PQC score against sector peers."""
    _require_role(request, allowed_roles=["viewer", "operator", "admin"],
                  action="peer_benchmark.compare", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    scans = [
        {"host": r["host"], "port": r["port"], "algorithm": r["algorithm_detail"] or r["algorithm"],
         "cipher": r["cipher_name"] or r["sig_algorithm"], "risk_level": r["risk_level"],
         "tls_version": r["tls_version"]}
        for r in _latest_asset_scan_facts(org_id, limit=1000)
    ]
    # Compute org score from FIPS report
    if scans:
        report = _fips_report(scans)
        org_score = float(report.get("overall_score") or 0)
    else:
        org_score = 0.0
    result = _peer_benchmark(org_score, sector=sector)
    return {"api_version": "v1", "org_id": org_id, **result}


