@app.get("/compliance-ledger/snapshot")
@app.get("/v1/compliance-ledger/snapshot")
def api_compliance_ledger_snapshot(request: Request):
    """Build a tamper-evident hash-chain snapshot for cross-border PQC compliance evidence."""
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, ["viewer", "analyst", "admin", "owner", "operator"],
                  action="compliance_ledger.snapshot", resource_type="organization", resource_id=org_id)
    assets = list_assets(limit=500)
    scans = list_scan_rows(limit=100)
    remediations = list_remediations(limit=500)
    frameworks = _reg_list_frameworks()
    proofs = _get_compliance_proofs(org_id)
    raw_entries: List[Dict[str, Any]] = [
        {"type": "regulatory_frameworks", "count": len(frameworks), "items": frameworks[:25]},
        {"type": "assets", "count": len(assets), "items": assets[:50]},
        {"type": "scans", "count": len(scans), "items": scans[:50]},
        {"type": "remediations", "count": len(remediations), "items": remediations[:50]},
        {"type": "zk_proofs", "count": len(proofs), "items": proofs[:50]},
    ]
    previous_hash = "0" * 64
    entries: List[Dict[str, Any]] = []
    for idx, entry in enumerate(raw_entries, start=1):
        payload = _json_safe(entry)
        digest = hashlib.sha256(
            (previous_hash + json.dumps(payload, sort_keys=True, default=str)).encode("utf-8")
        ).hexdigest()
        entries.append({
            "index": idx,
            "timestamp": _now_iso(),
            "previous_hash": previous_hash,
            "hash": digest,
            "entry": payload,
        })
        previous_hash = digest
    return {
        "api_version": "v1",
        "kind": "cross_border_pqc_compliance_ledger_snapshot",
        "organization_id": org_id,
        "generated_at": _now_iso(),
        "root_hash": previous_hash,
        "entries": entries,
        "verification": "Recompute SHA-256 over previous_hash + canonical JSON(entry) for each entry.",
    }


