@app.get("/airlock/onboarding-status")
@app.get("/v1/airlock/onboarding-status")
def api_airlock_onboarding_status(request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, ["viewer", "operator", "admin", "owner"],
                  action="airlock.onboarding_status", resource_type="organization", resource_id=org_id)
    base = str(request.base_url).rstrip("/")
    readiness_checks = api_airlock_enterprise_readiness(request)["checks"]
    flight_events = list_flight_recorder_events(limit=25, intent="airlock_runtime_handshake_proof")
    passport = _trust_passport(org_id)
    steps = [
        {
            "key": "production_hardening",
            "title": "Production hardening",
            "status": "complete" if all(c["status"] == "pass" for c in readiness_checks) else "blocked",
            "detail": "JWT auth, Airlock signing key, required agent signatures, and monitoring must be configured.",
        },
        {
            "key": "install_agent",
            "title": "Install customer-side Airlock",
            "status": "complete" if flight_events else "ready",
            "detail": "Run the one-command installer. It installs a read-only proof collector.",
        },
        {
            "key": "verify_proof",
            "title": "Verify first flight-recorder proof",
            "status": "complete" if flight_events else "waiting",
            "detail": f"{len(flight_events)} runtime proof event(s) recorded.",
        },
        {
            "key": "simulate_change",
            "title": "Simulate change before enforcement",
            "status": "ready",
            "detail": "Run the change simulator before routing traffic or enabling kill-switch blocking.",
        },
        {
            "key": "issue_passport",
            "title": "Issue Trust Passport",
            "status": "complete" if passport.get("status") else "ready",
            "detail": f"Current passport status: {passport.get('status', 'unknown')}.",
        },
    ]
    return {
        "api_version": "v1",
        "kind": "enterprise_airlock_onboarding_status",
        "organization_id": org_id,
        "status": "complete" if all(s["status"] == "complete" for s in steps) else "in_progress",
        "steps": steps,
        "install_commands": {
            "bash_jwt": f'curl -fsSL -H "Authorization: Bearer $PQC_TOKEN" "{base}/airlock/install.sh?customer_id=customer" | bash',
            "powershell_jwt": f'iwr -Headers @{{Authorization="Bearer $env:PQC_TOKEN"}} "{base}/airlock/install.ps1?customer_id=customer" | iex',
            "bash_dev_headers": f'curl -fsSL -H "x-user-role: operator" -H "x-user-id: airlock-admin" -H "x-org-id: {org_id}" "{base}/airlock/install.sh?customer_id=customer" | bash',
        },
        "next_action": next((s for s in steps if s["status"] != "complete"), steps[-1]),
    }


