@app.post("/airlock/flight-recorder/submit")
@app.post("/v1/airlock/flight-recorder/submit")
def api_airlock_flight_recorder_submit(body: AirlockFlightRecorderSubmitRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    actor = _require_role(request, ["operator", "admin", "owner"],
                          action="airlock.flight_recorder.submit", resource_type="organization", resource_id=org_id)
    signature_status = _verify_airlock_agent_signature(request, org_id, body.model_dump())
    accepted: List[Dict[str, Any]] = []
    rejected: List[Dict[str, Any]] = []
    for obs in body.observations[:1000]:
        if bool(obs.get("payload_visible")):
            rejected.append({"service_name": obs.get("service_name") or obs.get("peer"), "reason": "payload_visible_not_allowed"})
            continue
        clean, redactions = _airlock_redact(obs)
        service = str(clean.get("service_name") or clean.get("peer") or clean.get("sni") or "unknown")[:256]
        group = str(clean.get("negotiated_group") or "")
        tls_version = str(clean.get("tls_version") or "")
        hybrid = "MLKEM" in group or "ML-KEM" in group
        decision = "verified" if hybrid else "observed"
        event = append_flight_recorder_event(
            actor_type="agent" if signature_status.get("agent_id") else "human",
            actor_id=str(signature_status.get("agent_id") or actor.get("actor_id") or body.agent_id),
            actor_role=str(actor.get("actor_role") or "operator"),
            intent="airlock_runtime_handshake_proof",
            resource_type="service",
            resource_id=service,
            policy_version=body.policy_version,
            decision=decision,
            outcome="accepted",
            reason=f"TLS {tls_version} group {group or 'unknown'} recorded without payload inspection",
            evidence_refs={
                "batch_id": body.batch_id,
                "cert_sha256": clean.get("cert_sha256", ""),
                "agent_signature_verified": signature_status.get("verified", False),
            },
            details={**clean, "redaction_report": redactions, "pqc_hybrid": hybrid},
        )
        accepted.append(event)
        try:
            _tel_push("runtime_handshake_proof", {
                "flight_event_id": event.get("id"),
                "service_name": service,
                "tls_version": tls_version,
                "negotiated_group": group,
                "pqc_hybrid": hybrid,
                "agent_signature_verified": signature_status.get("verified", False),
                "source": "airlock_flight_recorder",
            }, org_id)
        except Exception:
            logging.debug("[TELEMETRY] flight recorder telemetry emission failed", exc_info=True)
    return {
        "api_version": "v1",
        "kind": "enterprise_airlock_flight_recorder_submission",
        "organization_id": org_id,
        "batch_id": body.batch_id,
        "accepted_count": len(accepted),
        "rejected_count": len(rejected),
        "agent_signature": signature_status,
        "summary": _flight_recorder_summary(accepted),
        "events": accepted,
        "rejected": rejected,
    }


