@app.post("/airlock/change-simulator")
@app.post("/v1/airlock/change-simulator")
def api_airlock_change_simulator(body: AirlockChangeSimulatorRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, ["viewer", "operator", "admin", "owner"],
                  action="airlock.change_simulator", resource_type="organization", resource_id=org_id)
    services = body.services
    if not services:
        state = _airlock_org_state(org_id)
        services = [
            {
                "name": str(s.get("asset_key") or f"{s.get('host','')}:{s.get('port','')}" or "service"),
                "tls_version": s.get("tls_version") or s.get("version") or "",
                "algorithm": s.get("algorithm") or s.get("cipher") or "",
                "owner": s.get("owner") or "",
            }
            for s in state["scans"][:100]
        ]
    blocked = []
    compatible = []
    for svc in services:
        text = json.dumps(_json_safe(svc), default=str)
        has_blocked = any(str(b).replace("*", "") in text for b in body.blocked_algorithms)
        supports_hybrid = any(g in text for g in body.required_tls_groups) or bool(svc.get("supports_hybrid_tls"))
        item = {
            "service": svc.get("name") or svc.get("service_name") or svc.get("asset_key") or "service",
            "owner": svc.get("owner") or "",
            "would_block": has_blocked,
            "supports_required_hybrid_group": supports_hybrid,
            "risk": "high" if has_blocked and not supports_hybrid else "medium" if has_blocked else "low",
        }
        (blocked if item["would_block"] or not item["supports_required_hybrid_group"] else compatible).append(item)
    legacy_clients = [
        c for c in body.legacy_clients
        if str(c.get("max_tls") or c.get("tls_version") or "") < "TLSv1.3" or c.get("supports_hybrid_tls") is False
    ]
    plan = {
        "mode": body.enforcement_mode,
        "rollout_percent": body.rollout_percent,
        "phase_1": "monitor only and collect runtime handshake proofs",
        "phase_2": f"route {body.rollout_percent}% of compatible services through middleware",
        "phase_3": "block new weak crypto in CI/CD",
        "rollback": "disable middleware route and set kill-switch enforcement_mode=detect_only",
    }
    result = {
        "services_seen": len(services),
        "compatible_services": compatible,
        "at_risk_services": blocked,
        "legacy_clients": legacy_clients,
        "estimated_breakage_risk": "high" if legacy_clients or len(blocked) > len(compatible) else "medium" if blocked else "low",
        "customer_action_required": ["approve rollout", "confirm owners for high-risk services"] if blocked else ["approve rollout"],
        "plan": plan,
        "no_change_applied": True,
    }
    return _signed_airlock_envelope("airlock_autopilot_change_simulation", org_id, result)


@app.post("/airlock/remediation-pr-factory")
@app.post("/v1/airlock/remediation-pr-factory")
def api_airlock_remediation_pr_factory(body: AirlockRemediationPrFactoryRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, ["viewer", "operator", "admin", "owner"],
                  action="airlock.remediation_pr_factory", resource_type="organization", resource_id=org_id)
    branch = f"{body.branch_prefix}/{hashlib.sha256(f'{body.repository}:{body.asset_key}:{body.finding}'.encode('utf-8')).hexdigest()[:10]}"
    patch = f"""diff --git a/pqc-airlock-policy.json b/pqc-airlock-policy.json
new file mode 100644
--- /dev/null
+++ b/pqc-airlock-policy.json
@@ -0,0 +1,15 @@
+{{
+  "asset_key": "{body.asset_key}",
+  "finding": "{body.finding}",
+  "required_tls_groups": ["X25519MLKEM768", "SecP256r1MLKEM768"],
+  "blocked_algorithms": ["TLS_RSA_*", "RSA key exchange", "RSA-1024", "SHA1 signatures"],
+  "approval_required": true,
+  "raw_customer_data_exported": false
+}}
"""
    workflow = """name: PQC Airlock Remediation Gate
on: [pull_request]
jobs:
  pqc-airlock:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Verify PQC policy exists
        run: test -f pqc-airlock-policy.json
      - name: Block quantum-vulnerable crypto regressions
        run: python tools/pqc_crypto_gate.py --diff origin/main...HEAD || true
"""
    subject = {
        "repository": body.repository,
        "branch": branch,
        "asset_key": body.asset_key,
        "finding": body.finding,
        "builder": "pqc-airlock-remediation-pr-factory",
        "materials": [{"uri": f"pqc://finding/{hashlib.sha256(body.finding.encode()).hexdigest()}", "digest": {"sha256": hashlib.sha256(body.finding.encode()).hexdigest()}}],
        "raw_repository_exported": False,
    }
    slsa = {
        "_type": "https://in-toto.io/Statement/v1",
        "subject": [{"name": body.repository, "digest": {"sha256": hashlib.sha256(patch.encode()).hexdigest()}}],
        "predicateType": "https://slsa.dev/provenance/v1",
        "predicate": subject,
    }
    artifacts = {
        "README.md": f"# PQC Airlock PR Factory\n\nRepository: {body.repository}\nBranch: {branch}\nFinding: {body.finding}\n\nThis bundle is review-only. It does not push to the customer repository.\n",
        "patch.diff": patch,
        "pqc-airlock-policy.json": json.dumps(subject, indent=2, sort_keys=True),
    }
    if body.include_ci_gate:
        artifacts[".github/workflows/pqc-airlock-remediation-gate.yml"] = workflow
    if body.include_slsa:
        artifacts["slsa-provenance.intoto.json"] = json.dumps(slsa, indent=2, sort_keys=True)
    if body.include_middleware_policy:
        artifacts["middleware-route-policy.json"] = json.dumps({
            "asset_key": body.asset_key,
            "mode": "candidate",
            "route_through_middleware": True,
            "required_tls_groups": ["X25519MLKEM768", "SecP256r1MLKEM768"],
        }, indent=2, sort_keys=True)
    envelope = _signed_airlock_envelope("airlock_signed_remediation_pr", org_id, subject)
    return {
        "api_version": "v1",
        "kind": "airlock_signed_remediation_pr_factory",
        "branch": branch,
        "profile": subject,
        "artifacts": artifacts,
        "bundle": _airlock_bundle("pqc-airlock-remediation-pr.zip", artifacts),
        "signature": envelope["signature"],
    }


@app.post("/privacy-cbom/fingerprint")
@app.post("/v1/privacy-cbom/fingerprint")
def api_privacy_cbom_fingerprint(body: PrivacyCbomFingerprintRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, ["viewer", "operator", "admin", "owner"],
                  action="privacy_cbom.fingerprint", resource_type="organization", resource_id=org_id)
    components = body.components or list((body.cbom or {}).get("components") or [])
    salt = body.salt or hashlib.sha256(f"{org_id}:privacy-cbom".encode("utf-8")).hexdigest()[:16]
    fingerprints = []
    for comp in components[:5000]:
        name = str(comp.get("name") or comp.get("bom-ref") or comp.get("purl") or "component")
        version = str(comp.get("version") or "")
        kind = str(comp.get("type") or comp.get("kind") or "library")
        algo = str(comp.get("algorithm") or comp.get("crypto_algorithm") or comp.get("properties") or "")
        raw = f"{salt}|{kind}|{name}|{version}|{algo}"
        item = {
            "fingerprint": hashlib.sha256(raw.encode("utf-8")).hexdigest(),
            "kind": kind,
            "algorithm_family": "pqc" if "ML-" in algo or "MLKEM" in algo else "classical" if algo else "unknown",
        }
        if not body.reveal_counts_only:
            item.update({"name": name, "version": version, "algorithm": algo})
        fingerprints.append(item)
    summary = {
        "component_count": len(components),
        "fingerprint_count": len(fingerprints),
        "pqc_count": sum(1 for f in fingerprints if f["algorithm_family"] == "pqc"),
        "classical_count": sum(1 for f in fingerprints if f["algorithm_family"] == "classical"),
        "salt_id": hashlib.sha256(salt.encode("utf-8")).hexdigest()[:12],
        "raw_component_names_exported": not body.reveal_counts_only,
    }
    return _signed_airlock_envelope("privacy_preserving_cbom_fingerprint", org_id, {
        "summary": summary,
        "fingerprints": fingerprints,
        "privacy_boundary": "salted hashes by default; raw names hidden unless reveal_counts_only=false",
    })


