def api_firmware_proof(body: FirmwareProofRequest, request: Request):
    org_id = str(getattr(request.state, "org_id", current_organization_id()) or DEFAULT_ORG_ID)
    _require_role(request, ["viewer", "operator", "admin", "owner"],
                  action="firmware.proof", resource_type="organization", resource_id=org_id)
    if body.raw_firmware_uploaded:
        raise HTTPException(status_code=422, detail="raw firmware upload is not accepted on this proof endpoint; submit hash/provenance only")
    firmware_hash = body.sha256 or hashlib.sha256(f"{body.filename}:{body.size_bytes}:{body.provenance}".encode("utf-8")).hexdigest()
    critical = sum(1 for f in body.findings if str(f.get("severity") or "").lower() == "critical")
    subject = {
        "filename": body.filename,
        "sha256": firmware_hash,
        "size_bytes": body.size_bytes,
        "finding_count": len(body.findings),
        "critical_count": critical,
        "provenance": body.provenance,
        "raw_firmware_exported": False,
    }
    return {
        "api_version": "v1",
        "kind": "zero_knowledge_firmware_provenance",
        "credential": _w3c_credential(org_id, "PQCFirmwareProvenanceCredential", subject),
        "attestation": _signed_airlock_envelope("firmware_hash_proof", org_id, subject),
    }


