@app.get("/crypto-agility")
@app.get("/v1/crypto-agility")
def api_crypto_agility(request: Request):
    _require_role(request, ["viewer", "analyst", "admin", "owner"],
                  action="agility.score", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    unavailable: List[Dict[str, str]] = []
    # scans, assets, scan_results and remediations are core tables: on a Postgres deployment they
    # are NOT in the local SQLite file. Reading them through _db() returned nothing there, and the
    # `except Exception: pass` around each read turned that into a confident zero -- an agility
    # score computed from "no remediations, no scan cadence" on an estate that had both.
    scan_times = _aux(unavailable, "scan_cadence", lambda: recent_scan_result_times(limit=2000), [])
    rems = _aux(unavailable, "remediations", lambda: list_remediations(limit=500), [])
    # The rest are service-owned tables that only have a SQLite implementation (see
    # docs/FEATURE_STORE_POSTGRES_MIGRATION.md). A table that does not exist means the feature is
    # not in use and counts zero; any other failure is reported rather than silently zeroed.
    with _db() as db:
        canary_count = _aux_sqlite_scalar(db, unavailable, "hndl_canaries",
                                          "SELECT COUNT(*) FROM hndl_canary_tokens WHERE organization_id=?",
                                          (org_id,), 0)
        playbook_count = _aux_sqlite_scalar(db, unavailable, "playbooks",
                                            "SELECT COUNT(*) FROM playbooks WHERE org_id=?", (org_id,), 0)
        alert_count = _aux_sqlite_scalar(db, unavailable, "alert_rules",
                                         "SELECT COUNT(*) FROM alert_rules WHERE org_id=?", (org_id,), 0)
        has_intent = bool(_aux_sqlite_scalar(
            db, unavailable, "security_intent",
            "SELECT 1 FROM security_intents WHERE org_id=? AND status='published' LIMIT 1", (org_id,), 0))
        cicd = _aux_sqlite_scalar(db, unavailable, "cicd_gate",
                                  "SELECT 1 FROM scan_events WHERE org_id=? AND event_type LIKE '%cicd%' LIMIT 1",
                                  (org_id,), None)
        has_cicd = bool(cicd) if cicd is not None else canary_count > 0  # fallback heuristic

    # scan_results is keyed by asset_key ("host:port") and has no host, port, algorithm,
    # cipher or scan_time column. Reading those names returned nothing on every row, so the
    # score was built from one phantom asset with no algorithms and an assumed cadence.
    # _latest_asset_scan_facts does the real mapping, and is what the board report uses.
    facts = _latest_asset_scan_facts(org_id, limit=5000)

    # Coverage means "of the assets we know about, how many carry scan evidence". Measuring
    # it as scanned/scanned would always be 100%, which is not a measurement of anything.
    inventory = _aux(unavailable, "asset_inventory", lambda: list_assets(limit=5000), [])
    inventory_count = len({str(a.get("asset_key") or "").strip() for a in inventory if a.get("asset_key")})
    scanned_assets = len(facts)
    total_assets = max(inventory_count, scanned_assets)

    # Scan cadence is measured, never assumed: it needs at least two scan timestamps,
    # and a failed parse leaves it unmeasured rather than guessing a week.
    scan_times = sorted(str(t or "") for t in scan_times if t)
    freq_days = None
    if len(scan_times) >= 2:
        try:
            from datetime import datetime as _dt
            t1 = _dt.fromisoformat(scan_times[-1].replace("Z", "+00:00"))
            t0 = _dt.fromisoformat(scan_times[0].replace("Z", "+00:00"))
            span_days = (t1 - t0).total_seconds() / 86400.0
            freq_days = max(0.01, span_days / max(1, len(scan_times) - 1)) if span_days > 0 else None
        except Exception:
            freq_days = None

    algos = [str(f.get("algorithm") or "") for f in facts if f.get("algorithm")]

    vuln_count = sum(1 for f in facts if str(f.get("risk_level") or "").lower() in ("critical", "high"))
    critical_count = sum(1 for f in facts if str(f.get("risk_level") or "").lower() == "critical")

    # Remediation velocity
    resolved_rems = [r for r in rems if (r.get("status") or "").lower() in ("resolved", "done", "closed", "completed", "fixed")]
    avg_days = None
    if resolved_rems:
        days_list = []
        for r in resolved_rems:
            try:
                from datetime import datetime as _dt
                c = _dt.fromisoformat(str(r.get("created_at", "")).replace("Z", "+00:00"))
                u = _dt.fromisoformat(str(r.get("updated_at", "")).replace("Z", "+00:00"))
                days_list.append(max(0, (u - c).days))
            except Exception:
                pass
        if days_list:
            avg_days = sum(days_list) / len(days_list)

    result = _agility_report(
        total_assets=total_assets,
        scanned_assets=scanned_assets,
        scan_frequency_days=freq_days,
        algorithms_in_use=algos,
        quantum_vulnerable_count=vuln_count,
        critical_vuln_count=critical_count,
        avg_remediation_days=avg_days,
        open_remediations=len([r for r in rems if (r.get("status") or "").lower() not in ("resolved", "done", "closed")]),
        resolved_remediations=len(resolved_rems),
        has_cicd_gate=has_cicd,
        canary_token_count=canary_count,
        playbook_count=playbook_count,
        alert_rule_count=alert_count,
        has_security_intent=has_intent,
    )
    return {"api_version": "v1", "org_id": org_id, **result, "unavailable": unavailable}


