@app.get("/migration-velocity")
@app.get("/v1/migration-velocity")
def api_migration_velocity(request: Request):
    _require_role(request, ["viewer", "analyst", "admin", "owner"],
                  action="velocity.report", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    unavailable: List[Dict[str, str]] = []
    # remediations is a core table: on a Postgres deployment it is not in the local SQLite file,
    # so reading it through _db() inside `except Exception: pass` reported zero remediations and
    # the velocity report concluded there was nothing in flight.
    rems = _aux(unavailable, "remediations", lambda: list_remediations(limit=2000), [])
    # scan_results has no host/port/algorithm column: the raw SELECT produced rows whose
    # dedup key was always ":" and whose algorithm was always blank, so every estate looked
    # like one asset with nothing vulnerable — which is where "Migration complete" came from.
    scans = [
        {"host": f["host"], "port": f["port"], "algorithm": f["algorithm"], "scan_time": f["scanned_at"]}
        for f in _latest_asset_scan_facts(org_id, limit=5000)
    ]
    result = _velocity_report(scans=scans, remediations=rems)
    return {"api_version": "v1", "org_id": org_id, **result, "unavailable": unavailable}


