@app.get("/cbom")
@app.get("/v1/cbom")
def api_cbom_org(request: Request):
    """CycloneDX 1.5 CBOM aggregated across all scans for the org."""
    _require_role(request, ["viewer", "analyst", "admin", "owner"],
                  action="cbom.org", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    # scan_results is keyed by asset_key and has no host, port, algorithm, cipher, scan_time,
    # cert_subject or cert_expiry column. Reading those off the raw rows gave every asset the
    # dedup key ":" and a blank algorithm, so the whole estate collapsed into a single nameless
    # "TLS endpoint" component with no cryptography in it — an empty CBOM that still returned 200.
    # _latest_asset_scan_facts is the one place that maps the real columns.
    results = []
    for f in _latest_asset_scan_facts(org_id, limit=2000):
        # generate_cbom reads certificate facts under cert_* keys.
        key_type = f.get("key_type") or ""
        results.append({
            "host": f["host"],
            "port": f["port"],
            "algorithm": f["algorithm"],
            "tls_version": f["tls_version"],
            "risk_level": f["risk_level"] or "unknown",
            "signature_algorithm": f["sig_algorithm"],
            "cert_subject": f["asset_key"],
            "cert_key_type": key_type,
            # The real observed size. This used to be absent, so cbom.canonical_algorithm() fell
            # back to its defaults and the whole estate was exported as RSA-2048 / ECDSA-P256
            # however many 4096-bit and P-521 certificates it contained.
            "cert_key_bits": f.get("key_bits") or 0,
            "key_curve": f.get("key_curve") or "",
            "cipher_name": f.get("cipher_name") or "",
            # generate_cbom has always read key_exchange; the scanner never set it, so the CBOM's
            # key-exchange algorithm was always absent.
            "key_exchange": f.get("key_exchange") or "",
            "cert_sig_alg": f["sig_algorithm"],
            # An asset with no observed key was never contacted; exclude it rather than emit a
            # certificate component asserting cryptography nobody saw.
            "error": "" if key_type else "not_observed",
        })

    cbom = generate_cbom(results, org_name=org_id, scan_id="org-aggregate")
    return JSONResponse(content=cbom)


@app.get("/v1/cbom.csv")
@app.get("/cbom.csv")
def api_cbom_csv(request: Request):
    """Download org-wide crypto inventory as CSV (for auditors / spreadsheet import)."""
    _require_role(request, ["viewer", "analyst", "admin", "owner"],
                  action="cbom.csv", resource_type="organization", resource_id="*")
    import io as _io
    import csv as _csv
    org_id = _org(request)
    # scan_results is keyed by asset_key and has no host/port/cert_subject/cert_expiry columns, so
    # the previous query always raised and — swallowed by the except below — this export silently
    # produced a header-only CSV.
    facts = _latest_asset_scan_facts(org_id, limit=5000)
    out = _io.StringIO()
    w = _csv.writer(out)
    # key_bits, key_curve, cipher_name and key_exchange are persisted per asset now; a crypto
    # inventory that omits the key size is not an inventory an auditor can act on. Empty means the
    # scan did not observe that field.
    w.writerow(["host", "port", "algorithm", "key_bits", "key_curve", "tls_version", "cipher_name",
                "key_exchange", "risk_level", "signature_algorithm", "quantum_score", "scanned_at"])
    for r in facts:
        w.writerow([r["host"], r["port"], r["algorithm"], r.get("key_bits") or "",
                    r.get("key_curve") or "", r["tls_version"], r.get("cipher_name") or "",
                    r.get("key_exchange") or "", r["risk_level"],
                    r["sig_algorithm"], r["quantum_score"], r["scanned_at"]])
    from fastapi.responses import Response as _Resp
    return _Resp(
        content=out.getvalue(),
        media_type="text/csv",
        headers={"Content-Disposition": 'attachment; filename="crypto-inventory.csv"'},
    )


