    import io as _io
    import csv as _csv
    org_id = _org(request)
    # Same schema mismatch as /cbom.csv above; also note the old row unpacking read r[7] from a
    # six-column SELECT, so even a successful query would have raised IndexError.
    facts = sorted(_latest_asset_scan_facts(org_id, limit=5000), key=lambda r: (r["host"], r["port"]))

    # Simple compliance classification.
    # x25519 and ed25519 were on this list. They are classical elliptic-curve algorithms broken by
    # Shor's algorithm exactly like ECDSA, so every Ed25519 endpoint was exported to auditors as
    # "PQC-safe, compliant: YES". Only the NIST PQC standards belong here.
    pqc_safe = {"kyber", "ml-kem", "mlkem", "dilithium", "ml-dsa", "mldsa",
                "falcon", "sphincs", "slh-dsa", "slhdsa", "ntru", "bike", "hqc"}
    out = _io.StringIO()
    w = _csv.writer(out)
    # key_bits is a real column now, so the export states the observed key size instead of leaving
    # an auditor to assume one. An empty cell means the size was not observed.
    w.writerow(["host", "port", "algorithm", "key_bits", "tls_version", "risk_level",
                "framework", "compliant", "finding", "scanned_at"])
    for r in facts:
        host, port = r["host"], r["port"]
        algo = r["algorithm_detail"] or r["algorithm"] or ""
        key_bits = r.get("key_bits") or ""
        tls, risk, ts = r["tls_version"] or "", r["risk_level"] or "", r["scanned_at"]
        algo_lower = algo.lower()
        if not algo:
            # No algorithm was observed (the scan failed, or the endpoint served no certificate).
            # "NO" with a blank algorithm name read as a finding about a known-vulnerable asset;
            # it is an unknown, and an auditor needs to see that difference.
            compliant_cell, finding = "UNKNOWN", (
                f"Endpoint cryptography was not observed; compliance with {framework} is unknown"
            )
        elif any(s in algo_lower for s in pqc_safe):
            compliant_cell, finding = "YES", "PQC-safe"
        else:
            compliant_cell, finding = "NO", f"{algo} is quantum-vulnerable under {framework}"
        w.writerow([host, port, algo, key_bits, tls, risk, framework, compliant_cell, finding, ts])
    from fastapi.responses import Response as _Resp
    fname = f"compliance-{framework.lower()}.csv"
    return _Resp(
        content=out.getvalue(),
        media_type="text/csv",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


