# WAVE 13 — PLATFORM-WIDE ASSET SEARCH
# ═══════════════════════════════════════════════════════════════════════════════

@app.get("/search")
@app.get("/v1/search")
def api_search(request: Request, q: str = "", limit: int = 50):
    """Full-text search across assets, algorithms, remediations, and findings."""
    _require_role(request, ["viewer", "analyst", "admin", "owner"],
                  action="search", resource_type="organization", resource_id="*")
    org_id = current_organization_id()
    if not q or len(q.strip()) < 2:
        return {"api_version": "v1", "query": q, "results": [], "total": 0}

    term = q.strip().lower()
    results = []
    unavailable: List[Dict[str, str]] = []

    with _db() as db:
        # Search scanned assets. The previous query hit `scans` with org_id/host/scan_time/
        # cert_subject — none of which exist there — so it always raised and, swallowed by the
        # except, search never returned a single asset. Filter in Python over the per-asset facts;
        # the result set is one row per asset, so this stays cheap.
        try:
            for r in _latest_asset_scan_facts(org_id, limit=5000):
                haystack = " ".join(str(r.get(k) or "") for k in
                                    ("host", "asset_key", "algorithm", "sig_algorithm",
                                     "tls_version", "risk_level", "owner", "team", "environment")).lower()
                if term not in haystack:
                    continue
                results.append({
                    "type": "asset",
                    "title": r["asset_key"],
                    "subtitle": f"{r['algorithm'] or ''} · {r['tls_version'] or ''} · {r['risk_level'] or ''}",
                    "risk": r["risk_level"] or "unknown",
                    "timestamp": r["scanned_at"] or "",
                    "data": r,
                })
                if len(results) >= limit:
                    break
        except (_pg_pool.PoolError, psycopg2.OperationalError):
            raise
        except Exception as exc:
            unavailable.append({"metric": "search.assets", "reason": f"Query failed: {exc.__class__.__name__}"})

        # Search remediations. `remediations` is a core table, so on a Postgres deployment it is
        # not in the local SQLite file db.execute() opens: the query raised every time and this
        # search silently returned no remediation hits at all. list_remediations routes to the
        # right dialect and applies the same free-text filter in SQL.
        try:
            for r in list_remediations(text_query=term, limit=max(1, limit // 2)):
                rid = str(r.get("id") or "")
                status = str(r.get("status") or "")
                results.append({
                    "type": "remediation",
                    "title": r.get("vulnerability") or f"Remediation {rid[:8]}",
                    "subtitle": f"Status: {status or '?'} · Host: {r.get('asset_key') or '?'} · Priority: {status or '?'}",
                    "risk": status or "medium",
                    "timestamp": str(r.get("created_at") or ""),
                    "data": {"id": r.get("id"), "title": r.get("vulnerability") or "",
                             "description": r.get("suggested_fix") or "", "status": status,
                             "priority": status, "target_host": r.get("asset_key") or "",
                             "created_at": str(r.get("created_at") or "")},
                })
        except (_pg_pool.PoolError, psycopg2.OperationalError):
            raise
        except Exception as exc:
            unavailable.append({"metric": "search.remediations", "reason": f"Query failed: {exc.__class__.__name__}"})

        # Search security intents
        try:
            irows = db.execute(
                """SELECT id, name, intent_text, status, created_at
                   FROM security_intents WHERE org_id=?
                   AND (LOWER(name) LIKE ? OR LOWER(intent_text) LIKE ?)
                   ORDER BY created_at DESC LIMIT 10""",
                (org_id, f"%{term}%", f"%{term}%")
            ).fetchall()
            for r in irows:
                results.append({
                    "type": "security_intent",
                    "title": r["name"] or "Security Intent",
                    "subtitle": f"Status: {r['status'] or 'draft'} · {(r['intent_text'] or '')[:80]}",
                    "risk": "info",
                    "timestamp": r["created_at"] or "",
                    "data": dict(r),
                })
        except sqlite3.OperationalError as exc:
            if "no such table" not in str(exc).lower():
                unavailable.append({"metric": "search.security_intents",
                                    "reason": f"Query failed: {exc.__class__.__name__}"})
        except Exception as exc:
            unavailable.append({"metric": "search.security_intents",
                                "reason": f"Query failed: {exc.__class__.__name__}"})

    # Sort: risk first, then timestamp
    risk_order = {"critical": 0, "high": 1, "medium": 2, "low": 3, "info": 4, "unknown": 5}
    results.sort(key=lambda x: (risk_order.get(x["risk"], 5), x.get("timestamp", "")))
    results = results[:limit]

    return {
        "api_version": "v1",
        "query": q,
        "total": len(results),
        "results": results,
        "unavailable": unavailable,
    }


