# ═══════════════════════════════════════════════════════════════════════════════

@app.get("/health/full")
@app.get("/v1/health/full")
def api_health_full(request: Request):
    """Comprehensive platform health — checks DB, all service imports, key endpoints."""
    from datetime import datetime as _dt, timezone as _tz
    start = _dt.now(_tz.utc)

    services_ok = []
    services_warn = []

    # DB check
    try:
        with _db() as db:
            count = db.execute("SELECT COUNT(*) FROM scans").fetchone()[0]
        services_ok.append({"name": "database", "status": "ok", "detail": f"{count} scan rows"})
    except Exception as e:
        services_warn.append({"name": "database", "status": "error", "detail": str(e)})

    # Key service imports
    for svc in [
        "services.fips_pqc", "services.peer_benchmark", "services.qday_forecast",
        "services.roi_calculator", "services.compliance_mapping", "services.crypto_agility",
        "services.pqc_codegen", "services.migration_velocity", "services.emergency_response",
        "services.ai_agent", "services.board_risk", "services.cbom",
    ]:
        try:
            __import__(svc)
            services_ok.append({"name": svc, "status": "ok"})
        except Exception as e:
            services_warn.append({"name": svc, "status": "error", "detail": str(e)[:120]})

    # AI API key
    import os as _os2
    _has_anthropic = bool(_os2.getenv("ANTHROPIC_API_KEY"))
    _has_openai = bool(_os2.getenv("OPENAI_API_KEY"))
    if _has_anthropic:
        services_ok.append({"name": "ai_api_key", "status": "ok", "detail": "ANTHROPIC_API_KEY configured"})
    elif _has_openai:
        services_ok.append({"name": "ai_api_key", "status": "ok", "detail": "OPENAI_API_KEY configured"})
    else:
        services_warn.append({"name": "ai_api_key", "status": "warning",
                               "detail": "No AI API key set — set ANTHROPIC_API_KEY or OPENAI_API_KEY"})

    elapsed_ms = round((_dt.now(_tz.utc) - start).total_seconds() * 1000)
    overall = "healthy" if not services_warn else "degraded"

    return {
        "api_version": "v1",
        "status": overall,
        "elapsed_ms": elapsed_ms,
        "services_ok": len(services_ok),
        "services_warn": len(services_warn),
        "checks": services_ok + services_warn,
        "timestamp": start.isoformat(),
    }


