@app.post("/scan-schedules/{schedule_id}/run")
@app.post("/v1/scan-schedules/{schedule_id}/run")
def api_sched_run_now(schedule_id: str, request: Request):
    """Manually trigger a schedule immediately (does not affect next_run_at)."""
    _require_role(request, allowed_roles=["admin", "owner", "member"], action="run", resource_type="scan_schedule")
    org_id = _org(request)
    with _db() as db:
        sched = _sched_get(db, schedule_id, org_id)
    if not sched:
        raise HTTPException(404, "Schedule not found")
    targets = sched.get("targets") or []
    if not targets:
        return {"message": "Schedule has no targets", "scanned": 0}
    # Run each target synchronously (capped at 5 for manual trigger)
    results = []
    for target in targets[:5]:
        try:
            host, port = parse_target(target)
            result = scan_host(host, port)
            if result:
                results.append({"host": host, "port": port, "risk_level": result.get("risk_level", "unknown")})
        except Exception as e:
            results.append({"host": target, "error": str(e)[:120]})
    return {
        "message": f"Manual run complete: {len(results)} target(s) scanned",
        "schedule_id": schedule_id,
        "scanned": len(results),
        "results": results,
    }






# ── Wave 15 lazy table init (idempotent, runs once per connection) ────────────
_w15_initialized = False

def _w15_ensure(db) -> None:
    """Ensure all Wave 15+16 tables exist. Idempotent — uses CREATE TABLE IF NOT EXISTS."""
    global _w15_initialized
    # Keyed by database, not a bare flag: a process that switches SQLite file (tests, a restore, a
    # re-pointed PQC_SCANNER_DB) used to keep the flag from the first database, so the new one never
    # got these tables and reads failed with "no such table: binary_scans".
    import db as _db_mod
    if _db_mod.schema_ensured("wave15_tables"):
        _w15_initialized = True
        return
    try:
        _tick_init(db)
        _sla_init(db)
        _wh_init(db)
        _kms_init(db)
        _pol_init(db)
        _sbom_init(db)
        _bin_init(db)
        _vw_init(db)
        _smtp_init(db)
        _dev_init(db)
        _miot_init(db)
        _db_mod.mark_schema_ensured("wave15_tables")
        _w15_initialized = True
    except Exception:
        pass


