class KMSCheckRequest(BaseModel):
    provider: str
    # AWS
    aws_access_key: Optional[str] = None
    aws_secret_key: Optional[str] = None
    aws_region: str = "us-east-1"
    # HashiCorp Vault
    vault_addr: Optional[str] = None
    vault_token: Optional[str] = None
    vault_mount: str = "transit"
    # Azure Key Vault
    vault_url: Optional[str] = None
    tenant_id: Optional[str] = None
    client_id: Optional[str] = None
    client_secret: Optional[str] = None

@app.post("/v1/kms/check")
@app.post("/kms/check")
def api_kms_check(body: KMSCheckRequest, request: Request):
    _require_role(request, ["admin", "owner"], action="kms.check", resource_type="kms")
    org_id = _org(request)
    with _db() as db:
        _w15_ensure(db)
        if body.provider == "aws_kms":
            if not body.aws_access_key or not body.aws_secret_key:
                raise HTTPException(400, "aws_access_key and aws_secret_key required")
            result = _kms_aws(db, org_id, body.aws_access_key, body.aws_secret_key, body.aws_region)
        elif body.provider == "hashicorp_vault":
            if not body.vault_addr or not body.vault_token:
                raise HTTPException(400, "vault_addr and vault_token required")
            result = _kms_vault(db, org_id, body.vault_addr, body.vault_token, body.vault_mount)
        elif body.provider == "azure_keyvault":
            if not all([body.vault_url, body.tenant_id, body.client_id, body.client_secret]):
                raise HTTPException(400, "vault_url, tenant_id, client_id, client_secret required")
            result = _kms_azure(db, org_id, body.vault_url, body.tenant_id, body.client_id, body.client_secret)
        else:
            raise HTTPException(400, f"Unknown provider: {body.provider}")
    return result

