def _vendor_assessment_error(exc: ValueError) -> HTTPException:
    """Map the vendor workflow's ValueErrors onto the right client status.

    services.vendor_workflow signals both "no such assessment" and "you cannot do
    that yet" by raising ValueError. The endpoints below were written as though
    it returned None instead, so `if not result: raise 404` was unreachable and
    FastAPI turned every one into a 500 -- a missing assessment reported as a
    server fault.
    """
    message = str(exc)
    if "not found" in message.lower():
        return HTTPException(status_code=404, detail="Assessment not found")
    return HTTPException(status_code=400, detail=message)


@app.post("/v1/vendor-assessments/{assessment_id}/send")
@app.post("/vendor-assessments/{assessment_id}/send")
def api_vendor_send(assessment_id: str, request: Request):
    _require_role(request, ["admin", "owner"], action="vendor.send", resource_type="vendor_assessment")
    org_id = _org(request)
    try:
        with _db() as db:
            _w15_ensure(db)
            result = _vw_send(db, assessment_id, org_id)
    except ValueError as exc:
        raise _vendor_assessment_error(exc) from exc
    if not result:
        raise HTTPException(status_code=404, detail="Assessment not found")
    return result


