class NotificationConfigRequest(BaseModel):
    smtp_host: Optional[str] = None
    # None, like every other field here. Defaulting to 587 made an omitted port
    # indistinguishable from one set to 587, so a partial save reset a custom
    # port back to the default. The 587 fallback belongs in save_config, which
    # already applies it.
    smtp_port: Optional[int] = None
    smtp_user: Optional[str] = None
    smtp_password: Optional[str] = None
    smtp_from: Optional[str] = None
    smtp_to: Optional[List[str]] = None
    smtp_enabled: Optional[bool] = None
    slack_webhook_url: Optional[str] = None
    slack_channel: Optional[str] = None
    slack_enabled: Optional[bool] = None

