@app.get("/v1/notifications/config")
@app.get("/notifications/config")
def api_notify_config_get(request: Request):
    _require_role(request, ["admin", "owner"], action="notifications.read", resource_type="notification")
    org_id = _org(request)
    with _db() as db:
        _w15_ensure(db)
        cfg = _smtp_get_cfg(db, org_id)
    return {"config": cfg or {}}


@app.post("/v1/notifications/config")
@app.post("/notifications/config")
def api_notify_config_save(body: NotificationConfigRequest, request: Request):
    _require_role(request, ["admin", "owner"], action="notifications.write", resource_type="notification")
    org_id = _org(request)
    with _db() as db:
        _w15_ensure(db)
        # Merge, do not replace. smtp_notify.save_config is a full upsert that
        # falls back to its own defaults for anything not passed, so sending a
        # partial body -- which is what the console does -- silently reset the
        # omitted fields: smtp_host to null, smtp_port to 587, and both enabled
        # flags to false. The operator saw "saved" and lost their mail server.
        current = _smtp_get_cfg(db, org_id) or {}
        merged = {k: v for k, v in current.items()
                  if k in NotificationConfigRequest.model_fields and v is not None}
        merged.update({k: v for k, v in body.model_dump().items() if v is not None})
        cfg = _smtp_save_cfg(db, org_id, **merged)
    return {"status": "saved", "config": cfg}


@app.post("/v1/notifications/test")
@app.post("/notifications/test")
def api_notify_test(body: NotificationTestRequest, request: Request):
    _require_role(request, ["admin", "owner"], action="notifications.test", resource_type="notification")
    org_id = _org(request)
    with _db() as db:
        _w15_ensure(db)
        if body.channel == "email":
            result = _smtp_send_email(db, org_id, "PQC Scanner Test", "<p>Test notification from PQC Scanner.</p>", "test")
            return {"email": result}
        elif body.channel == "slack":
            result = _smtp_send_slack(db, org_id, "Test notification from PQC Scanner.", "test", "info")
            return {"slack": result}
        else:
            result = _smtp_notify_all(db, org_id, "PQC Scanner Test",
                                      "Test notification from PQC Scanner.",
                                      "<p>Test notification from PQC Scanner.</p>", "test", "info")
            return result


