@app.post("/v1/mobile-iot/scan")
@app.post("/mobile-iot/scan")
async def api_miot_scan(request: Request):
    from fastapi import UploadFile
    import io as _io
    org_id = _org(request)
    content_type = request.headers.get("content-type", "")
    if "multipart/form-data" in content_type:
        form = await request.form()
        file = form.get("file")
        if not file:
            return JSONResponse(status_code=422, content={"detail": "file field required"})
        filename = str(getattr(file, "filename", "upload.bin") or "upload.bin")
        data = await file.read()
    else:
        data = await request.body()
        filename = request.headers.get("x-filename", "upload.bin")
    if not data:
        return JSONResponse(status_code=422, content={"detail": "empty file"})
    with _db() as db:
        _w15_ensure(db)
        result = _miot_scan(db, org_id, filename, data)
    return result


