@app.get("/v1/evidence/frameworks")
@app.get("/evidence/frameworks")
def api_evidence_frameworks():
    return {"frameworks": _evidence_frameworks()}


@app.post("/v1/evidence/build")
@app.post("/evidence/build")
async def api_evidence_build(request: Request):
    from fastapi.responses import Response as _FResponse
    body = await request.json()
    org_id = _org(request)
    framework = body.get("framework", "nist_sp_800_208")

    # Gather data from existing endpoints inline
    scan_data: dict = {}
    cbom_data: dict = {}
    fips_data: dict = {}
    gap_data: dict = {}
    intents_data: dict = {}
    remediation_data: dict = {}
    drift_data: dict = {}

    # The per-asset facts, through the dialect router. The query this replaces read `scan_results`
    # from the local SQLite file (empty on a Postgres deployment) *and* unpacked r[3] from a
    # three-column SELECT, so it raised IndexError on every deployment and the `except: pass` left
    # the evidence pack's asset inventory empty -- in a document an auditor is handed.
    scan_data = {"assets": [
        {"key": f["asset_key"], "algorithm": f["algorithm"], "risk": f["risk_level"], "port": f["port"]}
        for f in _latest_asset_scan_facts(org_id, limit=200)
    ]}
    with _db() as db:
        try:
            from services.drift_sentinel import list_drift_events as _lde, init_tables as _di
            _di(db)
            drift_data = {"events": _lde(db, org_id, 100)}
        except Exception:
            pass
        try:
            from services.security_intent_store import list_intents as _li
            intents_data = {"intents": _li(db, org_id, limit=50)}
        except Exception:
            pass

    zip_bytes = _evidence_build(
        org_id=org_id,
        framework_key=framework,
        scan_data=scan_data,
        cbom_data=cbom_data,
        fips_data=fips_data,
        gap_data=gap_data,
        intents_data=intents_data,
        remediation_data=remediation_data,
        drift_data=drift_data,
    )
    filename = f"pqc-evidence-{framework}-{org_id}.zip"
    return _FResponse(
        content=zip_bytes,
        media_type="application/zip",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


