# ============================================================
# Wave 17 — Q-Day Live Countdown
# ============================================================

@app.get("/v1/qday/countdown")
@app.get("/qday/countdown")
def api_qday_countdown(request: Request):
    org_id = _org(request)

    # Scenario years come from the Q-Intel model (services/q_intel.py), the
    # platform's single source of Q-Day years; the response carries model_basis.
    from services.q_intel import (
        _load_milestones as _qi_load_milestones,
        model_basis_for as _qi_model_basis_for,
        q_day_reference as _qi_q_day_reference,
    )
    _qi_rows = _qi_load_milestones()
    reference = _qi_q_day_reference("rsa2048", _qi_rows)
    estimates = {
        "conservative": reference["conservative_year"],
        "median": reference["expected_year"],
        "optimistic": reference["accelerated_year"],
    }
    now_dt = datetime.now(timezone.utc)
    current_year = now_dt.year

    def _secs_to(year: Optional[int]) -> Optional[int]:
        if year is None:
            return None
        return max(0, int((datetime(int(year), 1, 1, tzinfo=timezone.utc) - now_dt).total_seconds()))

    countdown = {k: _secs_to(v) for k, v in estimates.items()}

    def _target_status(year: int) -> str:
        # A target date passing says nothing about whether anyone met it.
        if year < current_year:
            return "target_date_passed"
        if year == current_year:
            return "target_year_current"
        return "upcoming"

    cnsa_source = "NSA, CNSA 2.0 algorithms advisory: https://media.defense.gov/2025/May/30/2003728741/-1/-1/0/CSA_CNSA_2.0_ALGORITHMS.PDF"
    cnsa_note = "Target date for U.S. National Security Systems; this platform does not track whether your organization met it."
    milestones = [
        {"year": 2024, "event": "NIST publishes FIPS 203, 204 and 205 (ML-KEM, ML-DSA, SLH-DSA)",
         "status": "published", "kind": "standard", "source": "https://csrc.nist.gov/pubs/fips/203/final"},
        {"year": 2025, "event": "CNSA 2.0 target: software/firmware signing, web browsers/servers and cloud services support and prefer CNSA 2.0 algorithms",
         "status": _target_status(2025), "kind": "cnsa_2_0_target", "note": cnsa_note, "source": cnsa_source},
        {"year": 2026, "event": "CNSA 2.0 target: traditional networking equipment (VPNs, routers) supports and prefers CNSA 2.0 algorithms",
         "status": _target_status(2026), "kind": "cnsa_2_0_target", "note": cnsa_note, "source": cnsa_source},
        {"year": 2027, "event": "CNSA 2.0 target: operating systems support and prefer CNSA 2.0 algorithms",
         "status": _target_status(2027), "kind": "cnsa_2_0_target", "note": cnsa_note, "source": cnsa_source},
        {"year": 2030, "event": "CNSA 2.0 target: software/firmware signing and networking equipment use CNSA 2.0 algorithms exclusively",
         "status": _target_status(2030), "kind": "cnsa_2_0_target", "note": cnsa_note, "source": cnsa_source},
        {"year": 2033, "event": "CNSA 2.0 target: web browsers/servers, cloud services and operating systems use CNSA 2.0 algorithms exclusively",
         "status": _target_status(2033), "kind": "cnsa_2_0_target", "note": cnsa_note, "source": cnsa_source},
        {"year": 2035, "event": "NSM-10 goal: mitigate as much quantum risk as feasible in U.S. federal systems by 2035",
         "status": _target_status(2035), "kind": "policy_goal", "source": "National Security Memorandum 10 (May 2022)"},
    ]
    for scenario, key, pct in (("accelerated", "optimistic", 10), ("expected", "median", 50), ("conservative", "conservative", 90)):
        if estimates[key] is not None:
            milestones.append({
                "year": estimates[key],
                "event": f"Q-Intel model, {scenario} scenario: {pct}% modelled probability that RSA-2048 is breakable",
                "status": "model_projection",
                "kind": "model",
            })
    milestones.sort(key=lambda m: (m["year"], m["kind"] == "model"))

    # Org readiness from DB
    # Readiness from the inventory and the newest scan per asset, through the dialect router.
    # The two COUNT(*)s this replaces ran against the local SQLite file, so on a Postgres
    # deployment both were zero and the timeline reported 0% readiness for every customer. The
    # second one also counted an asset as ready if *any* of its historical scans was not
    # high/critical, rather than its current one.
    readiness_unavailable: List[Dict[str, str]] = []
    total_assets = _aux(readiness_unavailable, "asset_inventory", count_assets, 0)
    risk = _aux(readiness_unavailable, "asset_risk", lambda: _asset_risk_counts(org_id), {})
    scanned = int(risk.get("total") or 0)
    denominator = max(int(total_assets or 0), scanned)
    readiness_pct = round(100 * (scanned - int(risk.get("at_risk") or 0)) / denominator) if denominator else None

    return {
        "estimates": estimates,
        "countdown_seconds": countdown,
        "milestones": milestones,
        # None, not 0, when there is nothing to measure: a workspace with no assets is not 0% ready.
        "org_readiness_pct": readiness_pct,
        "org_readiness_basis": (
            f"{scanned - int(risk.get('at_risk') or 0)} of {denominator} asset(s) whose newest scan is "
            f"neither high nor critical risk" if denominator else
            "No assets are known for this organization yet, so readiness cannot be measured."
        ),
        "unavailable": readiness_unavailable,
        # Traffic harvested today stays decryptable later, so HNDL risk remains
        # active for as long as classical key exchange is in use.
        "hndl_risk": "ACTIVE",
        "reference_years": reference,
        "scenario_analysis": {
            "conservative": {
                "year": estimates["conservative"],
                "label": "Conservative planning scenario",
                "description": (
                    "Year the Q-Intel model reaches a 90% probability that RSA-2048 is breakable. "
                    "An outer planning bound for long-lived data and multi-year migration cycles, not a prediction."
                ),
                "planning_implication": "Begin migration planning immediately for systems handling data with >10-year confidentiality requirements.",
            },
            "expected": {
                "year": estimates["median"],
                "label": "Expected planning scenario",
                "description": (
                    "Year the Q-Intel model reaches a 50% probability that RSA-2048 is breakable, computed from "
                    "recorded hardware milestones and a stated growth assumption. It is not an expert consensus."
                ),
                "planning_implication": "PQC migration should be substantially complete before this date for critical systems.",
            },
            "accelerated": {
                "year": estimates["optimistic"],
                "label": "Accelerated threat scenario",
                "description": (
                    "Year the Q-Intel model reaches a 10% probability that RSA-2048 is breakable. "
                    "Use it to stress-test plans against faster-than-assumed hardware progress."
                ),
                "planning_implication": "High-risk systems (financial keys, classified data) should already be migrated or under active migration.",
            },
        },
        "methodology_note": (
            "Scenario years come from the Q-Intel model; see model_basis for its assumptions and sources. "
            "They are illustrative projections, not predictions: the actual date of a cryptographically relevant "
            "quantum computer is unknown. CNSA 2.0 entries are target dates, and their status says only whether "
            "the date has passed."
        ),
        "model_basis": _qi_model_basis_for(_qi_rows),
    }




# ============================================================
# Wave 17 — Built-in Auth Issuer endpoints
# ============================================================

_RATE_AUTH = os.getenv("PQC_RATE_LIMIT_AUTH", "10/minute").strip()


def _require_auth_issuer_enabled() -> None:
    if not AUTH_ISSUER_ENABLED:
        raise HTTPException(status_code=404, detail="Built-in password authentication is disabled.")


async def _auth_input(request: Request, failure_event: str, method="password"):
    try:
        raw = bytearray()
        async for chunk in request.stream():
            if len(raw) + len(chunk) > 8192:
                raise HTTPException(413, "Authentication request too large")
            raw.extend(chunk)
        body = json.loads(raw)
        if not isinstance(body, dict):
            raise ValueError()
        return body
    except (ValueError, UnicodeError, HTTPException) as exc:
        status = exc.status_code if isinstance(exc, HTTPException) else 400
        await run_in_threadpool(_auth_journal, request, failure_event, method=method, status_code=status, required=False)
        raise HTTPException(status, "Invalid authentication request") from None


@app.post("/auth/login")
@limiter.limit(_RATE_AUTH)
async def auth_login(request: Request):
    """Issue credentials only after the actual login outcome is durably recorded."""
    _require_auth_issuer_enabled()
    body = await _auth_input(request, "login.invalid_request")
    email, password = body.get("email"), body.get("password")
    try:
        encoded_password = password.encode("utf-8") if isinstance(password, str) else b""
        if isinstance(email, str):
            email.encode("utf-8")
    except UnicodeError:
        encoded_password = b""
    if (not isinstance(email, str) or not isinstance(password, str) or not email.strip()
            or not encoded_password or len(email) > 320 or len(encoded_password) > 72):
        await run_in_threadpool(_auth_journal, request, "login.invalid_request", status_code=400, required=False)
        raise HTTPException(400, "Valid email and password are required")

    def authenticate():
        try:
            with _db() as db:
                result = _issuer_login(db, email.strip(), password)
                if not result:
                    _auth_journal(request, "login.failure", subject=email, status_code=401, required=False)
                    raise HTTPException(401, "Invalid credentials")
                try:
                    _auth_journal(request, "login.success", user=result["user"], subject=email)
                except HTTPException:
                    # Never leave a newly minted refresh token usable after a failed audit commit.
                    _issuer_revoke(db, result["refresh_token"])
                    raise
                return result
        except HTTPException:
            raise
        except Exception:
            _auth_journal(request, "login.unavailable", subject=email, status_code=503, required=False)
            raise HTTPException(503, "Authentication is temporarily unavailable; check server configuration and storage") from None
    result = await run_in_threadpool(authenticate)
    return JSONResponse(result, headers={"Cache-Control": "no-store", "Pragma": "no-cache"})


@app.post("/auth/register")
@limiter.limit(_RATE_AUTH)
async def auth_register(request: Request):
    """Create a user account. Admin-only: the caller's role is authorized before anything is written.

    This endpoint previously trusted a caller-supplied "role" with no authorization check, so an
    unauthenticated request could mint an admin account. It now requires the admin role and
    validates the requested role against VALID_USER_ROLES.
    """
    _require_auth_issuer_enabled()
    _require_role(request, ["admin"], "auth.register", "user")
    org_id = _org(request)
    body = await request.json()
    email = str(body.get("email") or "").strip()
    password = str(body.get("password") or "")
    full_name = str(body.get("full_name") or "").strip()
    role = str(body.get("role") or "viewer").strip().lower()
    if not email or not password:
        raise HTTPException(status_code=400, detail="email and password required")
    if role not in VALID_USER_ROLES:
        raise HTTPException(
            status_code=400,
            detail=f"role must be one of: {', '.join(sorted(VALID_USER_ROLES))}",
        )
    try:
        with _db() as db:
            user = _issuer_create_user(db, email, password, full_name, role, org_id)
        return {"user": user}
    except ValueError as e:
        raise HTTPException(status_code=409, detail=str(e))


@app.get("/auth/me")
async def auth_me(request: Request):
    """Return the currently authenticated user (from Bearer token)."""
    _require_auth_issuer_enabled()
    auth_header = request.headers.get("authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token required")
    token = auth_header[7:]
    try:
        payload = _issuer_verify_token(token)
    except Exception:
        raise HTTPException(status_code=401, detail="Invalid or expired token")
    user_id = payload.get("sub")
    with _db() as db:
        user = _issuer_get_user(db, user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user


class SwitchOrganizationRequest(BaseModel):
    organization_id: str = Field(..., min_length=1, max_length=200)


@app.post("/auth/switch-organization")
@app.post("/v1/auth/switch-organization")
@limiter.limit(_RATE_AUTH)
async def auth_switch_organization(req: SwitchOrganizationRequest, request: Request):
    """Move a built-in account to another organization it belongs to, and mint a token for it.

    A token is scoped to exactly one tenant: every authorization decision compares the target
    organization with the org claim on the presented credential, so belonging to two organizations
    does not let one token act in both. This is how a member of several organizations changes which
    one they are working in -- explicitly, with an active membership checked at the moment of the
    switch, and with a new token issued for the new tenant.

    Accepting an invitation performs the same move automatically (services/platform_access.py), so
    an invitee's next token is scoped to the organization they were invited to instead of the one
    they happened to register in.
    """
    _require_auth_issuer_enabled()
    auth_header = request.headers.get("authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token required")
    try:
        payload = _issuer_verify_token(auth_header[7:])
    except Exception:
        raise HTTPException(status_code=401, detail="Invalid or expired token")
    user_id = str(payload.get("sub") or "")
    target = str(req.organization_id or "").strip()

    def switch():
        member = get_organization_member(target, user_id)
        if not member or str(member.get("status") or "").lower() != "active":
            raise HTTPException(status_code=403, detail="You are not an active member of that organization.")
        role = str(member.get("role") or "").strip().lower()
        with _db() as db:
            if not _issuer_set_user_org(db, user_id, target, role if role in VALID_USER_ROLES else ""):
                raise HTTPException(status_code=404, detail="No built-in account for this identity; the organization "
                                                            "claim comes from your identity provider.")
            user = _issuer_get_user(db, user_id)
        if not user or not user.get("is_active"):
            raise HTTPException(status_code=403, detail="This account is not active.")
        return _issuer_access_token({"id": user["id"], "email": user["email"], "role": user["role"],
                                     "org_id": user["org_id"], "full_name": user.get("full_name") or ""})

    access = await run_in_threadpool(switch)
    await run_in_threadpool(_audit_event, request, action="auth.switch_organization",
                            resource_type="organization", resource_id=target, decision="allow")
    return JSONResponse({"access_token": access, "token_type": "Bearer", "organization_id": target},
                        headers={"Cache-Control": "no-store"})


@app.post("/auth/refresh")
@limiter.limit(_RATE_AUTH)
async def auth_refresh(request: Request):
    """Record refresh separately from login; do not expose tokens to any logger."""
    _require_auth_issuer_enabled()
    body = await _auth_input(request, "refresh.failure", "refresh_token")
    token = body.get("refresh_token")
    if not isinstance(token, str) or not token or len(token) > 512:
        await run_in_threadpool(_auth_journal, request, "refresh.failure", method="refresh_token", status_code=400, required=False)
        raise HTTPException(400, "refresh_token required")
    def refresh():
        from services.auth_issuer import refresh_token_owner
        try:
            with _db() as db:
                user = refresh_token_owner(db, token)
                access = _issuer_refresh(db, token) if user else None
        except Exception:
            _auth_journal(request, "refresh.failure", method="refresh_token", status_code=503, required=False)
            raise HTTPException(503, "Authentication storage is temporarily unavailable") from None
        if not access:
            _auth_journal(request, "refresh.failure", method="refresh_token", status_code=401, required=False)
            raise HTTPException(401, "Invalid or expired refresh token")
        _auth_journal(request, "refresh.success", method="refresh_token", user=user)
        return access
    access = await run_in_threadpool(refresh)
    return JSONResponse({"access_token": access, "token_type": "Bearer"}, headers={"Cache-Control": "no-store"})


@app.post("/auth/logout")
@limiter.limit(_RATE_AUTH)
async def auth_logout(request: Request):
    """Revoke the supplied refresh token; existing access tokens retain their expiry."""
    _require_auth_issuer_enabled()
    body = await _auth_input(request, "logout.no_session", "refresh_token")
    token = body.get("refresh_token")
    if not isinstance(token, str) or not token or len(token) > 512:
        await run_in_threadpool(_auth_journal, request, "logout.no_session", method="refresh_token", status_code=400, required=False)
        raise HTTPException(400, "refresh_token required")
    def logout():
        from services.auth_issuer import refresh_token_owner
        try:
            with _db() as db:
                user = refresh_token_owner(db, token)
                _issuer_revoke(db, token)
        except Exception:
            _auth_journal(request, "logout.failure", method="refresh_token", status_code=503, required=False)
            raise HTTPException(503, "Session revocation failed; retry logout when authentication storage is available") from None
        # Revoke even if the audit sink is unavailable; do not keep a session renewable for logging.
        recorded = _auth_journal(request, "logout.revoked" if user else "logout.no_session",
                                 method="refresh_token", user=user, required=False)
        return {"ok": True, "refresh_token_revoked": bool(user), "access_tokens_revoked": False, "audit_recorded": bool(recorded)}
    return JSONResponse(await run_in_threadpool(logout), headers={"Cache-Control": "no-store"})


def _require_issuer_admin(request: Request) -> tuple[Dict[str, Any], str]:
    """Verified built-in-issuer admin token and its organization.

    These routes used to skip the check entirely when no Bearer header was sent, and read the
    organization from x-org-id, so an anonymous caller could list, promote or deactivate users in any
    organization. The token is now mandatory and its org_id claim is the only organization accepted.
    """
    auth_header = request.headers.get("authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token required")
    try:
        payload = _issuer_verify_token(auth_header[7:])
    except Exception:
        raise HTTPException(status_code=401, detail="Invalid token") from None
    if _session_revocation.is_revoked(payload):
        raise HTTPException(status_code=401, detail="Token has been revoked")
    if payload.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin role required")
    org_id = str(payload.get("org_id") or "").strip()
    if not org_id:
        raise HTTPException(status_code=403, detail="Token carries no organization")
    return payload, org_id


@app.get("/auth/users")
async def auth_list_users(request: Request):
    """List users in the caller's organization (admin only)."""
    _require_auth_issuer_enabled()
    _, org_id = _require_issuer_admin(request)
    with _db() as db:
        users = _issuer_list_users(db, org_id)
    return {"users": users}


@app.put("/auth/users/{user_id}/role")
async def auth_update_role(user_id: str, request: Request):
    """Update a user's role within the caller's organization (admin only)."""
    _require_auth_issuer_enabled()
    _, org_id = _require_issuer_admin(request)
    try:
        body = await request.json()
    except Exception:
        body = {}
    role = str((body or {}).get("role") or "").strip().lower() if isinstance(body, dict) else ""
    if not role:
        raise HTTPException(status_code=400, detail="role required")
    if role not in VALID_USER_ROLES:
        raise HTTPException(status_code=400, detail=f"role must be one of: {', '.join(sorted(VALID_USER_ROLES))}")
    with _db() as db:
        ok = _issuer_update_role(db, user_id, role, org_id)
    if not ok:
        raise HTTPException(status_code=404, detail="User not found")
    return {"ok": True}


@app.post("/auth/users/{user_id}/deactivate")
async def auth_deactivate_user(user_id: str, request: Request):
    """Deactivate a user account in the caller's organization (admin only)."""
    _require_auth_issuer_enabled()
    _, org_id = _require_issuer_admin(request)
    with _db() as db:
        ok = _issuer_deactivate(db, user_id, org_id)
    if not ok:
        raise HTTPException(status_code=404, detail="User not found")
    return {"ok": True}


@app.post("/auth/change-password")
async def auth_change_password(request: Request):
    """Change the authenticated user's password."""
    _require_auth_issuer_enabled()
    auth_header = request.headers.get("authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token required")
    try:
        payload = _issuer_verify_token(auth_header[7:])
    except Exception:
        raise HTTPException(status_code=401, detail="Invalid token")
    user_id = payload.get("sub")
    body = await request.json()
    old_password = str(body.get("old_password") or "")
    new_password = str(body.get("new_password") or "")
    if not old_password or not new_password:
        raise HTTPException(status_code=400, detail="old_password and new_password required")
    try:
        with _db() as db:
            ok = _issuer_change_password(db, user_id, old_password, new_password)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    if not ok:
        raise HTTPException(status_code=401, detail="Incorrect current password")
    return {"ok": True}


# Register the Postgres schemas created lazily on first request, so `apply_deferred_schemas()` can
# create them during a migration run with an owner role. The runtime role under row-level security
# has no DDL rights; see db_postgres.tolerate_missing_ddl_privilege for what happens if it tries.
register_deferred_schema("platform_admin", _ensure_platform_admin_schema)
register_deferred_schema("security_truth", _ensure_security_truth_tables)
# platform_traffic_events and platform_feature_state_records were the one lazily
# created pair missing from this list, so the migration step never made them.
# Under the least-privilege runtime role the hardening guide requires, nothing
# else can either -- leaving PQC_TRAFFIC_PERSIST_TO_DB=1, which the production
# checklist mandates, unable to write, and /platform/state/coverage unable to
# read its archive count.
register_deferred_schema("platform_state", _ensure_platform_state_schema)
register_deferred_schema("security_journal", _security_journal.init_tables)
register_deferred_schema("usage_rollups", _usage_rollups.init_tables)
register_deferred_schema("analytics_snapshots", _analytics_snapshots.init_tables)
# admin_users, admin_invitations, admin_audit_log and admin_rate_limits. They are tenant tables --
# the customer's user list, its pending invitations and its administrative audit trail -- and they
# are now under row-level security (services/postgres_rls.py, tenant column `org_id`). A policy can
# only be applied to a table that exists, so the migration has to create them with the owner role;
# leaving them to be made lazily meant the RLS step skipped them with a NOTICE and the verifier
# reported them missing.
register_deferred_schema("admin_console", _admin_console_init_tables)

# =============================================================================
# Feedback — the one signal the platform could not collect
#
# Everything else in the admin console is inferred from telemetry, which records
# what people did and never why. These endpoints let a user say something back,
# and let the operator triage it.
# =============================================================================

class FeedbackRequest(BaseModel):
    message: str = Field(..., min_length=1, max_length=4000)
    category: str = Field("other", max_length=32)
    rating: Optional[int] = Field(None, ge=1, le=5)
    page: str = Field("", max_length=512)
    email: str = Field("", max_length=256)


class FeedbackStatusRequest(BaseModel):
    status: str = Field(..., max_length=32)
    admin_note: str = Field("", max_length=2000)


@app.post("/v1/feedback")
@app.post("/feedback")
def api_feedback_submit(body: FeedbackRequest, request: Request):
    """Any signed-in user may leave feedback about the product."""
    actor = _require_role(
        request,
        allowed_roles=["viewer", "operator", "admin"],
        action="feedback.submit",
        resource_type="feedback",
        resource_id="",
    )
    org_id = _org(request)
    try:
        created = _feedback.submit(
            org_id,
            body.message,
            user_id=str(actor.get("actor_id") or ""),
            email=body.email,
            category=body.category,
            rating=body.rating,
            page=body.page,
            user_agent=str(request.headers.get("user-agent") or ""),
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"api_version": "v1", "submitted": True, "feedback": created}


@app.get("/v1/feedback")
@app.get("/feedback")
def api_feedback_list_own(
    request: Request,
    limit: int = Query(50, ge=1, le=200),
):
    """What this organization has sent. Scoped to the caller's own tenant."""
    _require_role(
        request,
        allowed_roles=["viewer", "operator", "admin"],
        action="feedback.read",
        resource_type="feedback",
        resource_id="",
    )
    org_id = _org(request)
    return {"api_version": "v1", "items": _feedback.list_feedback(org_id, limit=int(limit))}


@app.get("/platform/feedback")
def api_platform_feedback(
    request: Request,
    status: str = Query("", description="new | triaged | resolved | declined"),
    category: str = Query(""),
    organization_id: str = Query("", description="blank lists every tenant"),
    limit: int = Query(200, ge=1, le=500),
):
    """Cross-tenant feedback for the platform operator."""
    _require_platform_admin(request)
    return {
        "summary": _feedback.summary(organization_id),
        "items": _feedback.list_feedback(
            organization_id, status=status, category=category, limit=int(limit)
        ),
    }


@app.get("/platform/feedback/{feedback_id}")
def api_platform_feedback_item(
    feedback_id: int,
    request: Request,
    organization_id: str = Query("", description="blank reads across every tenant"),
):
    """One item by id, in the same shape the list returns.

    The admin portal deep-links to a single feedback item (#/feedback?id=12). Without this route it
    could only select an item that happened to be in the page it had loaded, so a link to an older
    item looked exactly like a link to a deleted one. A real 404 here is what lets the console say
    "this item no longer exists" and mean it.
    """
    _require_platform_admin(request)
    item = _feedback.get_feedback(feedback_id, organization_id)
    if not item:
        raise HTTPException(status_code=404, detail="Feedback item not found.")
    return {"feedback": item}


@app.patch("/platform/feedback/{feedback_id}")
def api_platform_feedback_status(feedback_id: int, body: FeedbackStatusRequest, request: Request):
    """Move one item through triage."""
    _require_platform_admin(request, _PLATFORM_ADMIN_WRITE_ROLES)
    try:
        updated = _feedback.set_status(feedback_id, body.status, body.admin_note)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    if not updated:
        raise HTTPException(status_code=404, detail="Feedback item not found.")
    _record_platform_admin_event(
        str(updated.get("organization_id") or ""),
        "platform.feedback_triaged",
        details={"feedback_id": feedback_id, "status": updated.get("status")},
    )
    return {"updated": True, "feedback": updated}


register_deferred_schema("feedback", _feedback.init_tables)

# The gateway control plane created its two tenant tables on first use only, so on a database where
